INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C1','kor',5,1,'u5',1,'관점의 뜻 — 사물이나 현상을 바라보는 태도나 방향, 처지를 관점이라고 하며, 관점은 언제나 옳은 하나의 정답이나 무언가를 재는 기준이 아니다',ARRAY['6국02-04 읽기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C2','kor',5,1,'u5',1,'같은 일도 바라보는 방향이 다르다 — 같은 일을 두고도 사람마다 무엇에 무게를 두느냐가 달라 생각이 달라지며, 서로 다른 말을 했다고 누군가 틀린 말을 한 것은 아니다',ARRAY['6국02-04 읽기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C3','kor',5,1,'u5',1,'여러 의견은 견주어 판단한다 — 여러 의견을 듣는 것과 그대로 따르는 것은 다르며, 다양한 의견을 받아들일 때는 우리 상황에 맞는지 견주어 판단한다',ARRAY['6국02-04 읽기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C4','kor',5,1,'u5',1,'여러 관점이 필요한 까닭 — 혼자 생각하면 놓치는 부분이 생기고 잘못 판단할 수 있으므로, 하나의 문제를 여러 방향에서 따져 보려고 여러 관점의 글을 읽는다',ARRAY['6국02-04 읽기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C5','kor',5,1,'u5',1,'토의의 뜻 — 토의는 이기는 말하기가 아니라 서로 다른 생각을 모아 더 나은 답을 찾는 일이므로 협력이 없으면 토의가 되지 않는다',ARRAY['6국01-06 듣기·말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C6','kor',5,1,'u5',1,'이 단원의 두 갈래 — 이 단원에서는 다양한 관점의 글을 읽고 문제 해결에 활용하기와 다양한 관점을 나누고 협력하며 토의하기를 배우며, 읽기에서 찾은 관점이 토의의 재료가 된다',ARRAY['6국02-04 읽기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C7','kor',5,1,'u5',2,'제목으로 관점 짐작하기 — 글을 읽기 전에 제목에 쓰인 낱말이 주는 느낌을 보고 글쓴이의 관점을 미리 짐작할 수 있으며, 제목이 달라 보이면 두 글쓴이의 관점이 다를 수 있다',ARRAY['6국02-04 읽기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C8','kor',5,1,'u5',2,'표현에 관점이 스민다 — 같은 대상을 다루어도 글쓴이가 고른 낱말과 문장이 다르며, 이런 표현을 살펴보면 글쓴이의 관점을 알 수 있다',ARRAY['6국02-04 읽기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C9','kor',5,1,'u5',2,'사진이나 그림에도 관점이 드러난다 — 글과 함께 실린 사진이나 그림이 무엇을 담았는지에도 글쓴이의 생각이 드러나므로 관점을 파악할 때 함께 살핀다',ARRAY['6국02-04 읽기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C10','kor',5,1,'u5',2,'끝까지 읽고 판단한다 — 문제점을 짚은 글도 대상을 없애자는 것이 아니라 방식을 고치자는 관점일 수 있으므로, 몇 낱말만 보고 단정하지 않고 끝까지 읽고 판단한다',ARRAY['6국02-04 읽기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C11','kor',5,1,'u5',2,'관점을 파악하는 방법 — 제목 · 사진이나 그림 · 표현 · 내용을 살펴 관점을 파악하며, 이 넷은 꼭 지켜야 하는 차례가 아니라 살펴볼 곳의 목록이어서 내용을 충분히 파악하는 것만으로도 관점을 알 수 있다',ARRAY['6국02-04 읽기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C12','kor',5,1,'u5',2,'관점이 다른 것은 틀린 것이 아니다 — 겪은 일 · 알고 있는 것 · 속한 문화가 다르면 같은 것을 보아도 다르게 생각하게 되므로, 관점은 맞고 틀림이 아니라 서로 다름이다',ARRAY['6국02-04 읽기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C13','kor',5,1,'u5',2,'관점이 다른 글을 함께 읽으면 좋은 점 — 관점이 다른 글을 함께 읽으면 하나의 문제를 여러 관점으로 생각하고, 내용을 깊이 이해하며, 몰랐던 면을 알고, 내 생각을 다시 살펴볼 수 있다',ARRAY['6국02-04 읽기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C14','kor',5,1,'u5',2,'한쪽을 골라야 하는 것은 아니다 — 두 글을 읽었다고 둘 중 하나를 골라야 하는 것은 아니며, 두 관점을 합쳐 생각하거나 또 다른 나만의 관점을 세울 수 있다',ARRAY['6국02-04 읽기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C15','kor',5,1,'u5',4,'문제 상황을 다룬 여러 글 — 같은 일을 두고 좋은 점을 말한 글 · 문제점을 짚은 글 · 지킬 규칙을 알린 안내문처럼 여러 글이 나올 수 있고, 저마다 보여 주는 면이 다르다',ARRAY['6국02-04 읽기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C16','kor',5,1,'u5',4,'글 속 낱말의 뜻 — 대여는 물건을 빌려줌, 반납은 빌린 것을 도로 돌려줌, 훼손은 헐거나 깨뜨려 못 쓰게 함, 관리는 맡아서 돌보고 살핌이다',ARRAY['6국02-04 읽기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C17','kor',5,1,'u5',4,'안내문에 담긴 관점 — 안내문처럼 짧은 글에도 관점이 담기며, 「모두의 우산입니다. 소중히 써 주세요」에는 모두의 물건이니 함께 지키자는 관점이 드러난다',ARRAY['6국02-04 읽기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C18','kor',5,1,'u5',4,'자료를 평가하는 네 기준 — 읽은 글은 제목이 내용을 잘 나타내는지 · 표현과 그림이 관점을 뒷받침하는지 · 내용을 신뢰할 수 있는지 · 내 생각과 비슷한 점이 있는지로 평가한다',ARRAY['6국02-04 읽기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C19','kor',5,1,'u5',4,'신뢰할 수 있는지 판단하는 근거 — 확인할 수 있는 숫자나 사실을 들었는지 · 직접 살펴본 내용인지 · 한쪽 면만 부풀리지 않았는지 · 출처가 분명한지로 판단하며, 길고 어려운 글이나 내 생각과 같은 편인 글이라고 믿을 만한 것은 아니다',ARRAY['6국02-04 읽기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C20','kor',5,1,'u5',4,'여러 글을 겹쳐 문제 상황 정하기 — 좋은 점 · 사실 · 규칙을 보여 준 여러 글을 겹쳐 보면 해결해야 할 문제가 드러나며, 이를 「어떻게 하면 ~할 수 있을까?」처럼 문제 상황으로 정한다',ARRAY['6국02-04 읽기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C21','kor',5,1,'u5',4,'같은 편 글만 모으지 않는다 — 글을 더 찾아 읽을 때 내 생각과 같은 글만 모으면 보이지 않는 문제가 그대로 남으므로, 관점이 다른 글도 함께 읽어야 더 나은 해결 방법을 찾는다',ARRAY['6국02-04 읽기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C22','kor',5,1,'u5',4,'토의로 다룰 만한 문제 상황 — 토의로 다룰 문제는 혼자 답할 수 있는 사실 확인이 아니라 여럿이 방법을 모아야 하는 것이다',ARRAY['6국02-04 읽기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C23','kor',5,1,'u5',4,'실천할 수 있는 해결 방법 — 해결 방법은 누구나 꾸준히 할 수 있고 새로운 문제를 만들지 않아야 하며, 빌린 사람의 이름을 방송으로 알리거나 아예 빌려주지 않는 것은 새 문제를 만든다',ARRAY['6국02-04 읽기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C24','kor',5,1,'u5',7,'토의 절차 다섯 단계 — 토의는 토의 주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 결정하기의 차례로 진행한다',ARRAY['6국01-06 듣기·말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C25','kor',5,1,'u5',7,'어긋난 토의의 문제점 — 주제를 집중해 듣지 않기 · 이유 없이 반대하기 · 주제와 관련 없는 의견 내기 · 핀잔 주기 · 말 끊기 · 자기 생각만 우기기는 협력을 무너뜨린다',ARRAY['6국01-06 듣기·말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C26','kor',5,1,'u5',7,'사람이 아니라 의견을 다룬다 — 「네 말은 도움이 하나도 안 돼」처럼 의견이 아니라 사람을 깎아내리는 말은 상대가 마음 놓고 말하지 못하게 하므로 문제이다',ARRAY['6국01-06 듣기·말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C27','kor',5,1,'u5',7,'의견을 나누고 검토하기 — 의견과 이유를 함께 말하고 서로의 의견을 따져 보면 생각을 구체적으로 나누고 더 정교하게 다듬을 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C28','kor',5,1,'u5',7,'존중하는 태도로 토의하기 — 말을 끊지 않고 끝까지 듣고 사람이 아니라 의견을 다루면 누구나 마음 놓고 말할 수 있어 더 많은 생각이 나온다',ARRAY['6국01-06 듣기·말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C29','kor',5,1,'u5',7,'협력하며 토의 진행하기 — 주제에서 벗어나지 않게 부드럽게 되돌리고 모두가 말할 기회를 갖게 하면 시간 안에 결론에 이르고 빠지는 사람이 생기지 않는다',ARRAY['6국01-06 듣기·말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C30','kor',5,1,'u5',7,'세 방법이 함께 필요한 까닭 — 검토는 생각을 다듬고, 존중은 마음 놓고 말하게 하며, 협력하는 진행은 결론에 이르게 하므로 셋이 함께 있어야 토의가 결론까지 간다',ARRAY['6국01-06 듣기·말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C31','kor',5,1,'u5',7,'반대는 문제가 아니다 — 다른 의견에 반대하는 것 자체는 문제가 아니며 걱정되는 점과 이유를 들어 의견에 대해 말하면 의견이 다듬어지고, 문제는 이유 없는 반대와 사람을 겨눈 말이다',ARRAY['6국01-06 듣기·말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C32','kor',5,1,'u5',7,'협력은 모두의 몫 — 협력하는 방법은 세 가지가 전부가 아니라 토의에 도움이 되는 말과 행동이 모두 협력이며, 주제로 되돌리기 · 차례 넘기기 · 이유 묻기는 사회자가 아니어도 누구나 할 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C33','kor',5,1,'u5',9,'자료에서 토의 주제 찾기 — 토의 주제는 갑자기 떠오르지 않으며 광고나 기사 같은 자료를 살펴보다가 함께 이야기할 거리가 드러난다',ARRAY['6국01-06 듣기·말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C34','kor',5,1,'u5',9,'공익 광고 읽기 — 공익 광고는 길게 말하지 않고 그림과 한 문장으로 생각을 건네므로, 그림 속 모습과 적힌 글을 함께 보고 전하려는 뜻을 찾는다',ARRAY['6국02-04 읽기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C35','kor',5,1,'u5',9,'기사 내용 파악하기 — 기사의 처음과 지금을 견주어 무엇이 달라졌는지 찾으면 내용을 파악할 수 있으며, 「작은 나눔이 만든 변화」에서 상자가 늘어난 것은 마을 사람들이 함께 참여했기 때문이다',ARRAY['6국02-04 읽기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C36','kor',5,1,'u5',9,'생각을 묻는 질문 — 자료를 읽고 답이 그대로 적혀 있지 않아 여러 생각이 나올 수 있는 질문을 만들어야 토의할 거리가 생긴다',ARRAY['6국01-06 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C37','kor',5,1,'u5',9,'토의 주제의 조건 — 토의 주제는 여러 사람이 함께 생각을 모아야 하고, 원인이나 해결 방법과 관련 있으며, 우리가 실제로 해 볼 수 있고, 여러 의견이 나올 수 있으며, 내 삶과 관련 있고 흥미를 느낄 수 있는 것이어야 한다',ARRAY['6국01-06 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C38','kor',5,1,'u5',9,'의견을 뒷받침하는 타당한 이유 — 타당한 이유는 그렇게 하면 왜 좋은지를 설명하는 것이며, 「내가 하고 싶으니까」나 「다른 의견은 재미없어서」는 이유가 되지 않는다',ARRAY['6국01-06 듣기·말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C39','kor',5,1,'u5',9,'자료의 출처 적기 — 의견을 뒷받침할 자료를 찾았다면 어디에서 온 근거인지 출처를 함께 적어야 설득력이 생긴다',ARRAY['6국01-06 듣기·말하기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C40','kor',5,1,'u5',11,'협력이 드러난 토의 — 의견에 이유를 함께 말하고, 걱정되는 점을 의견에 대해 말하며, 앞의 지적을 받아 다음 의견을 내고, 사회자가 논의할 부분을 짚어 주면 의견이 서로를 딛고 자란다',ARRAY['6국01-06 듣기·말하기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C41','kor',5,1,'u5',11,'의견의 장점과 단점 살피기 — 의견마다 장점과 단점이 있으며, 단점을 찾는 것은 깎아내리는 일이 아니라 미리 알고 보완하기 위한 일이다',ARRAY['6국01-06 듣기·말하기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C42','kor',5,1,'u5',11,'종합해 더 나은 의견 만들기 — 여러 의견 가운데 하나만 골라야 하는 것은 아니며, 서로의 좋은 점을 합쳐 단점을 줄인 더 나은 의견을 만들 수 있다는 점이 토의가 투표와 다른 점이다',ARRAY['6국01-06 듣기·말하기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C43','kor',5,1,'u5',11,'의견을 결정하는 네 기준 — 모둠 의견은 누구나 실천할 수 있는지 · 꾸준히 이어 갈 수 있는지 · 문제 해결에 효과적인지 · 새 문제가 생기지 않는지로 결정하며, 누가 낸 의견인지는 기준이 아니다',ARRAY['6국01-06 듣기·말하기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C44','kor',5,1,'u5',11,'다른 모둠의 의견 듣기 — 다른 모둠의 의견을 들을 때에도 토의는 이어지므로 우리 모둠이 놓친 부분은 없는지, 우리 의견에 보탤 점은 없는지 살피며 듣는다',ARRAY['6국01-06 듣기·말하기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C45','kor',5,1,'u5',11,'토의 점검과 되돌아보기 — 토의 과정을 점검해 잘한 점과 아쉬운 점을 찾되, 아쉬운 점은 한 가지만 정해 다음 토의에서 고치고 다음 토의를 시작하기 전에 다시 꺼내 본다',ARRAY['6국01-06 듣기·말하기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C46','kor',5,1,'u5',12,'다른 교과와 이어지는 토의 주제 — 사회 · 과학 · 도덕 · 실과에서 배운 것 가운데 함께 답을 찾아야 할 문제를 우리 생활의 문제로 옮겨 토의할 수 있으며, 정한 방안은 실제로 해 본다',ARRAY['6국01-06 듣기·말하기']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C47','kor',5,1,'u5',12,'주제는 좁힐수록 좋다 — 「환경을 지키는 방법」처럼 넓은 주제는 누구도 실천하지 못하는 결론이 나오므로 「우리 반에서 종이컵 사용을 줄이는 방법」처럼 우리가 해 볼 수 있는 크기로 좁힌다',ARRAY['6국01-06 듣기·말하기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C48','kor',5,1,'u5',12,'토의 전에 준비할 것 — 토의 전에는 내 의견과 이유 · 이유를 뒷받침할 자료와 출처 · 협력하며 토의할 계획 · 차례와 시간 나누기를 준비하며, 상대를 이길 반박거리나 미리 정해 둔 결론은 준비할 것이 아니다',ARRAY['6국01-06 듣기·말하기']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C49','kor',5,1,'u5',12,'좋은 토의는 모두가 함께 만든다 — 좋은 토의는 한 사람의 솜씨가 아니라 참여한 모두가 저마다 몫을 맡아 함께 만드는 것이며, 이런 힘은 한 번에 길러지지 않고 토의를 거듭할수록 조금씩 자란다',ARRAY['6국02-04 읽기']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C50','kor',5,1,'u5',12,'받침은 대표 소리로 난다 — 받침으로 쓰이는 글자는 여럿이지만 실제로 나는 소리는 몇 가지 대표 소리뿐이어서 글자와 발음이 달라지는 낱말이 있으며, 소리가 같아도 쓸 때는 원래 글자를 쓴다 (기초 다지기)',ARRAY['기초 다지기(받침의 대표 소리)']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C51','kor',5,1,'u5',12,'받침소리 [ㄱ] — ㄱ · ㄲ · ㅋ 받침은 [ㄱ]으로 소리 나서 밖은 [박], 부엌은 [부억]으로 읽는다 (기초 다지기)',ARRAY['기초 다지기(받침의 대표 소리)']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C52','kor',5,1,'u5',12,'받침소리 [ㄷ] — ㅅ · ㅆ · ㅈ · ㅊ · ㅌ · ㄷ 받침은 [ㄷ]으로 소리 나서 옷은 [옫], 낮은 [낟], 꽃은 [꼳], 솥은 [솓]으로 읽는다 (기초 다지기)',ARRAY['기초 다지기(받침의 대표 소리)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u5-C53','kor',5,1,'u5',12,'받침소리 [ㅂ] — ㅂ · ㅍ 받침은 [ㅂ]으로 소리 나서 앞은 [압], 무릎은 [무릅]으로 읽는다 (기초 다지기)',ARRAY['기초 다지기(받침의 대표 소리)']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X01','kor',5,'u5',ARRAY['K5-1-u5-C1']::text[],'관점을 언제나 옳은 하나의 정답이나 무언가를 재는 기준으로 여긴다','바라보는 태도 · 방향 · 처지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X02','kor',5,'u5',ARRAY['K5-1-u5-C2']::text[],'같은 일을 두고 생각이 다르면 누군가는 반드시 틀렸다고 여긴다','바라보는 방향이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X03','kor',5,'u5',ARRAY['K5-1-u5-C3']::text[],'들은 의견을 견주어 보지 않고 들을 때마다 그대로 따르거나, 반대로 다른 의견은 아예 듣지 않는다','견주어 판단해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X04','kor',5,'u5',ARRAY['K5-1-u5-C4']::text[],'여러 글을 읽는 까닭을 읽은 글의 수를 늘리거나 토의에서 이기기 위해서로 여긴다','놓친 부분 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X05','kor',5,'u5',ARRAY['K5-1-u5-C5']::text[],'토의를 상대를 이기는 말하기로 여기거나, 다른 생각을 밀어내는 것을 토의로 여긴다','모아서 더 나은 답') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X06','kor',5,'u5',ARRAY['K5-1-u5-C6']::text[],'이 단원의 공부를 읽기나 토의 한쪽뿐으로 여기거나, 글에서 찾은 관점은 토의와 관계없다고 여긴다','관점 읽기 · 협력 토의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X07','kor',5,'u5',ARRAY['K5-1-u5-C7']::text[],'제목은 글의 이름일 뿐이라 관점과 관계없다고 여기거나, 제목에서는 글의 길이나 쓴 사람만 알 수 있다고 여긴다','제목의 낱말이 주는 느낌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X08','kor',5,'u5',ARRAY['K5-1-u5-C8']::text[],'학생 · 가을처럼 대상이나 때를 나타내는 낱말을 관점이 드러난 표현으로 고르거나, 낱말에는 생각이 담기지 않는다고 여긴다','느낌을 주는 낱말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X09','kor',5,'u5',ARRAY['K5-1-u5-C9']::text[],'글과 함께 실린 사진이나 그림은 꾸밈일 뿐이라 관점과 관계없다고 여긴다','무엇을 담았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X10','kor',5,'u5',ARRAY['K5-1-u5-C10']::text[],'문제점을 짚은 낱말 몇 개만 보고 글쓴이가 그 대상을 아예 반대한다고 단정한다','마지막 문장까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X11','kor',5,'u5',ARRAY['K5-1-u5-C11']::text[],'관점 파악 방법을 꼭 지켜야 하는 차례로 여기거나, 글자 수 세기처럼 관점과 관계없는 일을 방법으로 고른다','살펴볼 곳의 목록') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X12','kor',5,'u5',ARRAY['K5-1-u5-C12']::text[],'관점이 다른 까닭을 한쪽이 틀렸기 때문으로 여기거나, 관점에 맞고 틀림의 정답이 있다고 여긴다','맞고 틀림이 아니라 다름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X13','kor',5,'u5',ARRAY['K5-1-u5-C13']::text[],'관점이 다른 글을 함께 읽으면 헷갈리기만 하므로 한 가지 관점의 글만 읽는 것이 낫다고 여긴다','깊이 · 몰랐던 면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X14','kor',5,'u5',ARRAY['K5-1-u5-C14']::text[],'관점이 다른 두 글을 읽으면 반드시 둘 중 하나를 골라 편을 들어야 한다고 여긴다','생각을 넓히는 재료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X15','kor',5,'u5',ARRAY['K5-1-u5-C15']::text[],'같은 일을 다룬 여러 글은 모두 같은 면을 보여 준다고 여기거나 한 글만 읽어도 문제를 다 안다고 여긴다','저마다 보여 주는 면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X16','kor',5,'u5',ARRAY['K5-1-u5-C16']::text[],'대여 · 반납 · 훼손 · 관리의 뜻을 서로 헷갈린다','쓰인 문장에서 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X17','kor',5,'u5',ARRAY['K5-1-u5-C17']::text[],'안내문은 규칙만 알릴 뿐 관점이 없다고 여기거나 안내문의 관점을 엉뚱하게 짐작한다','마지막 줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X18','kor',5,'u5',ARRAY['K5-1-u5-C18']::text[],'글의 길이나 글씨처럼 관계없는 것으로 자료를 평가하거나 네 기준을 헷갈린다','제목 · 표현 · 신뢰 · 내 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X19','kor',5,'u5',ARRAY['K5-1-u5-C19']::text[],'글이 길고 어려운 낱말이 많거나 내 생각과 같은 편이면 믿을 만한 글이라고 여기고 출처는 살피지 않는다','확인할 수 있는 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X20','kor',5,'u5',ARRAY['K5-1-u5-C20']::text[],'여러 글을 따로따로 읽고 끝내 해결할 문제를 뽑아내지 못하거나 한 글의 내용만으로 문제를 정한다','겹쳐 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X21','kor',5,'u5',ARRAY['K5-1-u5-C21']::text[],'글을 더 찾아 읽을 때 내 생각과 같은 관점의 글만 모으면 된다고 여긴다','다른 관점 글도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X22','kor',5,'u5',ARRAY['K5-1-u5-C22']::text[],'남은 개수나 내일 날씨처럼 답이 하나로 정해지는 질문을 토의할 문제로 고른다','여럿이 방법을 모아야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X23','kor',5,'u5',ARRAY['K5-1-u5-C23']::text[],'창피를 주거나 아예 없애는 것처럼 새 문제를 만드는 방법을 실천할 해결 방법으로 고른다','누구나 · 꾸준히 · 새 문제 없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X24','kor',5,'u5',ARRAY['K5-1-u5-C24']::text[],'토의 절차의 차례를 뒤섞거나 주제를 정하기 전에 의견부터 결정한다','주제 → 마련 → 나누기 → 모으기 → 결정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X25','kor',5,'u5',ARRAY['K5-1-u5-C25']::text[],'사회자가 발언 순서를 정하는 것처럼 토의를 돕는 일을 문제점으로 여기거나 협력이 무너진 행동을 알아보지 못한다','듣기 · 근거 · 말투') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X26','kor',5,'u5',ARRAY['K5-1-u5-C26']::text[],'사람을 깎아내리는 말이 문제인 까닭을 목소리 크기나 말의 길이로 여긴다','의견을 따졌나, 사람을 탓했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X27','kor',5,'u5',ARRAY['K5-1-u5-C27']::text[],'의견만 말하고 이유는 붙이지 않아도 되거나, 서로의 의견을 따져 보는 것은 다툼이라고 여긴다','의견 + 이유') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X28','kor',5,'u5',ARRAY['K5-1-u5-C28']::text[],'내 차례가 아니면 듣지 않아도 되거나 할 말이 생각나면 남의 말을 끊어도 된다고 여긴다','끝까지 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X29','kor',5,'u5',ARRAY['K5-1-u5-C29']::text[],'주제에서 벗어난 말도 그대로 두거나, 말하지 않은 친구는 그냥 두어도 된다고 여긴다','되돌리기 · 차례 넘기기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X30','kor',5,'u5',ARRAY['K5-1-u5-C30']::text[],'세 방법 가운데 하나만 지키면 토의가 잘된다고 여기거나 각 방법이 필요한 까닭을 엉뚱하게 짝짓는다','셋이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X31','kor',5,'u5',ARRAY['K5-1-u5-C31']::text[],'토의에서 반대하는 것 자체가 협력을 깨는 일이라고 여기거나 이유 없이 「그냥」 반대한다','반대 + 이유') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X32','kor',5,'u5',ARRAY['K5-1-u5-C32']::text[],'토의를 이끄는 일은 사회자 한 사람의 몫이라고 여기거나 협력하는 방법은 정해진 세 가지뿐이라고 여긴다','모두가 할 수 있는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X33','kor',5,'u5',ARRAY['K5-1-u5-C33']::text[],'토의 주제는 자료 없이 갑자기 떠올리는 것이라고 여기거나 자료를 살피는 일은 토의와 관계없다고 여긴다','자료에서 이야기할 거리를') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X34','kor',5,'u5',ARRAY['K5-1-u5-C34']::text[],'광고 속 그림의 겉모습만 보고 뜻을 짐작해 전하려는 생각을 놓친다','그림 + 한 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X35','kor',5,'u5',ARRAY['K5-1-u5-C35']::text[],'기사에 나오지 않은 돈이나 다른 까닭을 끌어와 내용을 잘못 파악한다','처음과 지금') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X36','kor',5,'u5',ARRAY['K5-1-u5-C36']::text[],'개수나 이름처럼 답이 자료에 그대로 적힌 질문을 생각을 묻는 질문으로 여긴다','답이 하나로 정해지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X37','kor',5,'u5',ARRAY['K5-1-u5-C37']::text[],'학생 수나 가장 맛있는 간식처럼 답이 하나이거나 취향만 묻는 것을 토의 주제로 고른다','여럿이 · 해 볼 수 있는') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X38','kor',5,'u5',ARRAY['K5-1-u5-C38']::text[],'하고 싶은 마음이나 다른 의견에 대한 느낌을 의견의 이유로 여긴다','왜 좋은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X39','kor',5,'u5',ARRAY['K5-1-u5-C39']::text[],'찾은 자료의 출처는 적지 않아도 된다고 여긴다','어디에서 온 근거?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X40','kor',5,'u5',ARRAY['K5-1-u5-C40']::text[],'가장 목소리가 큰 사람의 의견으로 정하는 것을 협력으로 여기거나 앞 사람의 지적을 이어받는 모습을 알아보지 못한다','앞 말을 이어받아') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X41','kor',5,'u5',ARRAY['K5-1-u5-C41']::text[],'의견의 단점을 찾는 것을 깎아내리는 일로 여기거나 의견과 그 단점을 엉뚱하게 짝짓는다','보완하려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X42','kor',5,'u5',ARRAY['K5-1-u5-C42']::text[],'토의도 투표처럼 의견 하나만 골라야 하거나 가장 먼저 나온 의견으로 정하면 된다고 여긴다','합쳐서 더 나은') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X43','kor',5,'u5',ARRAY['K5-1-u5-C43']::text[],'누가 낸 의견인지나 친한 친구의 의견인지로 모둠 의견을 결정한다','실천 · 꾸준 · 효과 · 새 문제') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X44','kor',5,'u5',ARRAY['K5-1-u5-C44']::text[],'다른 모둠의 의견을 우리 의견이 낫다는 까닭을 찾으려고 듣거나 이미 정했으니 듣지 않는다','보탤 점 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X45','kor',5,'u5',ARRAY['K5-1-u5-C45']::text[],'되돌아볼 때 아쉬운 점을 한 번에 모두 고치려 하거나 점검한 내용을 다음 토의에 이어 쓰지 않는다','한 가지만 정해서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X46','kor',5,'u5',ARRAY['K5-1-u5-C46']::text[],'토의는 국어 시간에만 하는 것이라 여기거나 교과와 주제를 엉뚱하게 잇는다','배운 것을 생활 문제로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X47','kor',5,'u5',ARRAY['K5-1-u5-C47']::text[],'주제는 넓고 클수록 좋은 토의가 된다고 여긴다','해 볼 수 있는 크기로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X48','kor',5,'u5',ARRAY['K5-1-u5-C48']::text[],'상대를 이길 반박거리나 미리 정해 둔 결론을 토의 준비물로 여긴다','의견 · 자료 · 협력 계획') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X49','kor',5,'u5',ARRAY['K5-1-u5-C49']::text[],'토의가 어긋나면 사회자 한 사람의 탓이라 여기거나, 토의하는 힘은 한 번에 길러져야 한다고 여긴다','모두의 몫 · 조금씩 자람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X50','kor',5,'u5',ARRAY['K5-1-u5-C50']::text[],'받침은 쓴 글자대로 소리 난다고 여기거나, 소리 나는 대로 받침을 바꾸어 쓴다','소리는 대표 소리, 글자는 원래대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X51','kor',5,'u5',ARRAY['K5-1-u5-C51']::text[],'밖 · 부엌처럼 ㄲ · ㅋ 받침을 [ㄱ]이 아닌 소리로 읽는다','ㄱ · ㄲ · ㅋ → [ㄱ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X52','kor',5,'u5',ARRAY['K5-1-u5-C52']::text[],'옷 · 낮 · 꽃 · 솥처럼 ㅅ · ㅈ · ㅊ · ㅌ 받침을 [ㄷ]이 아닌 소리로 읽는다','ㅅ · ㅈ · ㅊ · ㅌ → [ㄷ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u5-X53','kor',5,'u5',ARRAY['K5-1-u5-C53']::text[],'앞 · 무릎처럼 ㅍ 받침을 [ㅂ]이 아닌 소리로 읽는다','ㅂ · ㅍ → [ㅂ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#1','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C1',1,'mc','auto','관점의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X01']::text[],false,'{"seq":1,"concept":"K5-1-u5-C1","difficulty":1,"kind":"mc","stem":"관점의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"사물이나 현상을 바라보는 태도나 방향, 처지","correct":true},{"t":"언제나 옳은 하나의 정답","mis":"K5-1-u5-X01"},{"t":"사물의 크기를 재는 기준","mis":"K5-1-u5-X01"},{"t":"글을 쓴 날짜와 장소","mis":"K5-1-u5-X01"}],"explanation":["관점은 정답이 아니에요.","재는 기준이 아니에요.","바라보는 태도 · 방향 · 처지가 관점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#2','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C2',1,'mc','auto','예린 · 지후 · 민서의 말에 대해 바르게 생각한 것은 어느 것인가요?',ARRAY['K5-1-u5-X02','K5-1-u5-X05']::text[],false,'{"seq":2,"concept":"K5-1-u5-C2","difficulty":1,"kind":"mc","stem":"예린 · 지후 · 민서의 말에 대해 바르게 생각한 것은 어느 것인가요?","options":[{"t":"세 사람 모두 틀린 말을 하지 않았고 바라보는 방향이 달랐다","correct":true},{"t":"예린이만 옳고 두 사람은 틀렸다","mis":"K5-1-u5-X02"},{"t":"세 사람 모두 틀린 말을 했다","mis":"K5-1-u5-X02"},{"t":"생각이 다르니 셋은 이야기를 나눌 수 없다","mis":"K5-1-u5-X05"}],"explanation":["누가 틀린 것이 아니에요.","셋 다 그럴듯한 말이에요.","무엇에 무게를 두느냐가 달랐어요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"진심을 담은 사과가 먼저라고 생각해."},{"who":"지후","text":"나는 갈등이 생긴 원인부터 찾아야 할 것 같은데."},{"who":"민서","text":"화가 가라앉을 때까지 기다렸다가 이야기하는 게 낫지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#3','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C3',1,'mc','auto','두 사람이 해가 저물도록 사다리를 다 옮기지 못한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X03','K5-1-u5-X02']::text[],false,'{"seq":3,"concept":"K5-1-u5-C3","difficulty":1,"kind":"mc","stem":"두 사람이 해가 저물도록 사다리를 다 옮기지 못한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"들은 말을 견주어 보지 않고 들을 때마다 그대로 따랐기 때문이다","correct":true},{"t":"사다리가 너무 무거웠기 때문이다","mis":"K5-1-u5-X03"},{"t":"아무에게도 의견을 듣지 않았기 때문이다","mis":"K5-1-u5-X03"},{"t":"들은 말이 모두 엉터리였기 때문이다","mis":"K5-1-u5-X02"}],"explanation":["무게 이야기는 없어요.","의견은 많이 들었어요.","듣는 것과 그대로 따르는 것은 달라요."],"asset":{"type":"passage","lines":["두 사람이 긴 사다리를 마을 끝까지 옮기게 되어 처음에는 앞뒤로 나누어 들었다.","마주 오던 어른이 「뒤에서 밀어 주지 그러나.」 하여 한 사람이 뒤에서 밀었다.","다른 사람이 「밀면 위험해요. 나란히 어깨에 메세요.」 하여 어깨에 멨다.","또 다른 사람이 「어깨가 상해요. 수레에 실으세요.」 하였다.","두 사람은 수레를 구하러 갔다가 끝내 해가 저물었다."],"title":"사다리를 옮기는 두 사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#4','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C5',1,'ox','auto','토의는 상대를 이기기 위한 말하기예요.',ARRAY['K5-1-u5-X05']::text[],false,'{"seq":4,"concept":"K5-1-u5-C5","difficulty":1,"kind":"ox","stem":"토의는 상대를 이기기 위한 말하기예요.","answer":"X","reason_options":[{"t":"서로 다른 생각을 모아 더 나은 답을 찾는 일이기 때문에","correct":true},{"t":"말을 잘해 상대를 꺾어야 하기 때문에","mis":"K5-1-u5-X05"}],"mis":"K5-1-u5-X05","explanation":["토의는 겨루기가 아니에요.","다른 생각을 모아요.","더 나은 답을 함께 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#5','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C3',2,'mc','auto','다양한 의견을 받아들일 때 생각할 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X03']::text[],false,'{"seq":5,"concept":"K5-1-u5-C3","difficulty":2,"kind":"mc","stem":"다양한 의견을 받아들일 때 생각할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 상황에 맞는지 견주어 판단한다","correct":true},{"t":"들은 대로 모두 따른다","mis":"K5-1-u5-X03"},{"t":"다른 의견은 아예 듣지 않는다","mis":"K5-1-u5-X03"},{"t":"가장 나중에 들은 의견을 따른다","mis":"K5-1-u5-X03"}],"explanation":["그대로 따르면 사다리 꼴이 나요.","듣지 않으면 놓쳐요.","견주어 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#6','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C4',2,'mc','auto','문제 해결 방법을 찾을 때 여러 관점의 글을 읽어야 하는 까닭은 무엇인가요?',ARRAY['K5-1-u5-X04']::text[],false,'{"seq":6,"concept":"K5-1-u5-C4","difficulty":2,"kind":"mc","stem":"문제 해결 방법을 찾을 때 여러 관점의 글을 읽어야 하는 까닭은 무엇인가요?","options":[{"t":"혼자서는 놓치는 부분을 찾을 수 있어서","correct":true},{"t":"읽은 글의 수를 늘리려고","mis":"K5-1-u5-X04"},{"t":"토의에서 이기려고","mis":"K5-1-u5-X04"},{"t":"글쓴이의 이름을 알아 두려고","mis":"K5-1-u5-X04"}],"explanation":["수가 목적이 아니에요.","이기려고 읽지 않아요.","여러 방향에서 따져 보려고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#7','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C6',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u5-X06']::text[],false,'{"seq":7,"concept":"K5-1-u5-C6","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"다양한 관점의 글을 읽고 문제 해결에 활용하기 · 협력하며 토의하기","correct":true},{"t":"겪은 일을 글로 쓰기 · 작품 감상하기","mis":"K5-1-u5-X06"},{"t":"글의 구조 알기 · 내용 요약하기","mis":"K5-1-u5-X06"},{"t":"관점 읽기만 하고 토의는 하지 않기","mis":"K5-1-u5-X06"}],"explanation":["다른 단원의 공부예요.","구조와 요약은 앞 단원이에요.","관점 읽기와 협력 토의 두 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#8','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C1',2,'blank','auto','빈칸에 알맞은 말은 어느 것인가요? 「같은 것을 보아도 생각이 달라지는 것은 (　　)이 다르기 때문이다.」',ARRAY['K5-1-u5-X01']::text[],false,'{"seq":8,"concept":"K5-1-u5-C1","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말은 어느 것인가요? 「같은 것을 보아도 생각이 달라지는 것은 (　　)이 다르기 때문이다.」","options":[{"t":"관점","correct":true},{"t":"글씨","mis":"K5-1-u5-X01"},{"t":"목소리","mis":"K5-1-u5-X01"},{"t":"키","mis":"K5-1-u5-X01"}],"explanation":["글씨 모양과는 관계없어요.","목소리와도 관계없어요.","바라보는 태도와 방향, 처지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#9','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C4',2,'match','auto','생각하는 방법과 그 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C4","difficulty":2,"kind":"match","stem":"생각하는 방법과 그 결과를 알맞게 이으세요.","pairs":[{"l":"혼자 생각하면","r":"놓치는 부분이 생길 수 있다"},{"l":"여럿이 살펴보면","r":"하나의 문제를 여러 방향에서 따져 볼 수 있다"},{"l":"들은 말을 견주어 보면","r":"우리 상황에 맞는 것을 고를 수 있다"}],"mis":"K5-1-u5-X04","explanation":["혼자는 빈틈이 생겨요.","여럿이면 방향이 늘어요.","견주면 고를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_basic#10','kor',5,1,'u5','L01','g5_1_kor_u5_L01_basic','lesson_basic','K5-1-u5-C5',3,'mc','auto','토의에 협력이 없으면 토의가 되지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X32','K5-1-u5-X05']::text[],false,'{"seq":10,"concept":"K5-1-u5-C5","difficulty":3,"kind":"mc","stem":"토의에 협력이 없으면 토의가 되지 않는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여럿의 생각을 모아 더 나은 답을 만드는 일이기 때문이다","correct":true},{"t":"토의는 사회자 혼자 정하는 일이기 때문이다","mis":"K5-1-u5-X32"},{"t":"토의는 목소리가 큰 사람이 이기는 일이기 때문이다","mis":"K5-1-u5-X05"},{"t":"협력하면 시간이 오래 걸리기 때문이다","mis":"K5-1-u5-X05"}],"explanation":["사회자 혼자 하는 일이 아니에요.","목소리 크기와 관계없어요.","생각을 모으려면 협력해야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#1','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C3',2,'ox','auto','여러 사람의 의견을 듣는 것과 그 의견을 그대로 따르는 것은 같은 일이에요.',ARRAY['K5-1-u5-X03']::text[],false,'{"seq":1,"concept":"K5-1-u5-C3","difficulty":2,"kind":"ox","stem":"여러 사람의 의견을 듣는 것과 그 의견을 그대로 따르는 것은 같은 일이에요.","answer":"X","reason_options":[{"t":"들은 의견이 우리 상황에 맞는지 견주어 판단해야 하기 때문에","correct":true},{"t":"의견을 들었으면 모두 따라야 예의이기 때문에","mis":"K5-1-u5-X03"}],"mis":"K5-1-u5-X03","explanation":["듣고 따르기는 달라요.","사다리 이야기를 떠올려요.","견주어 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#2','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C2',2,'mc','auto','같은 일을 두고 사람마다 생각이 달라지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X02','K5-1-u5-X01']::text[],false,'{"seq":2,"concept":"K5-1-u5-C2","difficulty":2,"kind":"mc","stem":"같은 일을 두고 사람마다 생각이 달라지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇에 무게를 두고 바라보는지가 사람마다 다르기 때문이다","correct":true},{"t":"한 사람은 반드시 틀렸기 때문이다","mis":"K5-1-u5-X02"},{"t":"생각이 같아야 하는데 실수했기 때문이다","mis":"K5-1-u5-X02"},{"t":"일이 일어난 날짜가 다르기 때문이다","mis":"K5-1-u5-X01"}],"explanation":["틀린 것이 아니에요.","실수가 아니에요.","바라보는 방향의 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#3','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C3',3,'mc','auto','사다리 이야기에서 두 사람이 했으면 좋았을 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X03','K5-1-u5-X43']::text[],false,'{"seq":3,"concept":"K5-1-u5-C3","difficulty":3,"kind":"mc","stem":"사다리 이야기에서 두 사람이 했으면 좋았을 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"들은 방법들을 견주어 보고 자기들 상황에 맞는 것을 골랐어야 했다","correct":true},{"t":"처음부터 아무 말도 듣지 말았어야 했다","mis":"K5-1-u5-X03"},{"t":"마지막에 들은 말만 따랐어야 했다","mis":"K5-1-u5-X03"},{"t":"가장 나이 많은 사람의 말을 따랐어야 했다","mis":"K5-1-u5-X43"}],"explanation":["듣지 않으면 놓쳐요.","나중 말이 늘 옳은 건 아니에요.","견주어 판단하고 골라요."],"asset":{"type":"passage","lines":["두 사람이 긴 사다리를 마을 끝까지 옮기게 되어 처음에는 앞뒤로 나누어 들었다.","마주 오던 어른이 「뒤에서 밀어 주지 그러나.」 하여 한 사람이 뒤에서 밀었다.","다른 사람이 「밀면 위험해요. 나란히 어깨에 메세요.」 하여 어깨에 멨다.","또 다른 사람이 「어깨가 상해요. 수레에 실으세요.」 하였다.","두 사람은 수레를 구하러 갔다가 끝내 해가 저물었다."],"title":"사다리를 옮기는 두 사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#4','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C2',3,'error','auto','세 친구의 말을 듣고 친구들이 한 생각이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-1-u5-X02','K5-1-u5-X12','K5-1-u5-X05']::text[],false,'{"seq":4,"concept":"K5-1-u5-C2","difficulty":3,"kind":"error","stem":"세 친구의 말을 듣고 친구들이 한 생각이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「지후는 사과를 말하지 않았으니 틀린 말을 한 거야.」","correct":true,"mis_target":"K5-1-u5-X02"},{"t":"「세 사람이 바라보는 방향이 서로 달랐을 뿐이야.」","mis":"K5-1-u5-X12"},{"t":"「여러 생각을 모으면 더 나은 방법이 나올 수 있겠어.」","mis":"K5-1-u5-X05"}],"explanation":["방향이 달랐다는 말은 알맞아요.","모으자는 말도 알맞아요.","다른 말을 했다고 틀린 것은 아니에요."],"asset":{"type":"speech","turns":[{"who":"예린","text":"진심을 담은 사과가 먼저라고 생각해."},{"who":"지후","text":"나는 갈등이 생긴 원인부터 찾아야 할 것 같은데."},{"who":"민서","text":"화가 가라앉을 때까지 기다렸다가 이야기하는 게 낫지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#5','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C4',3,'mc','auto','혼자서만 생각해서 문제를 풀 때 생길 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X04','K5-1-u5-X13']::text[],false,'{"seq":5,"concept":"K5-1-u5-C4","difficulty":3,"kind":"mc","stem":"혼자서만 생각해서 문제를 풀 때 생길 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"놓치는 부분이 생겨 잘못 판단할 수 있다","correct":true},{"t":"언제나 가장 좋은 답을 찾는다","mis":"K5-1-u5-X04"},{"t":"여러 방향에서 저절로 따져 보게 된다","mis":"K5-1-u5-X04"},{"t":"다른 사람의 생각까지 다 알게 된다","mis":"K5-1-u5-X13"}],"explanation":["늘 좋은 답이 나오진 않아요.","혼자서는 방향이 하나예요.","빈틈이 생길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#6','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C6',3,'mc','auto','이 단원에서 「글에서 찾은 관점」과 「토의」가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X06','K5-1-u5-X14']::text[],false,'{"seq":6,"concept":"K5-1-u5-C6","difficulty":3,"kind":"mc","stem":"이 단원에서 「글에서 찾은 관점」과 「토의」가 이어지는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 글에서 찾은 관점이 토의에서 의견을 마련하는 재료가 된다","correct":true},{"t":"글의 관점은 토의와 관계없다","mis":"K5-1-u5-X06"},{"t":"토의를 하면 글을 읽지 않아도 된다","mis":"K5-1-u5-X06"},{"t":"관점은 하나만 찾아야 토의를 할 수 있다","mis":"K5-1-u5-X14"}],"explanation":["둘은 이어져요.","읽기도 해요.","읽은 관점이 토의의 재료가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#7','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C1',3,'mc','auto','다음 가운데 「관점이 다르다」고 말하기에 가장 알맞은 경우는 어느 것인가요?',ARRAY['K5-1-u5-X01']::text[],false,'{"seq":7,"concept":"K5-1-u5-C1","difficulty":3,"kind":"mc","stem":"다음 가운데 「관점이 다르다」고 말하기에 가장 알맞은 경우는 어느 것인가요?","options":[{"t":"같은 축제를 두고 한 사람은 즐거움을, 다른 사람은 준비 부담을 먼저 본다","correct":true},{"t":"두 사람이 서로 다른 축제에 다녀왔다","mis":"K5-1-u5-X01"},{"t":"한 사람은 키가 크고 한 사람은 작다","mis":"K5-1-u5-X01"},{"t":"두 사람이 같은 책을 같은 날 샀다","mis":"K5-1-u5-X01"}],"explanation":["대상이 다르면 견줄 수 없어요.","키는 관점이 아니에요.","같은 것을 다르게 바라볼 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#8','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C3',4,'essay','teacher','사다리 이야기를 읽고, 여러 사람의 의견을 들을 때 지켜야 할 점을 두 사람이 겪은 일과 이어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C3","difficulty":4,"kind":"essay","stem":"사다리 이야기를 읽고, 여러 사람의 의견을 들을 때 지켜야 할 점을 두 사람이 겪은 일과 이어 쓰세요.","answer_guide":{"answer":"예: 두 사람은 들은 말을 견주어 보지 않고 들을 때마다 그대로 따라서 해가 저물도록 사다리를 옮기지 못했다. 여러 의견을 들을 때는 그 의견이 우리 상황에 맞는지 따져 보고 골라야 한다. 들은 대로 다 따르는 것과 귀담아듣는 것은 다르다.","scoring_points":["두 사람이 겪은 일을 썼는가","견주어 판단해야 한다는 점을 썼는가","듣기와 따르기가 다르다는 점을 썼는가"]},"explanation":["두 사람은 어떻게 했나요?","무엇을 해야 했나요?","듣기와 따르기를 견주어요."],"asset":{"type":"passage","lines":["두 사람이 긴 사다리를 마을 끝까지 옮기게 되어 처음에는 앞뒤로 나누어 들었다.","마주 오던 어른이 「뒤에서 밀어 주지 그러나.」 하여 한 사람이 뒤에서 밀었다.","다른 사람이 「밀면 위험해요. 나란히 어깨에 메세요.」 하여 어깨에 멨다.","또 다른 사람이 「어깨가 상해요. 수레에 실으세요.」 하였다.","두 사람은 수레를 구하러 갔다가 끝내 해가 저물었다."],"title":"사다리를 옮기는 두 사람"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#9','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C2',4,'essay','teacher','친구와 같은 일을 두고 생각이 달랐던 경험을 떠올려 쓰고, 그때 나와 친구가 각각 무엇을 보고 그렇게 생각했는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C2","difficulty":4,"kind":"essay","stem":"친구와 같은 일을 두고 생각이 달랐던 경험을 떠올려 쓰고, 그때 나와 친구가 각각 무엇을 보고 그렇게 생각했는지 쓰세요.","answer_guide":{"answer":"예: 모둠 발표 날짜를 정할 때 나는 준비할 시간이 넉넉한 날을, 친구는 다른 숙제가 없는 날을 먼저 생각했다. 나는 발표를 잘하는 것에, 친구는 부담을 줄이는 것에 무게를 두었다. 누가 틀린 것이 아니라 바라보는 방향이 달랐다.","scoring_points":["생각이 달랐던 경험을 썼는가","나와 친구가 무엇을 보았는지 썼는가","틀린 것이 아니라 방향이 달랐음을 썼는가"]},"explanation":["어떤 일이었나요?","각자 무엇에 무게를 두었나요?","다름을 어떻게 볼까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L01_challenge#10','kor',5,1,'u5','L01','g5_1_kor_u5_L01_challenge','lesson_challenge','K5-1-u5-C5',4,'essay','teacher','토의가 「이기는 말하기」가 아닌 까닭을 쓰고, 그래서 토의에 참여할 때 어떤 마음가짐이 필요한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C5","difficulty":4,"kind":"essay","stem":"토의가 「이기는 말하기」가 아닌 까닭을 쓰고, 그래서 토의에 참여할 때 어떤 마음가짐이 필요한지 쓰세요.","answer_guide":{"answer":"예: 토의는 서로 다른 생각을 모아 더 나은 답을 찾는 일이어서 누가 이기고 지는 것이 목적이 아니다. 그래서 내 의견만 내세우지 않고 다른 사람의 생각에서 좋은 점을 찾아 함께 답을 만들겠다는 협력하는 마음이 필요하다.","scoring_points":["토의의 목적을 썼는가","이기는 말하기와 다른 점을 썼는가","협력하는 마음가짐을 썼는가"]},"explanation":["토의는 무엇을 하는 일인가요?","겨루기와 무엇이 다른가요?","어떤 마음이 필요할까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#1','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C7',1,'mc','auto','두 글의 제목만 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X07','K5-1-u5-X10']::text[],false,'{"seq":1,"concept":"K5-1-u5-C7","difficulty":1,"kind":"mc","stem":"두 글의 제목만 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 글쓴이의 관점이 서로 다르다","correct":true},{"t":"두 글의 길이가 다르다","mis":"K5-1-u5-X07"},{"t":"두 글을 같은 사람이 썼다","mis":"K5-1-u5-X07"},{"t":"두 글 모두 축제를 없애자고 한다","mis":"K5-1-u5-X10"}],"explanation":["길이는 제목으로 알 수 없어요.","쓴 사람도 알 수 없어요.","제목의 낱말이 주는 느낌이 달라요."],"asset":{"type":"passage","lines":["글 ㉮ — 학교 축제, 열면 좋은 점","글 ㉯ — 학교 축제, 다시 생각해 볼 점"],"title":"두 글의 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#2','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C8',1,'mc','auto','글 ㉮에서 글쓴이의 관점이 드러나는 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X08']::text[],false,'{"seq":2,"concept":"K5-1-u5-C8","difficulty":1,"kind":"mc","stem":"글 ㉮에서 글쓴이의 관점이 드러나는 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"보람","correct":true},{"t":"가을","mis":"K5-1-u5-X08"},{"t":"학교","mis":"K5-1-u5-X08"},{"t":"무대","mis":"K5-1-u5-X08"}],"explanation":["때를 나타내는 말이에요.","대상을 가리키는 말이에요.","좋은 점에 무게를 둔 낱말이에요."],"asset":{"type":"passage","lines":["학교 축제는 서로를 가까이 만나는 소중한 기회입니다.","먼저, 평소에 볼 수 없던 친구의 모습을 발견할 수 있습니다.","또 함께 무언가를 만들어 낸 보람이 남고, 그 시간은 추억이 됩니다.","무엇보다 학교가 즐거운 곳이 됩니다.","앞으로도 이런 기회가 많아지면 좋겠습니다."],"title":"글 ㉮ 학교 축제, 열면 좋은 점","hi":["소중한","보람","추억","즐거운 곳"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#3','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C8',1,'mc','auto','글 ㉯에서 글쓴이의 관점이 드러나는 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X08']::text[],false,'{"seq":3,"concept":"K5-1-u5-C8","difficulty":1,"kind":"mc","stem":"글 ㉯에서 글쓴이의 관점이 드러나는 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"낭비","correct":true},{"t":"학생","mis":"K5-1-u5-X08"},{"t":"장식","mis":"K5-1-u5-X08"},{"t":"수업","mis":"K5-1-u5-X08"}],"explanation":["대상을 가리키는 말이에요.","물건 이름이에요.","걱정하는 느낌을 주는 낱말이에요."],"asset":{"type":"passage","lines":["학교 축제를 기다리는 학생이 많지만 문제점은 없는지도 살펴보아야 합니다.","먼저, 준비에 드는 시간이 지나치게 길어져 수업이 밀리기도 합니다.","또 무대에 서는 학생과 그렇지 않은 학생 사이에 차이가 생깁니다.","한 번 쓰고 버리는 장식과 소품이 많아 낭비가 생기기도 합니다.","따라서 축제를 열되 규모와 방식을 신중하게 정해야 합니다."],"title":"글 ㉯ 학교 축제, 다시 생각해 볼 점","hi":["문제점","길어져","차이","낭비","신중하게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#4','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C11',1,'mc','auto','글쓴이의 관점을 파악하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X11','K5-1-u5-X09','K5-1-u5-X08']::text[],false,'{"seq":4,"concept":"K5-1-u5-C11","difficulty":1,"kind":"mc","stem":"글쓴이의 관점을 파악하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글의 글자 수 세어 보기","correct":true},{"t":"제목 살펴보기","mis":"K5-1-u5-X11"},{"t":"함께 실린 사진이나 그림 살펴보기","mis":"K5-1-u5-X09"},{"t":"글에 쓰인 표현 살펴보기","mis":"K5-1-u5-X08"}],"explanation":["제목도 살펴볼 곳이에요.","사진과 그림도 살펴볼 곳이에요.","글자 수는 관점과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#5','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C10',2,'mc','auto','글 ㉯ 글쓴이의 관점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X10']::text[],false,'{"seq":5,"concept":"K5-1-u5-C10","difficulty":2,"kind":"mc","stem":"글 ㉯ 글쓴이의 관점으로 알맞은 것은 어느 것인가요?","options":[{"t":"축제를 열되 규모와 방식을 신중하게 정해야 한다","correct":true},{"t":"축제를 아예 없애야 한다","mis":"K5-1-u5-X10"},{"t":"축제를 더 크게 열어야 한다","mis":"K5-1-u5-X10"},{"t":"축제에 대한 생각이 없다","mis":"K5-1-u5-X10"}],"explanation":["없애자고 하지 않았어요.","크게 열자는 말도 없어요.","마지막 문장을 다시 읽어요."],"asset":{"type":"passage","lines":["학교 축제를 기다리는 학생이 많지만 문제점은 없는지도 살펴보아야 합니다.","먼저, 준비에 드는 시간이 지나치게 길어져 수업이 밀리기도 합니다.","또 무대에 서는 학생과 그렇지 않은 학생 사이에 차이가 생깁니다.","한 번 쓰고 버리는 장식과 소품이 많아 낭비가 생기기도 합니다.","따라서 축제를 열되 규모와 방식을 신중하게 정해야 합니다."],"title":"글 ㉯ 학교 축제, 다시 생각해 볼 점","hi":["문제점","길어져","차이","낭비","신중하게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#6','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C8',2,'mc','auto','글 ㉮ 글쓴이의 관점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X10','K5-1-u5-X15','K5-1-u5-X08']::text[],false,'{"seq":6,"concept":"K5-1-u5-C8","difficulty":2,"kind":"mc","stem":"글 ㉮ 글쓴이의 관점으로 알맞은 것은 어느 것인가요?","options":[{"t":"학교 축제는 좋은 점이 많으니 기회가 많아지면 좋겠다","correct":true},{"t":"학교 축제는 열지 않는 편이 낫다","mis":"K5-1-u5-X10"},{"t":"학교 축제는 준비 시간이 너무 길다","mis":"K5-1-u5-X15"},{"t":"학교 축제에 대한 생각이 없다","mis":"K5-1-u5-X08"}],"explanation":["그런 말은 없어요.","그건 글 ㉯의 내용이에요.","좋은 점에 무게를 두었어요."],"asset":{"type":"passage","lines":["학교 축제는 서로를 가까이 만나는 소중한 기회입니다.","먼저, 평소에 볼 수 없던 친구의 모습을 발견할 수 있습니다.","또 함께 무언가를 만들어 낸 보람이 남고, 그 시간은 추억이 됩니다.","무엇보다 학교가 즐거운 곳이 됩니다.","앞으로도 이런 기회가 많아지면 좋겠습니다."],"title":"글 ㉮ 학교 축제, 열면 좋은 점","hi":["소중한","보람","추억","즐거운 곳"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#7','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C12',2,'ox','auto','관점이 서로 다른 두 글쓴이 가운데 한 사람은 틀린 거예요.',ARRAY['K5-1-u5-X12']::text[],false,'{"seq":7,"concept":"K5-1-u5-C12","difficulty":2,"kind":"ox","stem":"관점이 서로 다른 두 글쓴이 가운데 한 사람은 틀린 거예요.","answer":"X","reason_options":[{"t":"겪은 일과 알고 있는 것이 달라 같은 것을 보아도 다르게 생각하기 때문에","correct":true},{"t":"관점에는 언제나 하나의 정답이 있기 때문에","mis":"K5-1-u5-X12"}],"mis":"K5-1-u5-X12","explanation":["관점은 맞고 틀림이 아니에요.","경험이 다르면 생각도 달라요.","서로 다름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#8','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C11',2,'match','auto','관점을 파악할 때 살펴볼 곳과 그곳에서 알 수 있는 것을 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C11","difficulty":2,"kind":"match","stem":"관점을 파악할 때 살펴볼 곳과 그곳에서 알 수 있는 것을 이으세요.","pairs":[{"l":"제목","r":"읽기 전에 미리 짐작할 수 있다"},{"l":"사진이나 그림","r":"무엇을 담았는지에 생각이 드러난다"},{"l":"표현","r":"고른 낱말과 문장에 관점이 스며 있다"}],"mis":"K5-1-u5-X11","explanation":["읽기 전에 보는 곳이에요.","담은 것에 생각이 있어요.","낱말과 문장을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#9','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C13',2,'mc','auto','관점이 다른 글을 함께 읽으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X13','K5-1-u5-X12']::text[],false,'{"seq":9,"concept":"K5-1-u5-C13","difficulty":2,"kind":"mc","stem":"관점이 다른 글을 함께 읽으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"내가 몰랐던 면을 새로 알게 된다","correct":true},{"t":"읽어야 할 글이 줄어든다","mis":"K5-1-u5-X13"},{"t":"어느 글이 틀렸는지 바로 알게 된다","mis":"K5-1-u5-X12"},{"t":"한 가지 관점만 남게 된다","mis":"K5-1-u5-X13"}],"explanation":["오히려 더 읽어요.","틀린 글을 찾는 게 아니에요.","여러 관점으로 생각하게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_basic#10','kor',5,1,'u5','L02','g5_1_kor_u5_L02_basic','lesson_basic','K5-1-u5-C14',3,'mc','auto','두 글을 다 읽은 뒤의 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X14','K5-1-u5-X13','K5-1-u5-X12']::text[],false,'{"seq":10,"concept":"K5-1-u5-C14","difficulty":3,"kind":"mc","stem":"두 글을 다 읽은 뒤의 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 관점을 함께 살려 축제를 즐겁게 하되 낭비를 줄이는 방법을 생각해 본다","correct":true},{"t":"둘 중 하나를 골라 그 편만 들어야 한다","mis":"K5-1-u5-X14"},{"t":"어느 쪽도 맞지 않으니 생각하지 않는다","mis":"K5-1-u5-X13"},{"t":"먼저 읽은 글이 더 옳다","mis":"K5-1-u5-X12"}],"explanation":["하나를 꼭 골라야 하는 건 아니에요.","생각을 멈추면 안 돼요.","두 관점을 합치거나 나만의 관점을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#1','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C11',2,'ox','auto','관점은 제목 → 사진 → 표현 → 내용의 차례를 꼭 지켜야만 파악할 수 있어요.',ARRAY['K5-1-u5-X11']::text[],false,'{"seq":1,"concept":"K5-1-u5-C11","difficulty":2,"kind":"ox","stem":"관점은 제목 → 사진 → 표현 → 내용의 차례를 꼭 지켜야만 파악할 수 있어요.","answer":"X","reason_options":[{"t":"넷은 살펴볼 곳의 목록이어서 내용을 충분히 파악하는 것만으로도 관점을 알 수 있기 때문에","correct":true},{"t":"차례를 어기면 관점이 바뀌기 때문에","mis":"K5-1-u5-X11"}],"mis":"K5-1-u5-X11","explanation":["정해진 차례가 아니에요.","살펴볼 곳의 목록이에요.","내용 파악만으로도 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#2','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C12',2,'mc','auto','두 글쓴이의 관점이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X12','K5-1-u5-X07']::text[],false,'{"seq":2,"concept":"K5-1-u5-C12","difficulty":2,"kind":"mc","stem":"두 글쓴이의 관점이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겪은 일과 알고 있는 것이 서로 다르기 때문이다","correct":true},{"t":"한 글쓴이가 거짓말을 했기 때문이다","mis":"K5-1-u5-X12"},{"t":"한 글쓴이가 글을 잘 못 쓰기 때문이다","mis":"K5-1-u5-X12"},{"t":"두 글의 제목 글자 수가 다르기 때문이다","mis":"K5-1-u5-X07"}],"explanation":["거짓이 아니에요.","솜씨 문제가 아니에요.","경험과 아는 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#3','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C10',3,'error','auto','글 ㉯를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u5-X10','K5-1-u5-X14','K5-1-u5-X11']::text[],false,'{"seq":3,"concept":"K5-1-u5-C10","difficulty":3,"kind":"error","stem":"글 ㉯를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「문제점 · 낭비라는 말이 있으니 축제를 없애자는 글이야.」","correct":true,"mis_target":"K5-1-u5-X10"},{"t":"「문제점을 짚었지만 방식을 고치자는 거야.」","mis":"K5-1-u5-X14"},{"t":"「마지막 문장까지 읽어야 관점을 정확히 알 수 있어.」","mis":"K5-1-u5-X11"}],"explanation":["방식을 고치자는 말은 알맞아요.","끝까지 읽자는 말도 알맞아요.","몇 낱말만 보고 단정하면 잘못 읽어요."],"asset":{"type":"passage","lines":["학교 축제를 기다리는 학생이 많지만 문제점은 없는지도 살펴보아야 합니다.","먼저, 준비에 드는 시간이 지나치게 길어져 수업이 밀리기도 합니다.","또 무대에 서는 학생과 그렇지 않은 학생 사이에 차이가 생깁니다.","한 번 쓰고 버리는 장식과 소품이 많아 낭비가 생기기도 합니다.","따라서 축제를 열되 규모와 방식을 신중하게 정해야 합니다."],"title":"글 ㉯ 학교 축제, 다시 생각해 볼 점","hi":["문제점","길어져","차이","낭비","신중하게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#4','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C8',3,'mc','auto','두 글이 고른 낱말을 견주어 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X08','K5-1-u5-X19']::text[],false,'{"seq":4,"concept":"K5-1-u5-C8","difficulty":3,"kind":"mc","stem":"두 글이 고른 낱말을 견주어 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 대상을 다루어도 고른 낱말에 따라 관점이 드러난다","correct":true},{"t":"낱말은 다르지만 관점은 똑같다","mis":"K5-1-u5-X08"},{"t":"어려운 낱말을 쓴 글이 더 옳다","mis":"K5-1-u5-X19"},{"t":"낱말에는 생각이 담기지 않는다","mis":"K5-1-u5-X08"}],"explanation":["관점이 달라요.","어렵다고 옳은 건 아니에요.","고른 낱말에 생각이 스며요."],"asset":{"type":"passage","lines":["학교 축제를 기다리는 학생이 많지만 문제점은 없는지도 살펴보아야 합니다.","먼저, 준비에 드는 시간이 지나치게 길어져 수업이 밀리기도 합니다.","또 무대에 서는 학생과 그렇지 않은 학생 사이에 차이가 생깁니다.","한 번 쓰고 버리는 장식과 소품이 많아 낭비가 생기기도 합니다.","따라서 축제를 열되 규모와 방식을 신중하게 정해야 합니다."],"title":"글 ㉯ 학교 축제, 다시 생각해 볼 점","hi":["문제점","길어져","차이","낭비","신중하게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#5','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C9',3,'mc','auto','글 ㉯에 버려진 장식이 쌓인 사진을 함께 싣는다면, 그 사진으로 알 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u5-X09','K5-1-u5-X10','K5-1-u5-X19']::text[],false,'{"seq":5,"concept":"K5-1-u5-C9","difficulty":3,"kind":"mc","stem":"글 ㉯에 버려진 장식이 쌓인 사진을 함께 싣는다면, 그 사진으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"낭비를 걱정하는 글쓴이의 관점이 더 뚜렷해진다","correct":true},{"t":"사진은 꾸밈일 뿐 관점과 관계없다","mis":"K5-1-u5-X09"},{"t":"글쓴이가 축제를 더 크게 열자고 한다","mis":"K5-1-u5-X10"},{"t":"글이 더 길어져 믿을 만해진다","mis":"K5-1-u5-X19"}],"explanation":["사진에도 생각이 담겨요.","크게 열자는 뜻이 아니에요.","무엇을 담았는지가 관점을 뒷받침해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#6','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C13',3,'mc','auto','관점이 다른 글을 함께 읽은 뒤 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X21','K5-1-u5-X13','K5-1-u5-X12']::text[],false,'{"seq":6,"concept":"K5-1-u5-C13","difficulty":3,"kind":"mc","stem":"관점이 다른 글을 함께 읽은 뒤 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 글에서 새로 안 점을 바탕으로 내 생각을 다시 살펴본다","correct":true},{"t":"처음 내 생각과 같은 글만 기억한다","mis":"K5-1-u5-X21"},{"t":"헷갈리니 두 글을 모두 잊는다","mis":"K5-1-u5-X13"},{"t":"두 글 가운데 틀린 글을 찾는다","mis":"K5-1-u5-X12"}],"explanation":["같은 편만 남기면 좁아져요.","잊으면 배운 게 없어요.","틀린 글 찾기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#7','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C7',3,'mc','auto','제목만 보고 관점을 짐작한 뒤 꼭 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X10','K5-1-u5-X07','K5-1-u5-X12']::text[],false,'{"seq":7,"concept":"K5-1-u5-C7","difficulty":3,"kind":"mc","stem":"제목만 보고 관점을 짐작한 뒤 꼭 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 끝까지 읽고 짐작이 맞는지 확인한다","correct":true},{"t":"제목으로 짐작했으니 본문은 읽지 않는다","mis":"K5-1-u5-X10"},{"t":"제목의 글자 수를 센다","mis":"K5-1-u5-X07"},{"t":"짐작한 관점과 반대로 생각한다","mis":"K5-1-u5-X12"}],"explanation":["본문을 읽어야 해요.","글자 수는 관계없어요.","짐작은 끝까지 읽고 확인해요."],"asset":{"type":"passage","lines":["글 ㉮ — 학교 축제, 열면 좋은 점","글 ㉯ — 학교 축제, 다시 생각해 볼 점"],"title":"두 글의 제목"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#8','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C8',4,'essay','teacher','글 ㉮와 글 ㉯에서 관점이 드러나는 낱말을 두 개씩 찾아 쓰고, 그 낱말로 알 수 있는 두 글쓴이의 관점을 각각 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C8","difficulty":4,"kind":"essay","stem":"글 ㉮와 글 ㉯에서 관점이 드러나는 낱말을 두 개씩 찾아 쓰고, 그 낱말로 알 수 있는 두 글쓴이의 관점을 각각 쓰세요.","answer_guide":{"answer":"예: 글 ㉮는 「보람」 · 「추억」을 써서 축제가 주는 좋은 점에 무게를 두었다. 글 ㉯는 「문제점」 · 「낭비」를 써서 축제의 문제점을 살펴 신중하게 열자는 관점이다.","scoring_points":["글 ㉮의 낱말을 두 개 찾았는가","글 ㉯의 낱말을 두 개 찾았는가","두 글쓴이의 관점을 각각 썼는가"]},"explanation":["좋은 느낌의 낱말을 찾아요.","걱정하는 느낌의 낱말을 찾아요.","낱말로 관점을 정리해요."],"asset":{"type":"passage","lines":["학교 축제를 기다리는 학생이 많지만 문제점은 없는지도 살펴보아야 합니다.","먼저, 준비에 드는 시간이 지나치게 길어져 수업이 밀리기도 합니다.","또 무대에 서는 학생과 그렇지 않은 학생 사이에 차이가 생깁니다.","한 번 쓰고 버리는 장식과 소품이 많아 낭비가 생기기도 합니다.","따라서 축제를 열되 규모와 방식을 신중하게 정해야 합니다."],"title":"글 ㉯ 학교 축제, 다시 생각해 볼 점","hi":["문제점","길어져","차이","낭비","신중하게"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#9','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C14',4,'essay','teacher','두 글을 읽고 두 관점을 함께 살리는 나만의 생각을 쓰세요. 한쪽 편만 들지 않았다는 것이 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C14","difficulty":4,"kind":"essay","stem":"두 글을 읽고 두 관점을 함께 살리는 나만의 생각을 쓰세요. 한쪽 편만 들지 않았다는 것이 드러나게 쓰세요.","answer_guide":{"answer":"예: 축제는 친구를 새로 알고 추억을 남기는 좋은 점이 있으니 열면 좋겠다. 다만 준비는 몇 주가 아니라 짧게 하고, 장식은 다시 쓸 수 있는 것으로 만들어 낭비를 줄이며, 모두 한 가지씩 맡게 해 빠지는 학생이 없게 하면 좋겠다.","scoring_points":["글 ㉮의 관점을 살렸는가","글 ㉯의 관점을 살렸는가","두 관점을 합친 나만의 생각을 썼는가"]},"explanation":["좋은 점은 무엇이었나요?","걱정은 무엇이었나요?","둘을 함께 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L02_challenge#10','kor',5,1,'u5','L02','g5_1_kor_u5_L02_challenge','lesson_challenge','K5-1-u5-C12',4,'essay','teacher','「관점은 맞고 틀림이 아니라 서로 다름이다」라는 말을 두 글쓴이의 예를 들어 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C12","difficulty":4,"kind":"essay","stem":"「관점은 맞고 틀림이 아니라 서로 다름이다」라는 말을 두 글쓴이의 예를 들어 설명하세요.","answer_guide":{"answer":"예: 글 ㉮의 글쓴이는 축제에서 친구를 새로 알게 된 경험을 중요하게 보았고, 글 ㉯의 글쓴이는 준비가 길어지고 낭비가 생기는 점을 중요하게 보았다. 겪은 일과 알고 있는 것이 달라 같은 축제를 다르게 본 것일 뿐 누가 틀린 것은 아니다.","scoring_points":["두 글쓴이가 중요하게 본 것을 썼는가","관점이 다른 까닭을 썼는가","틀림이 아니라 다름이라고 정리했는가"]},"explanation":["각자 무엇을 중요하게 보았나요?","왜 다르게 보았나요?","맞고 틀림으로 가를 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#1','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C16',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K5-1-u5-C16","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"대여","r":"물건을 빌려줌"},{"l":"반납","r":"빌린 것을 도로 돌려줌"},{"l":"훼손","r":"헐거나 깨뜨려 못 쓰게 함"}],"mis":"K5-1-u5-X16","explanation":["빌려주는 일이에요.","돌려주는 일이에요.","못 쓰게 되는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#2','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C16',1,'mc','auto','「맡아서 돌보고 살핌」이라는 뜻을 가진 낱말은 어느 것인가요?',ARRAY['K5-1-u5-X16']::text[],false,'{"seq":2,"concept":"K5-1-u5-C16","difficulty":1,"kind":"mc","stem":"「맡아서 돌보고 살핌」이라는 뜻을 가진 낱말은 어느 것인가요?","options":[{"t":"관리","correct":true},{"t":"대여","mis":"K5-1-u5-X16"},{"t":"반납","mis":"K5-1-u5-X16"},{"t":"훼손","mis":"K5-1-u5-X16"}],"explanation":["빌려줌이에요.","돌려줌이에요.","돌보고 살피는 일이 관리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#3','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C17',1,'mc','auto','글 ㉰ 안내문에 담긴 관점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X17']::text[],false,'{"seq":3,"concept":"K5-1-u5-C17","difficulty":1,"kind":"mc","stem":"글 ㉰ 안내문에 담긴 관점으로 알맞은 것은 어느 것인가요?","options":[{"t":"모두의 물건이니 함께 지키자","correct":true},{"t":"대여함을 없애야 한다","mis":"K5-1-u5-X17"},{"t":"우산을 더 많이 사야 한다","mis":"K5-1-u5-X17"},{"t":"안내문에는 관점이 없다","mis":"K5-1-u5-X17"}],"explanation":["없애자는 말은 없어요.","사자는 말도 없어요.","마지막 줄을 다시 봐요."],"asset":{"type":"passage","lines":["이름과 날짜를 적고 빌려 주세요.","다음 날 등교할 때 돌려 주세요.","고장 난 우산은 옆 상자에 넣어 주세요.","모두의 우산입니다. 소중히 써 주세요."],"title":"글 ㉰ 현관에 붙은 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#4','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C15',1,'mc','auto','글 ㉯가 보여 준 면으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X15','K5-1-u5-X22']::text[],false,'{"seq":4,"concept":"K5-1-u5-C15","difficulty":1,"kind":"mc","stem":"글 ㉯가 보여 준 면으로 알맞은 것은 어느 것인가요?","options":[{"t":"우산이 돌아오지 않아 줄어든 사실","correct":true},{"t":"대여함이 주는 좋은 점","mis":"K5-1-u5-X15"},{"t":"빌릴 때 지켜야 할 규칙","mis":"K5-1-u5-X15"},{"t":"비 오는 날의 날씨","mis":"K5-1-u5-X22"}],"explanation":["그건 글 ㉮가 보여 줬어요.","그건 글 ㉰가 보여 줬어요.","서른 개가 여덟 개가 된 사실이에요."],"asset":{"type":"passage","lines":["편해졌다는 학생이 많지만, 지금 방식이 오래갈지는 따져 보아야 합니다.","먼저, 돌려놓지 않는 일이 많아 서른 개였던 우산이 여덟 개만 남았습니다.","또 살이 부러진 우산이 그대로 꽂혀 있어 다음 사람이 헛걸음을 합니다.","고치거나 빼내는 사람이 정해져 있지 않기 때문입니다.","대여함을 이어 가려면 관리하는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 우산 대여함, 이대로 괜찮을까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#5','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C22',2,'mc','auto','토의로 다룰 만한 문제 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22']::text[],false,'{"seq":5,"concept":"K5-1-u5-C22","difficulty":2,"kind":"mc","stem":"토의로 다룰 만한 문제 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"빌린 우산이 돌아오게 하려면 어떻게 해야 할까","correct":true},{"t":"지금 남은 우산은 몇 개일까","mis":"K5-1-u5-X22"},{"t":"내일 비가 올까","mis":"K5-1-u5-X22"},{"t":"우산의 색은 무엇일까","mis":"K5-1-u5-X22"}],"explanation":["세어 보면 답이 나와요.","날씨는 토의할 문제가 아니에요.","여럿이 방법을 모아야 하는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#6','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C19',2,'mc','auto','글의 내용을 신뢰할 수 있는지 판단할 근거로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X19','K5-1-u5-X18']::text[],false,'{"seq":6,"concept":"K5-1-u5-C19","difficulty":2,"kind":"mc","stem":"글의 내용을 신뢰할 수 있는지 판단할 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"확인할 수 있는 숫자나 사실을 들었는가","correct":true},{"t":"글이 길고 어려운 낱말이 많은가","mis":"K5-1-u5-X19"},{"t":"내 생각과 같은 편인가","mis":"K5-1-u5-X19"},{"t":"글씨가 크고 반듯한가","mis":"K5-1-u5-X18"}],"explanation":["길고 어렵다고 믿을 만한 건 아니에요.","같은 편이라고 믿을 만한 건 아니에요.","확인할 수 있는 근거가 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#7','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C23',2,'mc','auto','대여함 문제를 해결할 방법 가운데 실천하기에 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X23']::text[],false,'{"seq":7,"concept":"K5-1-u5-C23","difficulty":2,"kind":"mc","stem":"대여함 문제를 해결할 방법 가운데 실천하기에 알맞은 것은 어느 것인가요?","options":[{"t":"반납 날짜를 적은 표를 대여함 옆에 붙이기","correct":true},{"t":"우산을 빌려 가는 학생의 이름을 방송으로 알리기","mis":"K5-1-u5-X23"},{"t":"우산을 아예 빌려주지 않기","mis":"K5-1-u5-X23"},{"t":"우산이 없어질 때마다 새로 사기","mis":"K5-1-u5-X23"}],"explanation":["창피를 주면 새 문제가 생겨요.","없애면 좋은 점도 사라져요.","누구나 꾸준히 할 수 있는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#8','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C21',2,'ox','auto','글을 더 찾아 읽을 때는 내 생각과 같은 관점의 글만 모으면 돼요.',ARRAY['K5-1-u5-X21']::text[],false,'{"seq":8,"concept":"K5-1-u5-C21","difficulty":2,"kind":"ox","stem":"글을 더 찾아 읽을 때는 내 생각과 같은 관점의 글만 모으면 돼요.","answer":"X","reason_options":[{"t":"관점이 다른 글도 함께 읽어야 보이지 않던 문제를 찾고 더 나은 방법이 나오기 때문에","correct":true},{"t":"다른 관점의 글은 헷갈리게만 하기 때문에","mis":"K5-1-u5-X21"}],"mis":"K5-1-u5-X21","explanation":["같은 편만 모으면 좁아져요.","글 ㉯가 없었다면?","다른 관점 글도 함께 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#9','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C20',2,'mc','auto','세 글을 겹쳐 보았을 때 드러나는 문제 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X20','K5-1-u5-X22','K5-1-u5-X23']::text[],false,'{"seq":9,"concept":"K5-1-u5-C20","difficulty":2,"kind":"mc","stem":"세 글을 겹쳐 보았을 때 드러나는 문제 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"공용 우산 대여함을 어떻게 하면 오래 이어 갈 수 있을까?","correct":true},{"t":"우산은 어느 가게에서 사는 것이 좋을까?","mis":"K5-1-u5-X20"},{"t":"대여함은 언제 처음 생겼을까?","mis":"K5-1-u5-X22"},{"t":"누가 우산을 가장 많이 빌렸을까?","mis":"K5-1-u5-X23"}],"explanation":["글에 없는 이야기예요.","답이 하나로 정해져요.","좋은 점 · 사실 · 규칙을 겹쳐 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_basic#10','kor',5,1,'u5','L04','g5_1_kor_u5_L04_basic','lesson_basic','K5-1-u5-C18',3,'mc','auto','읽은 글을 평가하는 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X18']::text[],false,'{"seq":10,"concept":"K5-1-u5-C18","difficulty":3,"kind":"mc","stem":"읽은 글을 평가하는 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글이 몇 줄인가","correct":true},{"t":"제목이 글의 내용을 잘 나타내는가","mis":"K5-1-u5-X18"},{"t":"표현과 그림이 글쓴이의 관점을 뒷받침하는가","mis":"K5-1-u5-X18"},{"t":"내 생각과 비슷한 점이 있는가","mis":"K5-1-u5-X18"}],"explanation":["제목도 평가 기준이에요.","표현과 그림도 기준이에요.","글의 길이는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#1','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C17',2,'ox','auto','안내문은 규칙만 알리는 글이어서 관점이 담기지 않아요.',ARRAY['K5-1-u5-X17']::text[],false,'{"seq":1,"concept":"K5-1-u5-C17","difficulty":2,"kind":"ox","stem":"안내문은 규칙만 알리는 글이어서 관점이 담기지 않아요.","answer":"X","reason_options":[{"t":"「모두의 우산입니다. 소중히 써 주세요」처럼 짧은 글에도 생각이 담기기 때문에","correct":true},{"t":"안내문은 아무나 쓸 수 있는 글이기 때문에","mis":"K5-1-u5-X17"}],"mis":"K5-1-u5-X17","explanation":["짧아도 생각이 담겨요.","마지막 줄을 봐요.","함께 지키자는 관점이에요."],"asset":{"type":"passage","lines":["이름과 날짜를 적고 빌려 주세요.","다음 날 등교할 때 돌려 주세요.","고장 난 우산은 옆 상자에 넣어 주세요.","모두의 우산입니다. 소중히 써 주세요."],"title":"글 ㉰ 현관에 붙은 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#2','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C19',2,'mc','auto','글 ㉯가 글 ㉮보다 신뢰할 만한 근거를 더 갖춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X19','K5-1-u5-X12']::text[],false,'{"seq":2,"concept":"K5-1-u5-C19","difficulty":2,"kind":"mc","stem":"글 ㉯가 글 ㉮보다 신뢰할 만한 근거를 더 갖춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"서른 개였던 우산이 여덟 개만 남았다는 확인할 수 있는 사실을 들었기 때문이다","correct":true},{"t":"글 ㉯가 더 길기 때문이다","mis":"K5-1-u5-X19"},{"t":"글 ㉯가 걱정하는 내용이기 때문이다","mis":"K5-1-u5-X12"},{"t":"글 ㉯의 낱말이 더 어렵기 때문이다","mis":"K5-1-u5-X19"}],"explanation":["길이는 근거가 아니에요.","걱정한다고 믿을 만한 건 아니에요.","확인할 수 있는 숫자가 있어요."],"asset":{"type":"passage","lines":["편해졌다는 학생이 많지만, 지금 방식이 오래갈지는 따져 보아야 합니다.","먼저, 돌려놓지 않는 일이 많아 서른 개였던 우산이 여덟 개만 남았습니다.","또 살이 부러진 우산이 그대로 꽂혀 있어 다음 사람이 헛걸음을 합니다.","고치거나 빼내는 사람이 정해져 있지 않기 때문입니다.","대여함을 이어 가려면 관리하는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 우산 대여함, 이대로 괜찮을까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#3','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C21',3,'error','auto','대여함 문제를 두고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u5-X21','K5-1-u5-X15','K5-1-u5-X19']::text[],false,'{"seq":3,"concept":"K5-1-u5-C21","difficulty":3,"kind":"error","stem":"대여함 문제를 두고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「나는 대여함이 좋으니까 좋은 점을 쓴 글만 더 찾아 읽을래.」","correct":true,"mis_target":"K5-1-u5-X21"},{"t":"「글 ㉯가 없었다면 우산이 줄어드는 문제를 놓쳤을 거야.」","mis":"K5-1-u5-X15"},{"t":"「출처가 분명한 글인지도 살펴보자.」","mis":"K5-1-u5-X19"}],"explanation":["글 ㉯의 쓸모를 말했어요.","출처를 살피자는 말은 알맞아요.","같은 편 글만 모으면 문제가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#4','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C15',3,'mc','auto','세 글이 저마다 보여 준 면을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u5-X15']::text[],false,'{"seq":4,"concept":"K5-1-u5-C15","difficulty":3,"kind":"mc","stem":"세 글이 저마다 보여 준 면을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉮ 좋은 점 · ㉯ 줄어든 사실과 관리 문제 · ㉰ 지킬 규칙","correct":true},{"t":"㉮ 지킬 규칙 · ㉯ 좋은 점 · ㉰ 줄어든 사실","mis":"K5-1-u5-X15"},{"t":"㉮ 줄어든 사실 · ㉯ 지킬 규칙 · ㉰ 좋은 점","mis":"K5-1-u5-X15"},{"t":"세 글 모두 같은 면을 보여 주었다","mis":"K5-1-u5-X15"}],"explanation":["㉮는 고마운 장치라고 했어요.","㉯는 숫자로 문제를 짚었어요.","저마다 다른 면을 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#5','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C23',3,'mc','auto','「우산을 아예 빌려주지 않기」가 알맞은 해결 방법이 아닌 까닭은 무엇인가요?',ARRAY['K5-1-u5-X23','K5-1-u5-X10']::text[],false,'{"seq":5,"concept":"K5-1-u5-C23","difficulty":3,"kind":"mc","stem":"「우산을 아예 빌려주지 않기」가 알맞은 해결 방법이 아닌 까닭은 무엇인가요?","options":[{"t":"대여함이 주던 좋은 점까지 사라져 새로운 불편이 생기기 때문이다","correct":true},{"t":"그 방법은 누구나 할 수 있기 때문이다","mis":"K5-1-u5-X23"},{"t":"글 ㉯의 글쓴이가 그렇게 하자고 했기 때문이다","mis":"K5-1-u5-X10"},{"t":"우산의 수가 늘어나기 때문이다","mis":"K5-1-u5-X23"}],"explanation":["누구나 할 수 있어도 문제가 생겨요.","글 ㉯는 관리 방법을 정하자고 했어요.","새 문제를 만들면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#6','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C20',3,'mc','auto','문제 상황을 정할 때 세 글을 함께 써야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X04','K5-1-u5-X15','K5-1-u5-X20']::text[],false,'{"seq":6,"concept":"K5-1-u5-C20","difficulty":3,"kind":"mc","stem":"문제 상황을 정할 때 세 글을 함께 써야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 글만으로는 보이지 않던 문제가 여러 글을 겹쳐야 드러나기 때문이다","correct":true},{"t":"글이 많을수록 점수가 높기 때문이다","mis":"K5-1-u5-X04"},{"t":"세 글이 모두 같은 말을 하기 때문이다","mis":"K5-1-u5-X15"},{"t":"글 ㉰만 읽어도 충분하기 때문이다","mis":"K5-1-u5-X20"}],"explanation":["수가 목적이 아니에요.","세 글은 서로 달라요.","겹쳐야 문제가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#7','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C18',3,'mc','auto','글 ㉮를 「내 생각과 비슷한 점이 있는가」로 평가하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X19','K5-1-u5-X12','K5-1-u5-X18']::text[],false,'{"seq":7,"concept":"K5-1-u5-C18","difficulty":3,"kind":"mc","stem":"글 ㉮를 「내 생각과 비슷한 점이 있는가」로 평가하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각과 견주어 보며 생각을 넓히거나 다시 살펴보려고","correct":true},{"t":"내 생각과 같으면 믿을 만한 글이기 때문에","mis":"K5-1-u5-X19"},{"t":"내 생각과 다르면 틀린 글이기 때문에","mis":"K5-1-u5-X12"},{"t":"글의 길이를 알아보려고","mis":"K5-1-u5-X18"}],"explanation":["같다고 믿을 만한 건 아니에요.","다르다고 틀린 건 아니에요.","내 생각을 넓히는 기준이에요."],"asset":{"type":"passage","lines":["현관의 공용 우산 대여함은 곤란을 덜어 주는 고마운 장치입니다.","먼저, 누구나 부담 없이 씁니다. 이름을 적고 빌린 뒤 다음 날 돌려놓으면 됩니다.","또 급하게 우산을 새로 사는 일이 줄어 낭비를 줄일 수 있습니다.","이처럼 대여함은 작지만 쓸모 있는 나눔입니다. 잘 이어졌으면 합니다."],"title":"글 ㉮ 우산 대여함, 있어서 다행입니다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#8','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C23',4,'essay','teacher','대여함 문제를 해결할 방법을 하나 정해 쓰고, 그 방법이 누구나 할 수 있는지 · 꾸준히 할 수 있는지 · 새 문제를 만들지 않는지 따져 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C23","difficulty":4,"kind":"essay","stem":"대여함 문제를 해결할 방법을 하나 정해 쓰고, 그 방법이 누구나 할 수 있는지 · 꾸준히 할 수 있는지 · 새 문제를 만들지 않는지 따져 쓰세요.","answer_guide":{"answer":"예: 학급마다 돌아가며 한 주씩 대여함을 살피는 방법이 좋겠다. 반마다 한 주만 맡으니 누구나 할 수 있고, 차례가 돌아오니 꾸준히 이어 갈 수 있다. 누구를 탓하거나 창피를 주지 않아 새 문제도 만들지 않는다.","scoring_points":["해결 방법을 하나 정했는가","세 가지 기준으로 따졌는가","새 문제가 생기지 않는 까닭을 썼는가"]},"explanation":["어떤 방법인가요?","누구나 · 꾸준히 할 수 있나요?","새 문제는 없나요?"],"asset":{"type":"passage","lines":["편해졌다는 학생이 많지만, 지금 방식이 오래갈지는 따져 보아야 합니다.","먼저, 돌려놓지 않는 일이 많아 서른 개였던 우산이 여덟 개만 남았습니다.","또 살이 부러진 우산이 그대로 꽂혀 있어 다음 사람이 헛걸음을 합니다.","고치거나 빼내는 사람이 정해져 있지 않기 때문입니다.","대여함을 이어 가려면 관리하는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 우산 대여함, 이대로 괜찮을까"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#9','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C19',4,'essay','teacher','글을 신뢰할 수 있는지 판단할 때 살펴볼 점을 두 가지 쓰고, 「길고 어려운 글」이 믿을 만한 글이라는 생각이 왜 알맞지 않은지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C19","difficulty":4,"kind":"essay","stem":"글을 신뢰할 수 있는지 판단할 때 살펴볼 점을 두 가지 쓰고, 「길고 어려운 글」이 믿을 만한 글이라는 생각이 왜 알맞지 않은지 쓰세요.","answer_guide":{"answer":"예: 확인할 수 있는 숫자나 사실을 들었는지, 글의 출처가 분명한지 살펴본다. 글이 길고 어려운 낱말이 많아도 근거가 없거나 한쪽만 부풀렸을 수 있으므로 길이나 낱말로 믿을 만한지 판단할 수 없다.","scoring_points":["살펴볼 점을 두 가지 썼는가","길고 어려운 글에 대한 생각을 바로잡았는가","근거와 출처를 기준으로 삼았는가"]},"explanation":["무엇을 확인하나요?","길이와 믿음은 관계있나요?","근거와 출처를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L04_challenge#10','kor',5,1,'u5','L04','g5_1_kor_u5_L04_challenge','lesson_challenge','K5-1-u5-C21',4,'essay','teacher','「같은 편 글만 모으지 않는다」는 말을 우산 대여함 이야기로 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C21","difficulty":4,"kind":"essay","stem":"「같은 편 글만 모으지 않는다」는 말을 우산 대여함 이야기로 설명하세요.","answer_guide":{"answer":"예: 대여함이 좋다고 생각해 글 ㉮ 같은 글만 모았다면 우산이 돌아오지 않아 줄어드는 문제를 몰랐을 것이다. 문제점을 짚은 글 ㉯를 함께 읽었기 때문에 관리 방법을 정해야 한다는 해결할 문제가 드러났다. 관점이 다른 글도 함께 읽어야 더 나은 해결 방법을 찾을 수 있다.","scoring_points":["같은 편 글만 모았을 때를 썼는가","글 ㉯를 함께 읽어 얻은 점을 썼는가","다른 관점 글을 함께 읽는 까닭을 정리했는가"]},"explanation":["글 ㉮만 읽었다면?","글 ㉯는 무엇을 보여 주었나요?","왜 함께 읽어야 할까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#1','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C24',1,'mc','auto','토의 절차에서 「의견 마련하기」 바로 다음에 하는 일은 무엇인가요?',ARRAY['K5-1-u5-X24']::text[],false,'{"seq":1,"concept":"K5-1-u5-C24","difficulty":1,"kind":"mc","stem":"토의 절차에서 「의견 마련하기」 바로 다음에 하는 일은 무엇인가요?","options":[{"t":"의견 나누기","correct":true},{"t":"토의 주제 정하기","mis":"K5-1-u5-X24"},{"t":"의견 모으기","mis":"K5-1-u5-X24"},{"t":"의견 결정하기","mis":"K5-1-u5-X24"}],"explanation":["주제 정하기가 맨 처음이에요.","모으기는 나누기 다음이에요.","마련한 의견을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#2','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C26',1,'mc','auto','서진이의 「네 말은 도움이 하나도 안 돼.」가 문제인 까닭은 무엇인가요?',ARRAY['K5-1-u5-X26','K5-1-u5-X32']::text[],false,'{"seq":2,"concept":"K5-1-u5-C26","difficulty":1,"kind":"mc","stem":"서진이의 「네 말은 도움이 하나도 안 돼.」가 문제인 까닭은 무엇인가요?","options":[{"t":"의견이 아니라 사람을 깎아내리는 말이어서","correct":true},{"t":"목소리가 너무 작아서","mis":"K5-1-u5-X26"},{"t":"말이 너무 길어서","mis":"K5-1-u5-X26"},{"t":"사회자가 시키지 않아서","mis":"K5-1-u5-X32"}],"explanation":["목소리와 관계없어요.","길이와도 관계없어요.","사람을 탓하는 말이에요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"책마다 색 스티커를 붙여 갈래를 나누면 좋겠어요. 색만 맞춰 꽂으면 되니까요."},{"who":"태이","text":"그건 별로인 것 같아요."},{"who":"하윤","text":"왜 그렇게 생각하나요?"},{"who":"태이","text":"특별한 이유는 없어요. 그리고 저는 도서관에 새 책이 많이 들어왔으면 좋겠어요."},{"who":"서진","text":"(짜증스럽게) 그게 지금 주제랑 무슨 상관이야. 네 말은 도움이 하나도 안 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#3','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C27',1,'mc','auto','의견을 나누고 검토할 때 알맞은 모습은 어느 것인가요?',ARRAY['K5-1-u5-X27','K5-1-u5-X31']::text[],false,'{"seq":3,"concept":"K5-1-u5-C27","difficulty":1,"kind":"mc","stem":"의견을 나누고 검토할 때 알맞은 모습은 어느 것인가요?","options":[{"t":"의견에 이유를 붙여 말한다","correct":true},{"t":"의견만 짧게 말하고 이유는 숨긴다","mis":"K5-1-u5-X27"},{"t":"다른 사람의 의견은 따져 보지 않는다","mis":"K5-1-u5-X27"},{"t":"이유 없이 반대한다","mis":"K5-1-u5-X31"}],"explanation":["이유가 있어야 다듬어져요.","서로 따져 봐야 해요.","의견 + 이유로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#4','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C28',1,'match','auto','협력하며 토의하는 방법과 알맞은 행동을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u5-C28","difficulty":1,"kind":"match","stem":"협력하며 토의하는 방법과 알맞은 행동을 이으세요.","pairs":[{"l":"의견을 나누고 검토하기","r":"의견에 이유를 붙여 말한다"},{"l":"존중하는 태도로 토의하기","r":"말을 끊지 않고 끝까지 듣는다"},{"l":"협력하며 토의 진행하기","r":"주제에서 벗어나면 부드럽게 되돌린다"}],"mis":"K5-1-u5-X30","explanation":["이유가 있어요.","끝까지 들어요.","주제를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#5','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C25',2,'mc','auto','토의 장면에서 드러난 문제점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X25','K5-1-u5-X31','K5-1-u5-X29']::text[],false,'{"seq":5,"concept":"K5-1-u5-C25","difficulty":2,"kind":"mc","stem":"토의 장면에서 드러난 문제점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"사회자가 이유를 물어보았다","correct":true},{"t":"주제를 집중해서 듣지 않았다","mis":"K5-1-u5-X25"},{"t":"이유 없이 반대했다","mis":"K5-1-u5-X31"},{"t":"주제와 관련 없는 의견을 냈다","mis":"K5-1-u5-X29"}],"explanation":["태이는 주제를 놓쳤어요.","「특별한 이유는 없어요」였어요.","이유를 묻는 것은 토의를 돕는 일이에요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"책마다 색 스티커를 붙여 갈래를 나누면 좋겠어요. 색만 맞춰 꽂으면 되니까요."},{"who":"태이","text":"그건 별로인 것 같아요."},{"who":"하윤","text":"왜 그렇게 생각하나요?"},{"who":"태이","text":"특별한 이유는 없어요. 그리고 저는 도서관에 새 책이 많이 들어왔으면 좋겠어요."},{"who":"서진","text":"(짜증스럽게) 그게 지금 주제랑 무슨 상관이야. 네 말은 도움이 하나도 안 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#6','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C31',2,'mc','auto','은채의 의견에 반대하고 싶을 때 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u5-X31','K5-1-u5-X26']::text[],false,'{"seq":6,"concept":"K5-1-u5-C31","difficulty":2,"kind":"mc","stem":"은채의 의견에 반대하고 싶을 때 알맞은 말은 어느 것인가요?","options":[{"t":"「스티커가 떨어질 수 있어서 걱정돼요. 다른 방법은 없을까요?」","correct":true},{"t":"「그건 별로예요. 그냥 그렇게 생각해요.」","mis":"K5-1-u5-X31"},{"t":"「네 말은 도움이 하나도 안 돼.」","mis":"K5-1-u5-X26"},{"t":"「반대하면 다투게 되니 그냥 따를게요.」","mis":"K5-1-u5-X31"}],"explanation":["이유 없는 반대예요.","사람을 겨눈 말이에요.","반대 + 이유로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#7','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C29',2,'mc','auto','태이가 「새 책 이야기」를 했을 때 협력하며 진행하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X26','K5-1-u5-X29']::text[],false,'{"seq":7,"concept":"K5-1-u5-C29","difficulty":2,"kind":"mc","stem":"태이가 「새 책 이야기」를 했을 때 협력하며 진행하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「새 책도 좋지만, 지금은 있는 책을 정리하는 방법을 먼저 이야기해 볼까요?」","correct":true},{"t":"「그 얘기는 그만해.」","mis":"K5-1-u5-X26"},{"t":"「새 책 이야기를 계속해 봐요.」","mis":"K5-1-u5-X29"},{"t":"(아무 말 없이 넘어간다)","mis":"K5-1-u5-X29"}],"explanation":["핀잔이 되면 안 돼요.","주제에서 더 멀어져요.","부드럽게 주제로 되돌려요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"책마다 색 스티커를 붙여 갈래를 나누면 좋겠어요. 색만 맞춰 꽂으면 되니까요."},{"who":"태이","text":"그건 별로인 것 같아요."},{"who":"하윤","text":"왜 그렇게 생각하나요?"},{"who":"태이","text":"특별한 이유는 없어요. 그리고 저는 도서관에 새 책이 많이 들어왔으면 좋겠어요."},{"who":"서진","text":"(짜증스럽게) 그게 지금 주제랑 무슨 상관이야. 네 말은 도움이 하나도 안 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#8','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C32',2,'ox','auto','토의를 이끄는 일은 사회자 한 사람만 할 수 있어요.',ARRAY['K5-1-u5-X32']::text[],false,'{"seq":8,"concept":"K5-1-u5-C32","difficulty":2,"kind":"ox","stem":"토의를 이끄는 일은 사회자 한 사람만 할 수 있어요.","answer":"X","reason_options":[{"t":"주제로 되돌리기 · 차례 넘기기 · 이유 묻기는 모두가 할 수 있는 일이기 때문에","correct":true},{"t":"사회자가 아닌 사람은 말할 수 없기 때문에","mis":"K5-1-u5-X32"}],"mis":"K5-1-u5-X32","explanation":["모두가 할 수 있어요.","차례 넘기기를 떠올려요.","협력은 모두의 몫이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#9','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C28',2,'mc','auto','태이가 서진이의 말을 끊은 것이 문제인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X28','K5-1-u5-X32','K5-1-u5-X26']::text[],false,'{"seq":9,"concept":"K5-1-u5-C28","difficulty":2,"kind":"mc","stem":"태이가 서진이의 말을 끊은 것이 문제인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"끝까지 듣지 않으면 상대가 마음 놓고 말하지 못하기 때문이다","correct":true},{"t":"말을 끊으면 토의가 빨리 끝나기 때문이다","mis":"K5-1-u5-X28"},{"t":"서진이가 사회자이기 때문이다","mis":"K5-1-u5-X32"},{"t":"태이의 목소리가 작았기 때문이다","mis":"K5-1-u5-X26"}],"explanation":["빨리 끝나는 게 문제가 아니에요.","서진이는 사회자가 아니에요.","끝까지 들어야 존중이에요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"지금까지 나온 의견을 모아 볼게요. 색 스티커로 갈래 나누기, 새 책 들여오기입니다."},{"who":"서진","text":"새 책 들여오기는 주제와 관련이 없으니 빼야 한다고 생각해요. 그리고……."},{"who":"태이","text":"(말을 끊으며) 새 책이 들어오면 정리도 새로 하게 되잖아요."},{"who":"서진","text":"그렇게 자기 생각만 우기면 어떡해요?"},{"who":"하윤","text":"시간이 다 됐네요. 일단 여기까지 하죠……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_basic#10','kor',5,1,'u5','L07','g5_1_kor_u5_L07_basic','lesson_basic','K5-1-u5-C30',3,'mc','auto','협력하며 토의하는 세 방법이 함께 있어야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X30','K5-1-u5-X32']::text[],false,'{"seq":10,"concept":"K5-1-u5-C30","difficulty":3,"kind":"mc","stem":"협력하며 토의하는 세 방법이 함께 있어야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"생각을 다듬고, 마음 놓고 말하고, 결론에 이르는 일이 모두 있어야 토의가 끝까지 가기 때문이다","correct":true},{"t":"셋 가운데 하나만 지켜도 토의는 잘되기 때문이다","mis":"K5-1-u5-X30"},{"t":"세 방법을 외우면 토의를 안 해도 되기 때문이다","mis":"K5-1-u5-X30"},{"t":"사회자가 셋을 모두 맡기 때문이다","mis":"K5-1-u5-X32"}],"explanation":["하나로는 부족해요.","외우기가 목적이 아니에요.","셋이 함께여야 결론까지 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#1','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C31',2,'ox','auto','토의에서 다른 의견에 반대하는 것은 협력을 깨는 일이에요.',ARRAY['K5-1-u5-X31']::text[],false,'{"seq":1,"concept":"K5-1-u5-C31","difficulty":2,"kind":"ox","stem":"토의에서 다른 의견에 반대하는 것은 협력을 깨는 일이에요.","answer":"X","reason_options":[{"t":"걱정되는 점과 이유를 들어 의견에 대해 반대하면 의견이 다듬어지기 때문에","correct":true},{"t":"반대하는 사람은 토의에 끼면 안 되기 때문에","mis":"K5-1-u5-X31"}],"mis":"K5-1-u5-X31","explanation":["반대 자체는 문제가 아니에요.","이유가 함께 있어야 해요.","문제는 이유 없는 반대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#2','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C24',2,'mc','auto','토의 절차를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K5-1-u5-X24']::text[],false,'{"seq":2,"concept":"K5-1-u5-C24","difficulty":2,"kind":"mc","stem":"토의 절차를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 결정하기","correct":true},{"t":"의견 결정하기 → 주제 정하기 → 의견 나누기 → 의견 모으기 → 의견 마련하기","mis":"K5-1-u5-X24"},{"t":"의견 나누기 → 주제 정하기 → 의견 결정하기 → 의견 마련하기 → 의견 모으기","mis":"K5-1-u5-X24"},{"t":"주제 정하기 → 의견 결정하기 → 의견 마련하기 → 의견 모으기 → 의견 나누기","mis":"K5-1-u5-X24"}],"explanation":["결정은 맨 끝이에요.","주제가 먼저예요.","정하기 → 마련 → 나누기 → 모으기 → 결정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#3','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C25',3,'error','auto','토의 장면 ③을 보고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u5-X25','K5-1-u5-X28','K5-1-u5-X26']::text[],false,'{"seq":3,"concept":"K5-1-u5-C25","difficulty":3,"kind":"error","stem":"토의 장면 ③을 보고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「사회자가 의견을 모아 정리한 것이 이 토의의 문제점이야.」","correct":true,"mis_target":"K5-1-u5-X25"},{"t":"「태이가 말을 끊은 것은 존중하는 태도가 아니야.」","mis":"K5-1-u5-X28"},{"t":"「서진이가 자기 생각만 우긴다고 몰아세운 것도 문제야.」","mis":"K5-1-u5-X26"}],"explanation":["말 끊기는 문제예요.","몰아세우는 말도 문제예요.","의견을 모으는 것은 토의를 돕는 일이에요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"지금까지 나온 의견을 모아 볼게요. 색 스티커로 갈래 나누기, 새 책 들여오기입니다."},{"who":"서진","text":"새 책 들여오기는 주제와 관련이 없으니 빼야 한다고 생각해요. 그리고……."},{"who":"태이","text":"(말을 끊으며) 새 책이 들어오면 정리도 새로 하게 되잖아요."},{"who":"서진","text":"그렇게 자기 생각만 우기면 어떡해요?"},{"who":"하윤","text":"시간이 다 됐네요. 일단 여기까지 하죠……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#4','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C26',3,'mc','auto','「네 말은 도움이 하나도 안 돼.」를 협력하는 말로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u5-X26','K5-1-u5-X25']::text[],false,'{"seq":4,"concept":"K5-1-u5-C26","difficulty":3,"kind":"mc","stem":"「네 말은 도움이 하나도 안 돼.」를 협력하는 말로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"「새 책 이야기는 지금 주제와 조금 멀어 보여요. 정리 방법과 이어지는 점이 있을까요?」","correct":true},{"t":"「너는 늘 엉뚱한 말만 하더라.」","mis":"K5-1-u5-X26"},{"t":"「네 말은 도움이 조금도 안 돼.」","mis":"K5-1-u5-X26"},{"t":"「됐어, 그 얘기는 그만해.」","mis":"K5-1-u5-X25"}],"explanation":["또 사람을 탓해요.","말만 바꿨지 같은 뜻이에요.","사람이 아니라 의견을 다뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#5','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C32',3,'mc','auto','협력하며 토의하는 방법에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X32','K5-1-u5-X31']::text[],false,'{"seq":5,"concept":"K5-1-u5-C32","difficulty":3,"kind":"mc","stem":"협력하며 토의하는 방법에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"세 가지 말고도 토의에 도움이 되는 말과 행동은 모두 협력이다","correct":true},{"t":"협력하는 방법은 정해진 세 가지뿐이다","mis":"K5-1-u5-X32"},{"t":"협력은 사회자만 하는 일이다","mis":"K5-1-u5-X32"},{"t":"협력하려면 반대를 하지 않아야 한다","mis":"K5-1-u5-X31"}],"explanation":["세 가지가 전부가 아니에요.","모두가 할 수 있어요.","반대도 이유가 있으면 협력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#6','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C29',3,'mc','auto','모둠 토의에서 한 친구가 아직 한 번도 말하지 않았을 때 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u5-X29','K5-1-u5-X31']::text[],false,'{"seq":6,"concept":"K5-1-u5-C29","difficulty":3,"kind":"mc","stem":"모둠 토의에서 한 친구가 아직 한 번도 말하지 않았을 때 알맞은 말은 어느 것인가요?","options":[{"t":"「아직 말하지 않은 친구 의견도 들어 봐요.」","correct":true},{"t":"「말하기 싫은가 보니 그냥 두자.」","mis":"K5-1-u5-X29"},{"t":"「시간이 없으니 우리끼리 정해요.」","mis":"K5-1-u5-X29"},{"t":"「말을 안 하니 그 친구는 반대인 거지?」","mis":"K5-1-u5-X31"}],"explanation":["그냥 두면 빠지는 사람이 생겨요.","모두가 말할 기회를 가져야 해요.","차례를 넘겨 주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#7','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C27',3,'mc','auto','의견을 나누고 검토하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X27','K5-1-u5-X42']::text[],false,'{"seq":7,"concept":"K5-1-u5-C27","difficulty":3,"kind":"mc","stem":"의견을 나누고 검토하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로의 생각을 구체적으로 나누고 더 정교하게 다듬을 수 있다","correct":true},{"t":"따지다 보면 다투게 되어 토의가 빨리 끝난다","mis":"K5-1-u5-X27"},{"t":"이유를 말하지 않아도 되어 편하다","mis":"K5-1-u5-X27"},{"t":"한 사람의 의견만 남게 된다","mis":"K5-1-u5-X42"}],"explanation":["따지는 것은 다툼이 아니에요.","이유가 있어야 해요.","다듬어진 의견이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#8','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C26',4,'essay','teacher','토의 장면 ②에서 문제가 된 말을 두 개 골라 쓰고, 각각을 협력하는 말로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C26","difficulty":4,"kind":"essay","stem":"토의 장면 ②에서 문제가 된 말을 두 개 골라 쓰고, 각각을 협력하는 말로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 태이의 「그건 별로인 것 같아요. 특별한 이유는 없어요.」는 「스티커가 떨어지면 다시 뒤섞일까 봐 걱정돼요. 다른 방법도 함께 생각해 볼까요?」로 바꾼다. 서진이의 「네 말은 도움이 하나도 안 돼.」는 「새 책 이야기는 주제와 조금 멀어요. 정리하는 방법을 먼저 이야기해 볼까요?」로 바꾼다.","scoring_points":["문제가 된 말을 두 개 골랐는가","이유를 붙이거나 의견을 다루는 말로 바꾸었는가","사람을 탓하지 않게 바꾸었는가"]},"explanation":["어떤 말이 문제였나요?","이유를 붙여요.","사람 말고 의견을 다뤄요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"책마다 색 스티커를 붙여 갈래를 나누면 좋겠어요. 색만 맞춰 꽂으면 되니까요."},{"who":"태이","text":"그건 별로인 것 같아요."},{"who":"하윤","text":"왜 그렇게 생각하나요?"},{"who":"태이","text":"특별한 이유는 없어요. 그리고 저는 도서관에 새 책이 많이 들어왔으면 좋겠어요."},{"who":"서진","text":"(짜증스럽게) 그게 지금 주제랑 무슨 상관이야. 네 말은 도움이 하나도 안 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#9','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C30',4,'essay','teacher','협력하며 토의하는 세 방법을 쓰고, 각 방법이 필요한 까닭을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C30","difficulty":4,"kind":"essay","stem":"협력하며 토의하는 세 방법을 쓰고, 각 방법이 필요한 까닭을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 의견을 나누고 검토하기는 생각을 정교하게 다듬기 위해 필요하다. 존중하는 태도로 토의하기는 누구나 마음 놓고 말해 더 많은 생각이 나오게 한다. 협력하며 토의 진행하기는 시간 안에 결론에 이르고 빠지는 사람이 없게 한다.","scoring_points":["세 방법을 모두 썼는가","각 방법이 필요한 까닭을 썼는가","셋이 함께 있어야 함을 드러냈는가"]},"explanation":["세 방법은 무엇인가요?","각각 무엇을 돕나요?","셋이 함께 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L07_challenge#10','kor',5,1,'u5','L07','g5_1_kor_u5_L07_challenge','lesson_challenge','K5-1-u5-C32',4,'essay','teacher','사회자가 아닌 친구도 토의를 이끌 수 있는 방법을 두 가지 쓰고, 그것이 왜 협력인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C32","difficulty":4,"kind":"essay","stem":"사회자가 아닌 친구도 토의를 이끌 수 있는 방법을 두 가지 쓰고, 그것이 왜 협력인지 쓰세요.","answer_guide":{"answer":"예: 이야기가 주제에서 멀어지면 「지금 주제와 이어서 말해 볼까요?」 하고 부드럽게 되돌릴 수 있다. 조용한 친구에게 「네 생각은 어때?」 하고 차례를 넘길 수도 있다. 이런 말은 모두의 생각을 모아 더 나은 답을 만드는 데 도움이 되므로 협력이다.","scoring_points":["사회자가 아닌 사람이 할 수 있는 방법을 두 가지 썼는가","그 방법을 말이나 행동으로 구체적으로 썼는가","협력인 까닭을 썼는가"]},"explanation":["주제로 되돌리기를 떠올려요.","차례 넘기기도 있어요.","왜 협력일까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#1','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C33',1,'mc','auto','토의 주제를 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X33','K5-1-u5-X40','K5-1-u5-X37']::text[],false,'{"seq":1,"concept":"K5-1-u5-C33","difficulty":1,"kind":"mc","stem":"토의 주제를 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"광고나 기사 같은 자료를 살펴보다가 함께 이야기할 거리를 찾는다","correct":true},{"t":"자료 없이 갑자기 떠오를 때까지 기다린다","mis":"K5-1-u5-X33"},{"t":"목소리가 가장 큰 친구가 혼자 정한다","mis":"K5-1-u5-X40"},{"t":"답이 하나로 정해진 질문을 고른다","mis":"K5-1-u5-X37"}],"explanation":["주제는 갑자기 떠오르지 않아요.","여럿이 함께 정해요.","자료 속에서 이야깃거리가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#2','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C34',1,'mc','auto','이 공익 광고가 전하려는 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X34']::text[],false,'{"seq":2,"concept":"K5-1-u5-C34","difficulty":1,"kind":"mc","stem":"이 공익 광고가 전하려는 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"작은 힘도 함께 모이면 누군가에게 그늘이 된다","correct":true},{"t":"나무를 많이 심어야 한다","mis":"K5-1-u5-X34"},{"t":"손을 자주 씻어야 한다","mis":"K5-1-u5-X34"},{"t":"혼자 하는 일이 가장 빠르다","mis":"K5-1-u5-X34"}],"explanation":["나무는 겉모습이에요.","손 씻기 이야기가 아니에요.","손 여럿이 모여 나무가 되었어요."],"asset":{"type":"passage","lines":["화면 — 빈 손바닥 여럿이 모여 한 그루 나무 모양을 이룬다.","적힌 글 — 혼자서는 그늘이 되지 못합니다."],"title":"공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#3','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C35',1,'mc','auto','기사에서 책 상자가 세 곳으로 늘어난 까닭은 무엇인가요?',ARRAY['K5-1-u5-X35']::text[],false,'{"seq":3,"concept":"K5-1-u5-C35","difficulty":1,"kind":"mc","stem":"기사에서 책 상자가 세 곳으로 늘어난 까닭은 무엇인가요?","options":[{"t":"마을 사람들이 책을 두고 가고 함께 돌보게 되어서","correct":true},{"t":"마을에서 돈을 많이 들여서","mis":"K5-1-u5-X35"},{"t":"신문에 먼저 났기 때문에","mis":"K5-1-u5-X35"},{"t":"학생이 상자를 한꺼번에 사 와서","mis":"K5-1-u5-X35"}],"explanation":["돈 이야기는 없어요.","신문 이야기도 없어요.","처음과 지금을 견주어 보아요."],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#4','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C36',1,'mc','auto','기사를 읽고 만든 질문 가운데 생각을 묻는 질문은 어느 것인가요?',ARRAY['K5-1-u5-X36']::text[],false,'{"seq":4,"concept":"K5-1-u5-C36","difficulty":1,"kind":"mc","stem":"기사를 읽고 만든 질문 가운데 생각을 묻는 질문은 어느 것인가요?","options":[{"t":"나눔을 실천하면 무엇이 좋을까?","correct":true},{"t":"상자는 지금 몇 곳인가?","mis":"K5-1-u5-X36"},{"t":"기사가 실린 신문 이름은 무엇인가?","mis":"K5-1-u5-X36"},{"t":"처음 상자는 무엇 옆에 놓였나?","mis":"K5-1-u5-X36"}],"explanation":["기사에 답이 적혀 있어요.","답이 하나로 정해져요.","사람마다 다른 생각이 나와요."],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#5','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C37',2,'mc','auto','토의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X37','K5-1-u5-X22']::text[],false,'{"seq":5,"concept":"K5-1-u5-C37","difficulty":2,"kind":"mc","stem":"토의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 학교에서 나눔을 실천할 방법은 무엇일까?","correct":true},{"t":"우리 학교 학생 수는 몇 명일까?","mis":"K5-1-u5-X37"},{"t":"어떤 간식이 가장 맛있을까?","mis":"K5-1-u5-X37"},{"t":"어제 우리 마을에 비가 왔을까?","mis":"K5-1-u5-X22"}],"explanation":["답이 하나예요.","취향만 묻고 있어요.","여럿이 방법을 모아야 하는 주제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#6','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C38',2,'mc','auto','은채가 마련한 의견의 이유로 타당한 것은 어느 것인가요?',ARRAY['K5-1-u5-X38']::text[],false,'{"seq":6,"concept":"K5-1-u5-C38","difficulty":2,"kind":"mc","stem":"은채가 마련한 의견의 이유로 타당한 것은 어느 것인가요?","options":[{"t":"집에서 안 읽는 책을 다시 읽히게 할 수 있다","correct":true},{"t":"내가 하고 싶으니까","mis":"K5-1-u5-X38"},{"t":"다른 의견은 재미가 없어서","mis":"K5-1-u5-X38"},{"t":"그냥 좋아 보여서","mis":"K5-1-u5-X38"}],"explanation":["하고 싶은 마음은 이유가 아니에요.","다른 의견에 대한 느낌이에요.","그렇게 하면 왜 좋은지 말해요."],"asset":{"type":"passage","lines":["의견 — 학년마다 한 달에 한 번 책 나눔 상자를 운영하자.","이유 — 다 읽은 책은 집에서 잠자고 있고, 학년별로 하면 읽는 수준이 맞아 실제로 읽힌다."],"title":"은채가 마련한 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#7','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C39',2,'ox','auto','자료를 찾아 의견을 뒷받침했다면 출처는 적지 않아도 돼요.',ARRAY['K5-1-u5-X39']::text[],false,'{"seq":7,"concept":"K5-1-u5-C39","difficulty":2,"kind":"ox","stem":"자료를 찾아 의견을 뒷받침했다면 출처는 적지 않아도 돼요.","answer":"X","reason_options":[{"t":"어디에서 온 근거인지 밝혀야 설득력이 생기기 때문에","correct":true},{"t":"자료만 있으면 누구나 믿어 주기 때문에","mis":"K5-1-u5-X39"}],"mis":"K5-1-u5-X39","explanation":["출처도 근거의 일부예요.","어디서 왔는지 밝혀요.","출처가 있어야 설득력이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#8','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C34',2,'mc','auto','광고에서 손 하나가 아니라 손 여럿을 담은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X34','K5-1-u5-X09']::text[],false,'{"seq":8,"concept":"K5-1-u5-C34","difficulty":2,"kind":"mc","stem":"광고에서 손 하나가 아니라 손 여럿을 담은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"함께 모여야 큰 힘이 된다는 뜻을 보여 주려고","correct":true},{"t":"손 그림이 그리기 쉬워서","mis":"K5-1-u5-X34"},{"t":"손을 깨끗이 하자는 뜻을 전하려고","mis":"K5-1-u5-X34"},{"t":"나무의 이름을 알리려고","mis":"K5-1-u5-X09"}],"explanation":["그리기 쉬운지는 관계없어요.","손 씻기 광고가 아니에요.","손 하나와 손 여럿의 차이를 보아요."],"asset":{"type":"passage","lines":["화면 — 빈 손바닥 여럿이 모여 한 그루 나무 모양을 이룬다.","적힌 글 — 혼자서는 그늘이 되지 못합니다."],"title":"공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#9','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C35',2,'mc','auto','기사의 처음과 지금을 바르게 견준 것은 어느 것인가요?',ARRAY['K5-1-u5-X35']::text[],false,'{"seq":9,"concept":"K5-1-u5-C35","difficulty":2,"kind":"mc","stem":"기사의 처음과 지금을 바르게 견준 것은 어느 것인가요?","options":[{"t":"처음에는 책이 줄기만 했지만 지금은 마을 사람들이 돌아가며 상자를 살핀다","correct":true},{"t":"처음부터 상자가 세 곳이었다","mis":"K5-1-u5-X35"},{"t":"지금은 아무도 상자를 살피지 않는다","mis":"K5-1-u5-X35"},{"t":"처음에는 마을에서 돈을 모아 책을 샀다","mis":"K5-1-u5-X35"}],"explanation":["상자는 나중에 늘었어요.","지금은 함께 살펴요.","기사에 나온 내용만으로 견주어요."],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_basic#10','kor',5,1,'u5','L09','g5_1_kor_u5_L09_basic','lesson_basic','K5-1-u5-C37',3,'mc','auto','토의 주제의 조건으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X37','K5-1-u5-X47']::text[],false,'{"seq":10,"concept":"K5-1-u5-C37","difficulty":3,"kind":"mc","stem":"토의 주제의 조건으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"답이 하나로 정해져 누구나 같은 말을 하는 주제","correct":true},{"t":"여러 사람이 함께 생각을 모아야 하는 주제","mis":"K5-1-u5-X37"},{"t":"우리가 실제로 해 볼 수 있는 주제","mis":"K5-1-u5-X47"},{"t":"내 삶과 관련 있고 흥미를 느낄 수 있는 주제","mis":"K5-1-u5-X37"}],"explanation":["조건에 맞아요.","조건에 맞아요.","여러 의견이 나올 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#1','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C36',2,'mc','auto','기사를 읽고 만든 질문 가운데 답이 기사에 그대로 적혀 있는 것은 어느 것인가요?',ARRAY['K5-1-u5-X36']::text[],false,'{"seq":1,"concept":"K5-1-u5-C36","difficulty":2,"kind":"mc","stem":"기사를 읽고 만든 질문 가운데 답이 기사에 그대로 적혀 있는 것은 어느 것인가요?","options":[{"t":"처음 상자를 놓은 학생은 무엇이라고 말했나?","correct":true},{"t":"이 학생은 어떤 마음으로 상자를 놓았을까?","mis":"K5-1-u5-X36"},{"t":"우리 학교에서 할 수 있는 나눔은 무엇일까?","mis":"K5-1-u5-X36"},{"t":"나눔이 오래 이어지려면 무엇이 필요할까?","mis":"K5-1-u5-X36"}],"explanation":["사람마다 짐작이 달라요.","우리 학교 이야기는 기사에 없어요.","마지막 줄에 그대로 있어요."],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#2','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C33',2,'ox','auto','토의 주제는 자료를 살펴보지 않고 갑자기 떠올려야 좋은 주제예요.',ARRAY['K5-1-u5-X33']::text[],false,'{"seq":2,"concept":"K5-1-u5-C33","difficulty":2,"kind":"ox","stem":"토의 주제는 자료를 살펴보지 않고 갑자기 떠올려야 좋은 주제예요.","answer":"X","reason_options":[{"t":"자료를 살피다 보면 함께 이야기할 거리가 드러나기 때문에","correct":true},{"t":"자료를 보면 생각이 좁아지기 때문에","mis":"K5-1-u5-X33"}],"mis":"K5-1-u5-X33","explanation":["주제는 저절로 떠오르지 않아요.","광고와 기사를 떠올려요.","자료에서 이야깃거리를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#3','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C37',3,'mc','auto','기사를 읽고 우리 반에서 토의할 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X47','K5-1-u5-X37']::text[],false,'{"seq":3,"concept":"K5-1-u5-C37","difficulty":3,"kind":"mc","stem":"기사를 읽고 우리 반에서 토의할 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반에서 다 읽은 책을 함께 나누는 방법","correct":true},{"t":"기사 속 마을의 상자는 몇 개일까","mis":"K5-1-u5-X22"},{"t":"세상의 모든 사람이 책을 읽게 하는 방법","mis":"K5-1-u5-X47"},{"t":"가장 재미있는 책은 무엇일까","mis":"K5-1-u5-X37"}],"explanation":["답이 기사에 있어요.","우리가 해 볼 수 없는 크기예요.","우리 삶과 이어지고 해 볼 수 있어요."],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#4','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C38',3,'mc','auto','「책 나눔 상자를 교실 문 옆에 두자.」는 의견의 이유로 가장 타당한 것은 어느 것인가요?',ARRAY['K5-1-u5-X38','K5-1-u5-X43']::text[],false,'{"seq":4,"concept":"K5-1-u5-C38","difficulty":3,"kind":"mc","stem":"「책 나눔 상자를 교실 문 옆에 두자.」는 의견의 이유로 가장 타당한 것은 어느 것인가요?","options":[{"t":"드나들 때마다 눈에 띄어 책을 넣고 꺼내기 쉽다","correct":true},{"t":"내가 문 옆을 좋아해서","mis":"K5-1-u5-X38"},{"t":"다른 곳에 두자는 의견은 재미없어서","mis":"K5-1-u5-X38"},{"t":"누가 먼저 말했는지 기억나지 않아서","mis":"K5-1-u5-X43"}],"explanation":["좋아하는 마음은 이유가 아니에요.","다른 의견에 대한 느낌이에요.","그렇게 하면 왜 좋은지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#5','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C39',3,'error','auto','의견을 마련하며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u5-X39','K5-1-u5-X38']::text[],false,'{"seq":5,"concept":"K5-1-u5-C39","difficulty":3,"kind":"error","stem":"의견을 마련하며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「찾은 자료는 어디서 봤는지 몰라도 그냥 쓰면 돼.」","correct":true,"mis_target":"K5-1-u5-X39"},{"t":"「의견에는 이유를 꼭 붙여야 해.」","mis":"K5-1-u5-X38"},{"t":"「이유를 뒷받침할 자료를 찾아 두자.」","mis":"K5-1-u5-X39"}],"explanation":["이유는 꼭 붙여요.","자료도 준비해요.","출처를 밝혀야 설득력이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#6','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C34',3,'mc','auto','광고의 「혼자서는 그늘이 되지 못합니다」와 기사가 이어지는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X34','K5-1-u5-X35']::text[],false,'{"seq":6,"concept":"K5-1-u5-C34","difficulty":3,"kind":"mc","stem":"광고의 「혼자서는 그늘이 되지 못합니다」와 기사가 이어지는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 시작한 나눔도 여럿이 함께해야 커진다는 점","correct":true},{"t":"나무를 심어야 그늘이 생긴다는 점","mis":"K5-1-u5-X34"},{"t":"책은 혼자 조용히 읽어야 한다는 점","mis":"K5-1-u5-X35"},{"t":"신문에 나야 나눔이 커진다는 점","mis":"K5-1-u5-X35"}],"explanation":["글자 그대로의 나무가 아니에요.","기사 내용과 달라요.","한 학생의 상자가 마을 모두의 상자가 되었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#7','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C33',3,'mc','auto','광고와 기사를 함께 읽고 토의 주제를 정하면 좋은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X04','K5-1-u5-X33','K5-1-u5-X36']::text[],false,'{"seq":7,"concept":"K5-1-u5-C33","difficulty":3,"kind":"mc","stem":"광고와 기사를 함께 읽고 토의 주제를 정하면 좋은 까닭은 무엇인가요?","options":[{"t":"두 자료에 담긴 「함께 나누는 힘」에서 우리가 이야기할 거리를 찾을 수 있어서","correct":true},{"t":"자료를 많이 읽을수록 토의에서 이길 수 있어서","mis":"K5-1-u5-X04"},{"t":"두 자료의 글자 수를 견줄 수 있어서","mis":"K5-1-u5-X33"},{"t":"자료에 적힌 답을 그대로 외울 수 있어서","mis":"K5-1-u5-X36"}],"explanation":["이기려고 읽지 않아요.","글자 수는 관계없어요.","두 자료에 공통으로 담긴 생각을 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#8','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C36',4,'essay','teacher','기사를 읽고 생각을 묻는 질문 두 개를 만들고, 그 질문이 왜 토의할 거리가 되는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C36","difficulty":4,"kind":"essay","stem":"기사를 읽고 생각을 묻는 질문 두 개를 만들고, 그 질문이 왜 토의할 거리가 되는지 쓰세요.","answer_guide":{"answer":"예: 「나눔이 오래 이어지려면 무엇이 필요할까?」, 「우리 학교에서 할 수 있는 나눔은 무엇일까?」 두 질문은 답이 기사에 그대로 적혀 있지 않아 사람마다 다른 생각을 말할 수 있으므로 토의할 거리가 된다.","scoring_points":["생각을 묻는 질문을 두 개 만들었는가","답이 기사에 그대로 있지 않은 질문인가","토의할 거리가 되는 까닭을 썼는가"]},"explanation":["답이 하나로 정해지나요?","우리 생활과 이어 보아요.","여러 생각이 나올 수 있나요?"],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#9','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C37',4,'essay','teacher','나눔과 관련해 우리 반에서 토의할 주제를 하나 정하고, 그 주제가 토의 주제의 조건에 맞는 까닭을 세 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C37","difficulty":4,"kind":"essay","stem":"나눔과 관련해 우리 반에서 토의할 주제를 하나 정하고, 그 주제가 토의 주제의 조건에 맞는 까닭을 세 가지 쓰세요.","answer_guide":{"answer":"예: 주제 — 우리 반에서 다 읽은 책을 서로 나누는 방법. 첫째, 혼자 답할 수 없고 여럿이 방법을 모아야 한다. 둘째, 우리 반에서 실제로 해 볼 수 있는 크기이다. 셋째, 상자를 두자 · 바꿔 읽는 날을 정하자처럼 여러 의견이 나올 수 있고 우리 생활과 관련 있다.","scoring_points":["토의 주제를 하나 정했는가","조건에 맞는 까닭을 세 가지 썼는가","답이 하나로 정해지지 않는 주제인가"]},"explanation":["여럿이 모아야 하나요?","해 볼 수 있는 크기인가요?","여러 의견이 나올까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L09_challenge#10','kor',5,1,'u5','L09','g5_1_kor_u5_L09_challenge','lesson_challenge','K5-1-u5-C39',4,'essay','teacher','나눔과 관련한 의견을 하나 정해, 그 의견의 타당한 이유 두 가지와 이유를 뒷받침할 자료, 그 자료의 출처를 어떻게 적을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C39","difficulty":4,"kind":"essay","stem":"나눔과 관련한 의견을 하나 정해, 그 의견의 타당한 이유 두 가지와 이유를 뒷받침할 자료, 그 자료의 출처를 어떻게 적을지 쓰세요.","answer_guide":{"answer":"예: 의견 — 한 달에 한 번 반끼리 책을 바꿔 읽는 날을 만들자. 이유 — 같은 책을 여럿이 읽어 책을 아낄 수 있고, 다른 반 친구가 고른 책을 만나 읽을거리가 넓어진다. 자료 — 우리 학교 도서관에서 빌려 가는 책 수를 알아본 안내문. 출처 — 자료를 낸 곳과 찾은 날을 함께 적는다.","scoring_points":["의견을 하나 정했는가","왜 좋은지 설명하는 이유를 두 가지 썼는가","자료와 출처를 적을 방법을 썼는가"]},"explanation":["그렇게 하면 왜 좋나요?","이유를 뒷받침할 자료는?","어디서 온 자료인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#1','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C40',1,'mc','auto','다시 한 토의에서 태이는 걱정되는 점을 어떻게 말했나요?',ARRAY['K5-1-u5-X26','K5-1-u5-X31','K5-1-u5-X41']::text[],false,'{"seq":1,"concept":"K5-1-u5-C40","difficulty":1,"kind":"mc","stem":"다시 한 토의에서 태이는 걱정되는 점을 어떻게 말했나요?","options":[{"t":"사람이 아니라 의견에 대해 말했다","correct":true},{"t":"은채를 깎아내리며 말했다","mis":"K5-1-u5-X26"},{"t":"이유 없이 반대했다","mis":"K5-1-u5-X31"},{"t":"말하지 않고 그냥 넘어갔다","mis":"K5-1-u5-X41"}],"explanation":["사람을 탓하지 않았어요.","관리 걱정이라는 이유가 있어요.","의견에 대해 걱정을 말했어요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"학년마다 책 나눔 상자를 두면 좋겠어요. 집에서 안 읽는 책이 다시 읽힐 수 있으니까요."},{"who":"태이","text":"저는 상자가 금세 비거나 넘칠까 봐 걱정돼요. 관리하는 사람을 정해야 하지 않을까요?"},{"who":"하윤","text":"좋은 지적이에요. 관리 문제를 함께 생각해 봅시다."},{"who":"서진","text":"그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"태이","text":"그 방법이면 저도 찬성이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#2','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C41',1,'mc','auto','토의에서 의견의 단점을 찾는 까닭은 무엇인가요?',ARRAY['K5-1-u5-X41','K5-1-u5-X42']::text[],false,'{"seq":2,"concept":"K5-1-u5-C41","difficulty":1,"kind":"mc","stem":"토의에서 의견의 단점을 찾는 까닭은 무엇인가요?","options":[{"t":"미리 알고 보완하기 위해서","correct":true},{"t":"친구의 의견을 깎아내리려고","mis":"K5-1-u5-X41"},{"t":"토의를 빨리 끝내려고","mis":"K5-1-u5-X41"},{"t":"내 의견만 남기려고","mis":"K5-1-u5-X42"}],"explanation":["깎아내리는 일이 아니에요.","빨리 끝내는 것이 목적이 아니에요.","미리 알면 보완할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#3','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C43',1,'mc','auto','모둠 의견을 결정할 때 따질 기준이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u5-X43','K5-1-u5-X23']::text[],false,'{"seq":3,"concept":"K5-1-u5-C43","difficulty":1,"kind":"mc","stem":"모둠 의견을 결정할 때 따질 기준이 아닌 것은 어느 것인가요?","options":[{"t":"누가 낸 의견인가","correct":true},{"t":"누구나 실천할 수 있는가","mis":"K5-1-u5-X43"},{"t":"꾸준히 이어 갈 수 있는가","mis":"K5-1-u5-X43"},{"t":"새로운 문제가 생기지 않는가","mis":"K5-1-u5-X23"}],"explanation":["기준이에요.","기준이에요.","누가 냈는지는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#4','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C44',1,'mc','auto','다른 모둠의 의견을 들을 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-1-u5-X44','K5-1-u5-X26']::text[],false,'{"seq":4,"concept":"K5-1-u5-C44","difficulty":1,"kind":"mc","stem":"다른 모둠의 의견을 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"우리 의견에 보탤 점이 없는지 살피며 듣는다","correct":true},{"t":"우리 의견이 더 나은 까닭을 찾으며 듣는다","mis":"K5-1-u5-X44"},{"t":"이미 정했으니 듣지 않는다","mis":"K5-1-u5-X44"},{"t":"발표한 친구의 말투만 살핀다","mis":"K5-1-u5-X26"}],"explanation":["이기려고 듣지 않아요.","들어야 놓친 것을 찾아요.","보탤 실마리를 찾으며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#5','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C41',2,'match','auto','의견과 그 의견의 단점을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u5-C41","difficulty":2,"kind":"match","stem":"의견과 그 의견의 단점을 알맞게 이으세요.","pairs":[{"l":"학년마다 나눔 상자를 둔다","r":"관리할 사람을 새로 정해야 한다"},{"l":"도서 도우미가 상자를 관리한다","r":"도우미가 맡는 일이 늘어난다"},{"l":"누구나 아무 때나 책을 넣게 한다","r":"읽기 어려운 책까지 섞일 수 있다"}],"mis":"K5-1-u5-X41","explanation":["상자를 누가 돌볼까요?","도우미에게 무엇이 늘까요?","아무 책이나 들어오면?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#6','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C42',2,'mc','auto','여러 의견을 합친 좋은 모둠 의견은 어느 것인가요?',ARRAY['K5-1-u5-X42','K5-1-u5-X41']::text[],false,'{"seq":6,"concept":"K5-1-u5-C42","difficulty":2,"kind":"mc","stem":"여러 의견을 합친 좋은 모둠 의견은 어느 것인가요?","options":[{"t":"학년마다 상자를 두되 도서 도우미가 한 주에 한 번 살핀다","correct":true},{"t":"가장 먼저 나온 의견으로 그냥 정한다","mis":"K5-1-u5-X42"},{"t":"걱정되는 점은 말하지 않고 넘어간다","mis":"K5-1-u5-X41"},{"t":"손을 많이 든 의견 하나만 남긴다","mis":"K5-1-u5-X42"}],"explanation":["먼저 나왔다고 좋은 게 아니에요.","걱정을 다뤄야 해요.","좋은 점을 합쳐 단점을 줄였어요."],"asset":{"type":"passage","lines":["학년마다 나눔 상자 — 장점: 읽는 수준이 맞는다 / 단점: 관리할 사람이 필요하다","도서 도우미가 관리 — 장점: 새 역할을 만들지 않아도 된다 / 단점: 도우미의 일이 늘어난다"],"title":"의견의 장점과 단점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#7','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C42',2,'ox','auto','토의에서도 투표처럼 의견 하나만 골라야 해요.',ARRAY['K5-1-u5-X42']::text[],false,'{"seq":7,"concept":"K5-1-u5-C42","difficulty":2,"kind":"ox","stem":"토의에서도 투표처럼 의견 하나만 골라야 해요.","answer":"X","reason_options":[{"t":"서로의 좋은 점을 합쳐 더 나은 의견을 만들 수 있기 때문에","correct":true},{"t":"의견을 합치면 아무도 찬성하지 않기 때문에","mis":"K5-1-u5-X42"}],"mis":"K5-1-u5-X42","explanation":["하나만 고르는 것이 답은 아니에요.","합칠 수 있는지 먼저 봐요.","이것이 토의가 투표와 다른 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#8','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C45',2,'mc','auto','토의를 되돌아보며 찾은 아쉬운 점은 어떻게 하는 것이 알맞나요?',ARRAY['K5-1-u5-X45','K5-1-u5-X26']::text[],false,'{"seq":8,"concept":"K5-1-u5-C45","difficulty":2,"kind":"mc","stem":"토의를 되돌아보며 찾은 아쉬운 점은 어떻게 하는 것이 알맞나요?","options":[{"t":"한 가지만 정해 다음 토의에서 고친다","correct":true},{"t":"아쉬운 점을 모두 한 번에 고친다","mis":"K5-1-u5-X45"},{"t":"적어만 두고 다시 보지 않는다","mis":"K5-1-u5-X45"},{"t":"아쉬운 점을 말한 친구를 탓한다","mis":"K5-1-u5-X26"}],"explanation":["한 번에 다 바꾸면 아무것도 안 바뀌어요.","다음 토의 전에 다시 꺼내요.","하나씩 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#9','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C40',2,'mc','auto','하윤이의 「좋은 지적이에요. 관리 문제를 함께 생각해 봅시다.」는 어떤 협력인가요?',ARRAY['K5-1-u5-X40','K5-1-u5-X25','K5-1-u5-X28']::text[],false,'{"seq":9,"concept":"K5-1-u5-C40","difficulty":2,"kind":"mc","stem":"하윤이의 「좋은 지적이에요. 관리 문제를 함께 생각해 봅시다.」는 어떤 협력인가요?","options":[{"t":"사회자가 논의할 부분을 짚어 주었다","correct":true},{"t":"가장 목소리가 큰 사람의 의견으로 정했다","mis":"K5-1-u5-X40"},{"t":"주제와 관련 없는 의견을 냈다","mis":"K5-1-u5-X25"},{"t":"태이의 말을 끊었다","mis":"K5-1-u5-X28"}],"explanation":["누구 의견으로 정하지 않았어요.","주제 안의 말이에요.","함께 다룰 부분을 짚었어요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"학년마다 책 나눔 상자를 두면 좋겠어요. 집에서 안 읽는 책이 다시 읽힐 수 있으니까요."},{"who":"태이","text":"저는 상자가 금세 비거나 넘칠까 봐 걱정돼요. 관리하는 사람을 정해야 하지 않을까요?"},{"who":"하윤","text":"좋은 지적이에요. 관리 문제를 함께 생각해 봅시다."},{"who":"서진","text":"그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"태이","text":"그 방법이면 저도 찬성이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_basic#10','kor',5,1,'u5','L11','g5_1_kor_u5_L11_basic','lesson_basic','K5-1-u5-C43',3,'mc','auto','「책을 넣지 않은 사람의 이름을 방송으로 알린다」는 의견이 어긋나는 기준은 어느 것인가요?',ARRAY['K5-1-u5-X43','K5-1-u5-X18','K5-1-u5-X42']::text[],false,'{"seq":10,"concept":"K5-1-u5-C43","difficulty":3,"kind":"mc","stem":"「책을 넣지 않은 사람의 이름을 방송으로 알린다」는 의견이 어긋나는 기준은 어느 것인가요?","options":[{"t":"실천하는 과정에서 새 문제가 생기지 않는가","correct":true},{"t":"누가 낸 의견인가","mis":"K5-1-u5-X43"},{"t":"글씨를 바르게 썼는가","mis":"K5-1-u5-X18"},{"t":"가장 먼저 나온 의견인가","mis":"K5-1-u5-X42"}],"explanation":["기준이 아니에요.","기준이 아니에요.","창피를 주면 새 문제가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#1','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C44',2,'mc','auto','「다른 모둠의 의견을 들을 때에도 토의는 이어진다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X05','K5-1-u5-X03','K5-1-u5-X44']::text[],false,'{"seq":1,"concept":"K5-1-u5-C44","difficulty":2,"kind":"mc","stem":"「다른 모둠의 의견을 들을 때에도 토의는 이어진다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 모둠이 놓친 부분이 그쪽에서 보일 수 있다는 뜻","correct":true},{"t":"다른 모둠과 다시 다투어야 한다는 뜻","mis":"K5-1-u5-X05"},{"t":"다른 모둠의 의견을 그대로 따라야 한다는 뜻","mis":"K5-1-u5-X03"},{"t":"우리 의견은 절대 바꾸면 안 된다는 뜻","mis":"K5-1-u5-X44"}],"explanation":["다툼이 아니에요.","견주어 판단해요.","놓친 것을 찾는 기회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#2','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C41',2,'ox','auto','의견의 단점을 말하는 것은 친구를 깎아내리는 일이에요.',ARRAY['K5-1-u5-X41']::text[],false,'{"seq":2,"concept":"K5-1-u5-C41","difficulty":2,"kind":"ox","stem":"의견의 단점을 말하는 것은 친구를 깎아내리는 일이에요.","answer":"X","reason_options":[{"t":"단점을 미리 알면 보완할 수 있기 때문에","correct":true},{"t":"단점은 말하지 않는 것이 예의이기 때문에","mis":"K5-1-u5-X41"}],"mis":"K5-1-u5-X41","explanation":["단점은 보완의 실마리예요.","사람이 아니라 의견을 다뤄요.","미리 알면 고칠 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#3','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C40',3,'mc','auto','서진이의 「그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요?」에 드러난 협력은 어느 것인가요?',ARRAY['K5-1-u5-X25','K5-1-u5-X31','K5-1-u5-X26']::text[],false,'{"seq":3,"concept":"K5-1-u5-C40","difficulty":3,"kind":"mc","stem":"서진이의 「그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요?」에 드러난 협력은 어느 것인가요?","options":[{"t":"앞의 지적을 받아 다음 의견을 냈다","correct":true},{"t":"자기 생각만 우겼다","mis":"K5-1-u5-X25"},{"t":"이유 없이 반대했다","mis":"K5-1-u5-X31"},{"t":"친구를 깎아내렸다","mis":"K5-1-u5-X26"}],"explanation":["우기지 않았어요.","반대가 아니에요.","태이의 관리 걱정을 이어받았어요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"학년마다 책 나눔 상자를 두면 좋겠어요. 집에서 안 읽는 책이 다시 읽힐 수 있으니까요."},{"who":"태이","text":"저는 상자가 금세 비거나 넘칠까 봐 걱정돼요. 관리하는 사람을 정해야 하지 않을까요?"},{"who":"하윤","text":"좋은 지적이에요. 관리 문제를 함께 생각해 봅시다."},{"who":"서진","text":"그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"태이","text":"그 방법이면 저도 찬성이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#4','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C40',3,'error','auto','다시 한 토의를 보고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u5-X40','K5-1-u5-X26']::text[],false,'{"seq":4,"concept":"K5-1-u5-C40","difficulty":3,"kind":"error","stem":"다시 한 토의를 보고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「태이가 찬성한 건 서진이 목소리가 커서야.」","correct":true,"mis_target":"K5-1-u5-X40"},{"t":"「태이가 걱정을 말할 때 은채를 탓하지 않았어.」","mis":"K5-1-u5-X26"},{"t":"「서진이는 태이의 지적을 이어받아 의견을 냈어.」","mis":"K5-1-u5-X40"}],"explanation":["의견에 대해 말했어요.","앞 말을 이어받았어요.","걱정이 풀려서 찬성했어요."],"asset":{"type":"speech","turns":[{"who":"은채","text":"학년마다 책 나눔 상자를 두면 좋겠어요. 집에서 안 읽는 책이 다시 읽힐 수 있으니까요."},{"who":"태이","text":"저는 상자가 금세 비거나 넘칠까 봐 걱정돼요. 관리하는 사람을 정해야 하지 않을까요?"},{"who":"하윤","text":"좋은 지적이에요. 관리 문제를 함께 생각해 봅시다."},{"who":"서진","text":"그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"태이","text":"그 방법이면 저도 찬성이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#5','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C42',3,'mc','auto','토의가 투표와 다른 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X42','K5-1-u5-X43']::text[],false,'{"seq":5,"concept":"K5-1-u5-C42","difficulty":3,"kind":"mc","stem":"토의가 투표와 다른 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"여러 의견의 좋은 점을 합쳐 더 나은 의견을 만들 수 있다","correct":true},{"t":"손을 가장 많이 든 의견 하나를 고른다","mis":"K5-1-u5-X42"},{"t":"먼저 나온 의견으로 정한다","mis":"K5-1-u5-X42"},{"t":"누가 냈는지에 따라 정한다","mis":"K5-1-u5-X43"}],"explanation":["그건 투표예요.","차례는 기준이 아니에요.","합칠 수 있다는 점이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#6','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C43',3,'mc','auto','학급 문고 정리 방법으로 네 기준에 가장 잘 맞는 의견은 어느 것인가요?',ARRAY['K5-1-u5-X23','K5-1-u5-X43']::text[],false,'{"seq":6,"concept":"K5-1-u5-C43","difficulty":3,"kind":"mc","stem":"학급 문고 정리 방법으로 네 기준에 가장 잘 맞는 의견은 어느 것인가요?","options":[{"t":"책 등에 갈래별 색 띠를 붙이고 도서 도우미가 한 주에 한 번 살핀다","correct":true},{"t":"정리를 못 한 사람에게 벌칙을 준다","mis":"K5-1-u5-X23"},{"t":"학급 문고를 아예 없앤다","mis":"K5-1-u5-X23"},{"t":"반장 혼자 날마다 모든 책을 정리한다","mis":"K5-1-u5-X43"}],"explanation":["새 문제가 생겨요.","문제를 없애는 대신 문고를 없앴어요.","한 사람이 꾸준히 하기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#7','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C45',3,'mc','auto','토의를 점검한 내용을 다음 토의에 이어 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X45']::text[],false,'{"seq":7,"concept":"K5-1-u5-C45","difficulty":3,"kind":"mc","stem":"토의를 점검한 내용을 다음 토의에 이어 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"다음 토의를 시작하기 전에 오늘 정한 한 가지를 다시 꺼내 본다","correct":true},{"t":"점검표는 다 쓰면 버린다","mis":"K5-1-u5-X45"},{"t":"다음 토의에서는 아쉬운 점을 다시 찾지 않는다","mis":"K5-1-u5-X45"},{"t":"잘한 점만 적고 아쉬운 점은 적지 않는다","mis":"K5-1-u5-X45"}],"explanation":["버리면 이어지지 않아요.","점검은 계속해요.","정한 한 가지를 다시 꺼내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#8','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C42',4,'essay','teacher','「의견의 장점과 단점」을 보고 두 의견의 장점과 단점을 정리한 뒤, 두 의견을 합쳐 단점을 줄인 모둠 의견을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C42","difficulty":4,"kind":"essay","stem":"「의견의 장점과 단점」을 보고 두 의견의 장점과 단점을 정리한 뒤, 두 의견을 합쳐 단점을 줄인 모둠 의견을 쓰세요.","answer_guide":{"answer":"예: 학년마다 나눔 상자를 두면 읽는 수준이 맞지만 관리할 사람이 필요하다. 도서 도우미가 관리하면 새 역할을 만들지 않아도 되지만 도우미의 일이 늘어난다. 합친 의견 — 학년마다 상자를 두고, 도서 도우미가 한 주에 한 번만 살피되 넘치거나 빈 것만 알린다.","scoring_points":["두 의견의 장점을 썼는가","두 의견의 단점을 썼는가","좋은 점을 합쳐 단점을 줄인 의견을 썼는가"]},"explanation":["장점은 무엇인가요?","단점은 무엇인가요?","합치면 어떤 단점이 줄까요?"],"asset":{"type":"passage","lines":["학년마다 나눔 상자 — 장점: 읽는 수준이 맞는다 / 단점: 관리할 사람이 필요하다","도서 도우미가 관리 — 장점: 새 역할을 만들지 않아도 된다 / 단점: 도우미의 일이 늘어난다"],"title":"의견의 장점과 단점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#9','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C40',4,'essay','teacher','어긋난 토의와 다시 한 토의를 견주어, 다시 한 토의에서 달라진 점을 세 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C40","difficulty":4,"kind":"essay","stem":"어긋난 토의와 다시 한 토의를 견주어, 다시 한 토의에서 달라진 점을 세 가지 쓰세요.","answer_guide":{"answer":"예: 첫째, 의견에 이유를 함께 말했다. 둘째, 태이가 걱정되는 점을 사람이 아니라 의견에 대해 말했다. 셋째, 서진이가 앞의 지적을 받아 다음 의견을 내고, 하윤이가 논의할 부분을 짚어 주어 결론에 이르렀다.","scoring_points":["달라진 점을 세 가지 썼는가","토의 장면의 말을 근거로 들었는가","협력하는 방법과 이어 썼는가"]},"explanation":["이유가 붙었나요?","걱정은 어떻게 말했나요?","의견이 어떻게 자랐나요?"],"asset":{"type":"speech","turns":[{"who":"은채","text":"학년마다 책 나눔 상자를 두면 좋겠어요. 집에서 안 읽는 책이 다시 읽힐 수 있으니까요."},{"who":"태이","text":"저는 상자가 금세 비거나 넘칠까 봐 걱정돼요. 관리하는 사람을 정해야 하지 않을까요?"},{"who":"하윤","text":"좋은 지적이에요. 관리 문제를 함께 생각해 봅시다."},{"who":"서진","text":"그럼 학급 도서 도우미가 한 주에 한 번 살피면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"태이","text":"그 방법이면 저도 찬성이에요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L11_challenge#10','kor',5,1,'u5','L11','g5_1_kor_u5_L11_challenge','lesson_challenge','K5-1-u5-C45',4,'essay','teacher','모둠 토의를 마쳤다고 생각하고, 잘한 점 한 가지와 아쉬운 점 한 가지를 쓴 뒤 아쉬운 점을 다음 토의에서 어떻게 고칠지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C45","difficulty":4,"kind":"essay","stem":"모둠 토의를 마쳤다고 생각하고, 잘한 점 한 가지와 아쉬운 점 한 가지를 쓴 뒤 아쉬운 점을 다음 토의에서 어떻게 고칠지 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 단점을 짚은 뒤에도 기분 상하지 않게 이어 갔다. 아쉬운 점 — 말수가 적은 친구에게 차례를 넘기지 못했다. 다음 토의를 시작하기 전에 이 점을 다시 꺼내 보고, 의견을 하나씩 다 들은 뒤 아직 말하지 않은 친구에게 「네 생각은 어때?」 하고 묻겠다.","scoring_points":["잘한 점을 썼는가","아쉬운 점을 한 가지만 골랐는가","다음 토의에서 고칠 방법을 구체적으로 썼는가"]},"explanation":["무엇이 잘되었나요?","하나만 골라요.","다음엔 어떻게 할까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#1','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C46',1,'mc','auto','다른 교과와 이어지는 토의 주제로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X37']::text[],false,'{"seq":1,"concept":"K5-1-u5-C46","difficulty":1,"kind":"mc","stem":"다른 교과와 이어지는 토의 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"교실에서 전기를 아끼는 방법","correct":true},{"t":"오늘 날짜는 며칠인가","mis":"K5-1-u5-X22"},{"t":"가장 인기 있는 연예인은 누구인가","mis":"K5-1-u5-X37"},{"t":"어제 저녁 반찬은 무엇이었나","mis":"K5-1-u5-X22"}],"explanation":["답이 하나예요.","취향을 묻고 있어요.","과학에서 배운 것을 생활 문제로 옮겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#2','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C46',1,'match','auto','교과와 어울리는 토의 주제를 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u5-C46","difficulty":1,"kind":"match","stem":"교과와 어울리는 토의 주제를 이으세요.","pairs":[{"l":"과학","r":"교실에서 전기를 아끼는 방법"},{"l":"사회","r":"마을 공공시설을 함께 쓰는 방법"},{"l":"도덕","r":"온라인에서 지켜야 할 말과 태도"}],"mis":"K5-1-u5-X46","explanation":["에너지를 배운 교과예요.","마을과 공공시설을 배운 교과예요.","바른 말과 태도를 배운 교과예요."],"asset":{"type":"passage","lines":["과학 — 교실에서 전기와 물을 아끼는 방법","사회 — 우리 마을 공공시설을 함께 쓰는 방법","도덕 — 온라인에서 서로 지켜야 할 말과 태도","실과 — 급식 남기는 양을 줄이는 방법"],"title":"다른 교과와 이어지는 토의 주제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#3','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C47',1,'mc','auto','잘 다듬어진 토의 주제는 어느 것인가요?',ARRAY['K5-1-u5-X47']::text[],false,'{"seq":3,"concept":"K5-1-u5-C47","difficulty":1,"kind":"mc","stem":"잘 다듬어진 토의 주제는 어느 것인가요?","options":[{"t":"우리 반 급식 남기는 양을 줄이는 방법","correct":true},{"t":"세계의 굶주림을 없애는 방법","mis":"K5-1-u5-X47"},{"t":"좋은 사람이 되는 방법","mis":"K5-1-u5-X47"},{"t":"지구를 깨끗하게 하는 방법","mis":"K5-1-u5-X47"}],"explanation":["우리 힘으로 하기엔 너무 커요.","무엇을 할지 막연해요.","우리가 직접 해 볼 수 있는 크기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#4','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C48',1,'mc','auto','토의를 시작하기 전에 준비할 것이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u5-X48','K5-1-u5-X39']::text[],false,'{"seq":4,"concept":"K5-1-u5-C48","difficulty":1,"kind":"mc","stem":"토의를 시작하기 전에 준비할 것이 아닌 것은 어느 것인가요?","options":[{"t":"다른 친구를 이길 반박거리","correct":true},{"t":"내 의견과 이유","mis":"K5-1-u5-X48"},{"t":"이유를 뒷받침할 자료와 출처","mis":"K5-1-u5-X39"},{"t":"협력하며 토의할 계획","mis":"K5-1-u5-X48"}],"explanation":["준비할 것이에요.","준비할 것이에요.","토의는 이기는 말하기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#5','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C46',2,'ox','auto','토의는 국어 시간에만 하는 활동이에요.',ARRAY['K5-1-u5-X46']::text[],false,'{"seq":5,"concept":"K5-1-u5-C46","difficulty":2,"kind":"ox","stem":"토의는 국어 시간에만 하는 활동이에요.","answer":"X","reason_options":[{"t":"다른 교과에서 배운 것 가운데에도 함께 답을 찾아야 할 문제가 많기 때문에","correct":true},{"t":"다른 시간에는 의견을 말하면 안 되기 때문에","mis":"K5-1-u5-X46"}],"mis":"K5-1-u5-X46","explanation":["사회 · 과학 · 도덕 · 실과도 있어요.","배운 것을 생활 문제로 옮겨요.","토의는 어디서나 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#6','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C47',2,'mc','auto','「환경을 지키는 방법」 같은 넓은 주제가 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X47','K5-1-u5-X32']::text[],false,'{"seq":6,"concept":"K5-1-u5-C47","difficulty":2,"kind":"mc","stem":"「환경을 지키는 방법」 같은 넓은 주제가 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"누구도 실천하지 못하는 결론이 나오기 때문이다","correct":true},{"t":"넓을수록 좋은 토의가 되기 때문이다","mis":"K5-1-u5-X47"},{"t":"글자가 많아 읽기 어렵기 때문이다","mis":"K5-1-u5-X47"},{"t":"사회자가 정하지 않았기 때문이다","mis":"K5-1-u5-X32"}],"explanation":["넓으면 오히려 막연해요.","글자 수와는 관계없어요.","해 볼 수 있는 크기로 좁혀요."],"asset":{"type":"passage","lines":["너무 넓은 주제 — 환경을 지키는 방법","다듬은 주제 — 우리 반에서 종이컵 사용을 줄이는 방법"],"title":"주제 다듬기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#7','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C48',2,'mc','auto','「미리 정해 둔 결론」을 가지고 토의에 나가면 안 되는 까닭은 무엇인가요?',ARRAY['K5-1-u5-X48','K5-1-u5-X32','K5-1-u5-X38']::text[],false,'{"seq":7,"concept":"K5-1-u5-C48","difficulty":2,"kind":"mc","stem":"「미리 정해 둔 결론」을 가지고 토의에 나가면 안 되는 까닭은 무엇인가요?","options":[{"t":"서로의 생각을 모아 더 나은 답을 찾는 토의가 되지 않기 때문이다","correct":true},{"t":"결론을 쓰는 데 시간이 오래 걸리기 때문이다","mis":"K5-1-u5-X48"},{"t":"결론은 사회자만 정할 수 있기 때문이다","mis":"K5-1-u5-X32"},{"t":"결론이 있으면 이유가 필요 없기 때문이다","mis":"K5-1-u5-X38"}],"explanation":["시간 문제가 아니에요.","결론은 함께 정해요.","토의는 함께 답을 찾는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#8','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C49',2,'mc','auto','좋은 토의를 만드는 사람으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X49','K5-1-u5-X32']::text[],false,'{"seq":8,"concept":"K5-1-u5-C49","difficulty":2,"kind":"mc","stem":"좋은 토의를 만드는 사람으로 알맞은 것은 어느 것인가요?","options":[{"t":"참여한 모두가 저마다 몫을 맡아 함께 만든다","correct":true},{"t":"사회자 한 사람의 솜씨로 만든다","mis":"K5-1-u5-X49"},{"t":"말을 가장 잘하는 친구가 만든다","mis":"K5-1-u5-X32"},{"t":"선생님이 정해 준 대로 만든다","mis":"K5-1-u5-X49"}],"explanation":["한 사람의 솜씨가 아니에요.","말솜씨만으로 되지 않아요.","모두에게 몫이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#9','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C46',2,'mc','auto','실천 토의에서 「해결 방안 결정하기」 다음에 할 일은 무엇인가요?',ARRAY['K5-1-u5-X24']::text[],false,'{"seq":9,"concept":"K5-1-u5-C46","difficulty":2,"kind":"mc","stem":"실천 토의에서 「해결 방안 결정하기」 다음에 할 일은 무엇인가요?","options":[{"t":"토의를 되돌아보기","correct":true},{"t":"다른 교과와 이어지는 문제 이야기하기","mis":"K5-1-u5-X24"},{"t":"토의 계획하기","mis":"K5-1-u5-X24"},{"t":"협력하며 토의하기","mis":"K5-1-u5-X24"}],"explanation":["맨 처음 하는 일이에요.","결정보다 앞서요.","결정한 뒤 되돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_basic#10','kor',5,1,'u5','L12','g5_1_kor_u5_L12_basic','lesson_basic','K5-1-u5-C49',3,'mc','auto','토의하는 힘에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X49','K5-1-u5-X32']::text[],false,'{"seq":10,"concept":"K5-1-u5-C49","difficulty":3,"kind":"mc","stem":"토의하는 힘에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"한 번에 길러지지 않고 토의를 거듭할수록 조금씩 자란다","correct":true},{"t":"한 번에 잘하지 못하면 토의에 맞지 않는 사람이다","mis":"K5-1-u5-X49"},{"t":"말을 잘하는 사람만 기를 수 있다","mis":"K5-1-u5-X32"},{"t":"사회자를 해 본 사람만 기를 수 있다","mis":"K5-1-u5-X49"}],"explanation":["처음부터 잘하는 사람은 드물어요.","누구나 기를 수 있어요.","거듭할수록 조금씩 자라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#1','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C47',2,'mc','auto','「건강하게 사는 방법」을 우리가 해 볼 수 있는 크기로 좁힌 것은 어느 것인가요?',ARRAY['K5-1-u5-X47','K5-1-u5-X37','K5-1-u5-X22']::text[],false,'{"seq":1,"concept":"K5-1-u5-C47","difficulty":2,"kind":"mc","stem":"「건강하게 사는 방법」을 우리가 해 볼 수 있는 크기로 좁힌 것은 어느 것인가요?","options":[{"t":"우리 반이 쉬는 시간에 몸을 움직이는 시간을 늘리는 방법","correct":true},{"t":"모든 사람이 건강하게 사는 방법","mis":"K5-1-u5-X47"},{"t":"건강이란 무엇인가","mis":"K5-1-u5-X37"},{"t":"우리 반에서 키가 가장 큰 사람은 누구인가","mis":"K5-1-u5-X22"}],"explanation":["더 넓어졌어요.","뜻을 묻는 질문이에요.","우리 반 · 쉬는 시간으로 좁혔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#2','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C49',2,'ox','auto','토의가 어긋나면 사회자 한 사람의 탓이에요.',ARRAY['K5-1-u5-X49']::text[],false,'{"seq":2,"concept":"K5-1-u5-C49","difficulty":2,"kind":"ox","stem":"토의가 어긋나면 사회자 한 사람의 탓이에요.","answer":"X","reason_options":[{"t":"참여한 모두가 저마다 맡을 몫이 있기 때문에","correct":true},{"t":"사회자만 토의를 이끌 수 있기 때문에","mis":"K5-1-u5-X49"}],"mis":"K5-1-u5-X49","explanation":["사회자만의 일은 없어요.","모두에게 몫이 있어요.","함께 만드는 토의예요."],"asset":{"type":"passage","lines":["토의를 잘 이끄는 일은 흔히 사회자의 몫이라고 여겨집니다.","그러나 좋은 토의는 한 사람의 솜씨로 만들어지지 않습니다.","이유 붙이기, 끊지 않고 듣기, 주제로 되돌리기, 차례 넘기기가 함께 일어나야 합니다.","이 가운데 사회자만 할 수 있는 일은 없습니다. 여럿이 나누어 할 때 더 잘됩니다.","그러므로 토의가 어긋났을 때 사회자 한 사람을 탓하는 것은 알맞지 않습니다.","좋은 토의는 모두가 함께 만드는 것입니다."],"title":"좋은 토의는 누가 만드는가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#3','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C46',3,'mc','auto','실과와 이어진 주제 「급식 남기는 양을 줄이는 방법」으로 방안을 정한 뒤 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X46','K5-1-u5-X05','K5-1-u5-X45']::text[],false,'{"seq":3,"concept":"K5-1-u5-C46","difficulty":3,"kind":"mc","stem":"실과와 이어진 주제 「급식 남기는 양을 줄이는 방법」으로 방안을 정한 뒤 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"정한 방안을 실제로 며칠 동안 해 보고 되돌아본다","correct":true},{"t":"정한 방안은 공책에 적어 두기만 한다","mis":"K5-1-u5-X46"},{"t":"다른 모둠 방안과 누가 이기는지 다툰다","mis":"K5-1-u5-X05"},{"t":"결정했으니 다시 이야기하지 않는다","mis":"K5-1-u5-X45"}],"explanation":["적기만 하면 바뀌지 않아요.","이기는 말하기가 아니에요.","해 보고 되돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#4','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C48',3,'error','auto','토의를 준비하며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u5-X48','K5-1-u5-X38','K5-1-u5-X39']::text[],false,'{"seq":4,"concept":"K5-1-u5-C48","difficulty":3,"kind":"error","stem":"토의를 준비하며 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「상대 모둠을 이길 반박거리를 많이 모아 가자.」","correct":true,"mis_target":"K5-1-u5-X48"},{"t":"「의견마다 이유를 붙여 두자.」","mis":"K5-1-u5-X38"},{"t":"「자료를 찾으면 출처도 적어 두자.」","mis":"K5-1-u5-X39"}],"explanation":["이유는 준비해요.","출처도 준비해요.","이길 거리가 아니라 함께 쓸 재료를 준비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#5','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C47',3,'mc','auto','넓은 주제를 좁히는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X47','K5-1-u5-X37','K5-1-u5-X24']::text[],false,'{"seq":5,"concept":"K5-1-u5-C47","difficulty":3,"kind":"mc","stem":"넓은 주제를 좁히는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"누가 · 어디에서를 우리 반이나 우리 학교로 정해 해 볼 수 있는 크기로 만든다","correct":true},{"t":"주제 앞에 「세계」나 「모든」을 붙인다","mis":"K5-1-u5-X47"},{"t":"답이 하나인 질문으로 바꾼다","mis":"K5-1-u5-X37"},{"t":"주제를 정하지 않고 바로 의견을 낸다","mis":"K5-1-u5-X24"}],"explanation":["더 넓어져요.","토의할 거리가 사라져요.","주제부터 정해요."],"asset":{"type":"passage","lines":["너무 넓은 주제 — 환경을 지키는 방법","다듬은 주제 — 우리 반에서 종이컵 사용을 줄이는 방법"],"title":"주제 다듬기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#6','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C46',3,'mc','auto','도덕과 이어진 주제 「온라인에서 서로 지켜야 할 말과 태도」로 토의할 때 알맞은 방향은 어느 것인가요?',ARRAY['K5-1-u5-X23','K5-1-u5-X37']::text[],false,'{"seq":6,"concept":"K5-1-u5-C46","difficulty":3,"kind":"mc","stem":"도덕과 이어진 주제 「온라인에서 서로 지켜야 할 말과 태도」로 토의할 때 알맞은 방향은 어느 것인가요?","options":[{"t":"서로 존중하며 쓸 수 있는 말과 태도를 함께 정해 본다","correct":true},{"t":"누가 나쁜 말을 했는지 이름을 찾아낸다","mis":"K5-1-u5-X23"},{"t":"온라인은 아예 쓰지 말자고만 정한다","mis":"K5-1-u5-X23"},{"t":"가장 재미있는 누리집을 고른다","mis":"K5-1-u5-X37"}],"explanation":["사람을 찾으면 새 문제가 생겨요.","없애는 것만이 답은 아니에요.","우리가 지킬 말과 태도를 함께 정해요."],"asset":{"type":"passage","lines":["과학 — 교실에서 전기와 물을 아끼는 방법","사회 — 우리 마을 공공시설을 함께 쓰는 방법","도덕 — 온라인에서 서로 지켜야 할 말과 태도","실과 — 급식 남기는 양을 줄이는 방법"],"title":"다른 교과와 이어지는 토의 주제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#7','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C49',3,'mc','auto','글 「좋은 토의는 누가 만드는가」에 드러난 글쓴이의 관점은 어느 것인가요?',ARRAY['K5-1-u5-X49','K5-1-u5-X05','K5-1-u5-X32']::text[],false,'{"seq":7,"concept":"K5-1-u5-C49","difficulty":3,"kind":"mc","stem":"글 「좋은 토의는 누가 만드는가」에 드러난 글쓴이의 관점은 어느 것인가요?","options":[{"t":"좋은 토의의 몫은 참여한 모두에게 있다","correct":true},{"t":"사회자를 더 잘 뽑아야 토의가 잘된다","mis":"K5-1-u5-X49"},{"t":"토의는 하지 않는 편이 낫다","mis":"K5-1-u5-X05"},{"t":"차례 넘기기는 사회자만 할 수 있다","mis":"K5-1-u5-X32"}],"explanation":["사회자 이야기만이 아니에요.","글쓴이는 토의를 권해요.","제목과 마지막 문장을 함께 보아요."],"asset":{"type":"passage","lines":["토의를 잘 이끄는 일은 흔히 사회자의 몫이라고 여겨집니다.","그러나 좋은 토의는 한 사람의 솜씨로 만들어지지 않습니다.","이유 붙이기, 끊지 않고 듣기, 주제로 되돌리기, 차례 넘기기가 함께 일어나야 합니다.","이 가운데 사회자만 할 수 있는 일은 없습니다. 여럿이 나누어 할 때 더 잘됩니다.","그러므로 토의가 어긋났을 때 사회자 한 사람을 탓하는 것은 알맞지 않습니다.","좋은 토의는 모두가 함께 만드는 것입니다."],"title":"좋은 토의는 누가 만드는가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#8','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C47',4,'essay','teacher','「자원을 아끼는 방법」이라는 넓은 주제를 우리가 해 볼 수 있는 토의 주제로 좁혀 쓰고, 그렇게 좁힌 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u5-C47","difficulty":4,"kind":"essay","stem":"「자원을 아끼는 방법」이라는 넓은 주제를 우리가 해 볼 수 있는 토의 주제로 좁혀 쓰고, 그렇게 좁힌 까닭을 쓰세요.","answer_guide":{"answer":"예: 다듬은 주제 — 우리 반에서 이면지를 모아 다시 쓰는 방법. 「자원을 아끼는 방법」은 너무 넓어서 누구도 실천하지 못하는 결론이 나오기 쉽다. 우리 반 · 이면지로 좁히면 모두가 직접 해 보고 잘되었는지 되돌아볼 수 있다.","scoring_points":["넓은 주제를 좁혀 썼는가","우리가 해 볼 수 있는 크기인가","좁힌 까닭을 썼는가"]},"explanation":["누가 · 어디에서 할까요?","무엇을 아낄까요?","해 보고 되돌아볼 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#9','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C48',4,'essay','teacher','「교실에서 전기를 아끼는 방법」으로 토의한다고 할 때, 토의 전에 준비할 것을 네 가지 갈래로 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u5-C48","difficulty":4,"kind":"essay","stem":"「교실에서 전기를 아끼는 방법」으로 토의한다고 할 때, 토의 전에 준비할 것을 네 가지 갈래로 나누어 쓰세요.","answer_guide":{"answer":"예: 내 의견과 이유 — 쉬는 시간에 빈 교실의 불을 끄자, 아무도 없는 교실에 불이 켜져 있는 일이 많기 때문이다. 자료와 출처 — 우리 학교 행정실 안내문과 찾은 날. 협력 계획 — 의견에 이유를 붙이고 말을 끊지 않는다. 차례와 시간 — 한 사람씩 돌아가며 말하고 마칠 때를 정한다.","scoring_points":["내 의견과 이유를 썼는가","자료와 출처를 썼는가","협력 계획과 차례 · 시간 나누기를 썼는가"]},"explanation":["내 생각과 까닭은?","어디서 찾은 근거인가요?","어떻게 함께 말할까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_L12_challenge#10','kor',5,1,'u5','L12','g5_1_kor_u5_L12_challenge','lesson_challenge','K5-1-u5-C49',4,'essay','teacher','「좋은 토의는 모두가 함께 만든다」는 말을 내가 토의에서 맡을 수 있는 몫 두 가지를 예로 들어 설명하고, 토의하는 힘이 어떻게 길러지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u5-C49","difficulty":4,"kind":"essay","stem":"「좋은 토의는 모두가 함께 만든다」는 말을 내가 토의에서 맡을 수 있는 몫 두 가지를 예로 들어 설명하고, 토의하는 힘이 어떻게 길러지는지 쓰세요.","answer_guide":{"answer":"예: 나는 이야기가 주제에서 멀어지면 「지금 주제로 돌아가 볼까요?」 하고 되돌릴 수 있고, 아직 말하지 않은 친구에게 차례를 넘길 수 있다. 사회자가 아니어도 이런 몫을 맡으면 토의가 잘된다. 이런 힘은 한 번에 길러지지 않고 토의를 거듭할수록 조금씩 자란다.","scoring_points":["내가 맡을 몫을 두 가지 썼는가","모두가 함께 만든다는 뜻과 이어 썼는가","조금씩 자란다는 점을 썼는가"]},"explanation":["되돌리기를 떠올려요.","차례 넘기기도 있어요.","한 번에 길러지나요?"],"asset":{"type":"passage","lines":["토의를 잘 이끄는 일은 흔히 사회자의 몫이라고 여겨집니다.","그러나 좋은 토의는 한 사람의 솜씨로 만들어지지 않습니다.","이유 붙이기, 끊지 않고 듣기, 주제로 되돌리기, 차례 넘기기가 함께 일어나야 합니다.","이 가운데 사회자만 할 수 있는 일은 없습니다. 여럿이 나누어 할 때 더 잘됩니다.","그러므로 토의가 어긋났을 때 사회자 한 사람을 탓하는 것은 알맞지 않습니다.","좋은 토의는 모두가 함께 만드는 것입니다."],"title":"좋은 토의는 누가 만드는가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#1','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C51',1,'mc','auto','「부엌」의 바른 발음은 어느 것인가요?',ARRAY['K5-1-u5-X51']::text[],false,'{"seq":1,"concept":"K5-1-u5-C51","difficulty":1,"kind":"mc","stem":"「부엌」의 바른 발음은 어느 것인가요?","options":[{"t":"[부억]","correct":true},{"t":"[부엌]","mis":"K5-1-u5-X51"},{"t":"[부언]","mis":"K5-1-u5-X51"},{"t":"[부엉]","mis":"K5-1-u5-X51"}],"explanation":["쓴 글자대로 소리 나지 않아요.","ㅋ 받침은 [ㄴ]이 아니에요.","ㅋ 받침은 [ㄱ]으로 소리 나요."],"asset":{"type":"passage","lines":["받침소리 [ㄱ] — 약[약] · 밖[박] · 부엌[부억] · 떡[떡]","받침소리 [ㄷ] — 옷[옫] · 낮[낟] · 꽃[꼳] · 솥[솓]","받침소리 [ㅂ] — 입[입] · 앞[압] · 무릎[무릅]"],"title":"세 가지 받침소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#2','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C51',1,'mc','auto','받침이 [ㄱ]으로 소리 나는 받침끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X53','K5-1-u5-X52','K5-1-u5-X50']::text[],false,'{"seq":2,"concept":"K5-1-u5-C51","difficulty":1,"kind":"mc","stem":"받침이 [ㄱ]으로 소리 나는 받침끼리 묶은 것은 어느 것인가요?","options":[{"t":"ㄱ · ㄲ · ㅋ","correct":true},{"t":"ㅂ · ㅍ","mis":"K5-1-u5-X53"},{"t":"ㅅ · ㅈ · ㅊ","mis":"K5-1-u5-X52"},{"t":"ㄴ · ㅁ · ㅇ","mis":"K5-1-u5-X50"}],"explanation":["[ㅂ]으로 나요.","[ㄷ]으로 나요.","밖 · 부엌을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#3','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C2',1,'mc','auto','다흰이와 해찬이가 놀이 상자를 다르게 본 것을 두고 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X02','K5-1-u5-X01','K5-1-u5-X15']::text[],false,'{"seq":3,"concept":"K5-1-u5-C2","difficulty":1,"kind":"mc","stem":"다흰이와 해찬이가 놀이 상자를 다르게 본 것을 두고 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 사람은 놀이 상자를 바라보는 방향이 다를 뿐이다","correct":true},{"t":"해찬이는 틀렸고 다흰이만 옳다","mis":"K5-1-u5-X02"},{"t":"관점에는 언제나 하나의 정답이 있다","mis":"K5-1-u5-X01"},{"t":"두 글은 서로 다른 놀이 상자를 다루었다","mis":"K5-1-u5-X15"}],"explanation":["누가 틀린 것이 아니에요.","관점은 정답이 아니에요.","같은 놀이 상자를 다루었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#4','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C7',1,'mc','auto','해찬이의 글 제목 「놀이 상자, 이대로 괜찮을까요」에서 짐작할 수 있는 관점은 어느 것인가요?',ARRAY['K5-1-u5-X07']::text[],false,'{"seq":4,"concept":"K5-1-u5-C7","difficulty":1,"kind":"mc","stem":"해찬이의 글 제목 「놀이 상자, 이대로 괜찮을까요」에서 짐작할 수 있는 관점은 어느 것인가요?","options":[{"t":"지금 쓰는 방식에 문제가 없는지 따져 보려 한다","correct":true},{"t":"놀이 상자를 더 크게 만들자고 한다","mis":"K5-1-u5-X07"},{"t":"제목만으로는 아무것도 알 수 없다","mis":"K5-1-u5-X07"},{"t":"글쓴이가 쓴 날짜를 알 수 있다","mis":"K5-1-u5-X07"}],"explanation":["크기 이야기는 없어요.","제목의 낱말이 주는 느낌을 보아요.","「이대로 괜찮을까」는 따져 보자는 말이에요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#5','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C17',1,'mc','auto','안내 쪽지 ㉰의 마지막 줄에 담긴 관점은 어느 것인가요?',ARRAY['K5-1-u5-X17']::text[],false,'{"seq":5,"concept":"K5-1-u5-C17","difficulty":1,"kind":"mc","stem":"안내 쪽지 ㉰의 마지막 줄에 담긴 관점은 어느 것인가요?","options":[{"t":"모두의 물건이니 함께 아끼자","correct":true},{"t":"놀이 상자를 치우자","mis":"K5-1-u5-X17"},{"t":"선생님만 상자를 쓰자","mis":"K5-1-u5-X17"},{"t":"안내 쪽지에는 관점이 없다","mis":"K5-1-u5-X17"}],"explanation":["치우자는 말은 없어요.","모두의 놀이 상자예요.","짧은 글에도 관점이 담겨요."],"asset":{"type":"passage","lines":["쓴 놀이 도구는 종이 울리면 바로 상자에 넣어 주세요.","고장 난 도구는 선생님께 알려 주세요.","모두의 놀이 상자입니다. 아껴 써 주세요."],"title":"글 ㉰ 놀이 상자 옆 안내 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#6','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C24',1,'mc','auto','토의 절차에서 맨 처음 하는 일은 무엇인가요?',ARRAY['K5-1-u5-X24']::text[],false,'{"seq":6,"concept":"K5-1-u5-C24","difficulty":1,"kind":"mc","stem":"토의 절차에서 맨 처음 하는 일은 무엇인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 나누기","mis":"K5-1-u5-X24"},{"t":"의견 결정하기","mis":"K5-1-u5-X24"},{"t":"의견 모으기","mis":"K5-1-u5-X24"}],"explanation":["주제가 있어야 나눠요.","결정은 맨 끝이에요.","무엇을 토의할지부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#7','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C37',1,'mc','auto','보담네 모둠의 주제 후보 가운데 토의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X47','K5-1-u5-X37']::text[],false,'{"seq":7,"concept":"K5-1-u5-C37","difficulty":1,"kind":"mc","stem":"보담네 모둠의 주제 후보 가운데 토의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","correct":true},{"t":"㉡ 놀이 상자에 든 줄넘기는 몇 개일까","mis":"K5-1-u5-X22"},{"t":"㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","mis":"K5-1-u5-X47"},{"t":"㉣ 어떤 놀이가 가장 재미있을까","mis":"K5-1-u5-X37"}],"explanation":["세면 답이 나와요.","너무 넓어요.","여럿이 모아야 하고 해 볼 수 있어요."],"asset":{"type":"passage","lines":["㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","㉡ 놀이 상자에 든 줄넘기는 몇 개일까","㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","㉣ 어떤 놀이가 가장 재미있을까"],"title":"보담네 모둠의 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#8','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C43',1,'mc','auto','보담네 의견 가운데 「새 문제가 생기지 않는가」 기준에 어긋나는 것은 어느 것인가요?',ARRAY['K5-1-u5-X43']::text[],false,'{"seq":8,"concept":"K5-1-u5-C43","difficulty":1,"kind":"mc","stem":"보담네 의견 가운데 「새 문제가 생기지 않는가」 기준에 어긋나는 것은 어느 것인가요?","options":[{"t":"의견 ㉢ 돌려놓지 않은 사람의 이름을 칠판에 적는다","correct":true},{"t":"의견 ㉠ 요일마다 모둠이 돌아가며 쓴다","mis":"K5-1-u5-X43"},{"t":"의견 ㉡ 놀이 도우미가 종이 울리면 개수를 센다","mis":"K5-1-u5-X43"},{"t":"기준에 어긋나는 의견은 없다","mis":"K5-1-u5-X43"}],"explanation":["새 문제가 없어요.","이미 있는 역할이에요.","창피를 주면 새 문제가 생겨요."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#9','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C52',2,'mc','auto','「받침 낱말 모음」에서 「밭」의 받침은 어떤 소리로 나나요?',ARRAY['K5-1-u5-X52','K5-1-u5-X51','K5-1-u5-X53']::text[],false,'{"seq":9,"concept":"K5-1-u5-C52","difficulty":2,"kind":"mc","stem":"「받침 낱말 모음」에서 「밭」의 받침은 어떤 소리로 나나요?","options":[{"t":"[ㄷ]","correct":true},{"t":"[ㅌ]","mis":"K5-1-u5-X52"},{"t":"[ㄱ]","mis":"K5-1-u5-X51"},{"t":"[ㅂ]","mis":"K5-1-u5-X53"}],"explanation":["쓴 글자대로 나지 않아요.","ㄱ · ㄲ · ㅋ이 아니에요.","ㅌ 받침은 [ㄷ]으로 나요."],"asset":{"type":"passage","lines":["밭 · 숲 · 빛 · 낫 · 짚 · 동녘 · 잎 · 엿"],"title":"받침 낱말 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#10','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C10',2,'mc','auto','해찬이의 글을 끝까지 읽고 알 수 있는 관점은 어느 것인가요?',ARRAY['K5-1-u5-X10','K5-1-u5-X15','K5-1-u5-X35']::text[],false,'{"seq":10,"concept":"K5-1-u5-C10","difficulty":2,"kind":"mc","stem":"해찬이의 글을 끝까지 읽고 알 수 있는 관점은 어느 것인가요?","options":[{"t":"놀이 상자를 두되 쓰는 방법을 함께 정하자","correct":true},{"t":"놀이 상자를 아예 없애자","mis":"K5-1-u5-X10"},{"t":"지금 방식에 아무 문제가 없다","mis":"K5-1-u5-X15"},{"t":"줄넘기를 더 사 오자","mis":"K5-1-u5-X35"}],"explanation":["마지막 문장을 보아요.","문제점을 짚었어요.","없애자가 아니라 방법을 정하자예요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#11','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C8',2,'mc','auto','해찬이의 글에서 지금 방식을 걱정하는 관점이 드러난 표현은 어느 것인가요?',ARRAY['K5-1-u5-X08']::text[],false,'{"seq":11,"concept":"K5-1-u5-C8","difficulty":2,"kind":"mc","stem":"해찬이의 글에서 지금 방식을 걱정하는 관점이 드러난 표현은 어느 것인가요?","options":[{"t":"「써 보지도 못합니다」","correct":true},{"t":"「쉬는 시간」","mis":"K5-1-u5-X08"},{"t":"「놀이 상자가 생긴 뒤」","mis":"K5-1-u5-X08"},{"t":"「친구가 많습니다」","mis":"K5-1-u5-X08"}],"explanation":["때를 나타내는 말이에요.","때를 나타내는 말이에요.","아쉬움이 담긴 표현이에요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#12','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C19',2,'mc','auto','해찬이의 글을 믿을 수 있다고 판단할 근거로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X19','K5-1-u5-X07']::text[],false,'{"seq":12,"concept":"K5-1-u5-C19","difficulty":2,"kind":"mc","stem":"해찬이의 글을 믿을 수 있다고 판단할 근거로 알맞은 것은 어느 것인가요?","options":[{"t":"줄넘기가 열 개에서 네 개로 줄었다는, 확인할 수 있는 사실을 들었다","correct":true},{"t":"글이 길고 어려운 낱말이 많다","mis":"K5-1-u5-X19"},{"t":"내 생각과 같은 편이다","mis":"K5-1-u5-X19"},{"t":"제목이 질문으로 끝난다","mis":"K5-1-u5-X07"}],"explanation":["길고 어렵다고 믿을 만하지 않아요.","같은 편이라고 믿을 만하지 않아요.","확인할 수 있는 사실을 보아요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#13','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C25',2,'mc','auto','보담네 어긋난 토의에서 드러난 문제점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X31','K5-1-u5-X26','K5-1-u5-X29']::text[],false,'{"seq":13,"concept":"K5-1-u5-C25","difficulty":2,"kind":"mc","stem":"보담네 어긋난 토의에서 드러난 문제점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"사회자가 주제를 먼저 알려 주었다","correct":true},{"t":"이유 없이 반대했다","mis":"K5-1-u5-X31"},{"t":"사람을 탓했다","mis":"K5-1-u5-X26"},{"t":"주제와 관련 없는 의견을 냈다","mis":"K5-1-u5-X29"}],"explanation":["휘서의 말이에요.","해찬이의 말이에요.","주제를 알리는 것은 토의를 돕는 일이에요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#14','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C40',2,'mc','auto','다시 한 토의에서 해찬이의 「놀이 도우미가 종이 울리면 개수를 세면 어때요?」에 드러난 협력은 어느 것인가요?',ARRAY['K5-1-u5-X25','K5-1-u5-X31','K5-1-u5-X29']::text[],false,'{"seq":14,"concept":"K5-1-u5-C40","difficulty":2,"kind":"mc","stem":"다시 한 토의에서 해찬이의 「놀이 도우미가 종이 울리면 개수를 세면 어때요?」에 드러난 협력은 어느 것인가요?","options":[{"t":"앞의 지적을 받아 다음 의견을 냈다","correct":true},{"t":"자기 생각만 우겼다","mis":"K5-1-u5-X25"},{"t":"이유 없이 반대했다","mis":"K5-1-u5-X31"},{"t":"주제에서 벗어났다","mis":"K5-1-u5-X29"}],"explanation":["우기지 않았어요.","반대가 아니에요.","휘서의 걱정을 이어받았어요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#15','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C23',2,'mc','auto','의견 ㉣ 「놀이 상자를 치운다」가 알맞은 해결 방법이 아닌 까닭은 무엇인가요?',ARRAY['K5-1-u5-X43','K5-1-u5-X42']::text[],false,'{"seq":15,"concept":"K5-1-u5-C23","difficulty":2,"kind":"mc","stem":"의견 ㉣ 「놀이 상자를 치운다」가 알맞은 해결 방법이 아닌 까닭은 무엇인가요?","options":[{"t":"문제를 고치는 대신 모두가 놀이 상자를 쓰지 못하게 되기 때문이다","correct":true},{"t":"누구나 실천할 수 있기 때문이다","mis":"K5-1-u5-X43"},{"t":"가장 늦게 나온 의견이기 때문이다","mis":"K5-1-u5-X42"},{"t":"의견이 짧기 때문이다","mis":"K5-1-u5-X43"}],"explanation":["그건 좋은 점이에요.","차례는 기준이 아니에요.","새 문제가 생겨요."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#16','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C5',2,'mc','auto','보담네 다시 한 토의가 토의의 뜻에 맞는 까닭은 무엇인가요?',ARRAY['K5-1-u5-X05','K5-1-u5-X31','K5-1-u5-X32']::text[],false,'{"seq":16,"concept":"K5-1-u5-C5","difficulty":2,"kind":"mc","stem":"보담네 다시 한 토의가 토의의 뜻에 맞는 까닭은 무엇인가요?","options":[{"t":"서로 다른 생각을 모아 더 나은 답을 찾았기 때문이다","correct":true},{"t":"한 사람이 말싸움에서 이겼기 때문이다","mis":"K5-1-u5-X05"},{"t":"걱정을 말한 사람이 없었기 때문이다","mis":"K5-1-u5-X31"},{"t":"사회자가 혼자 정했기 때문이다","mis":"K5-1-u5-X32"}],"explanation":["이기는 말하기가 아니에요.","휘서가 걱정을 말했어요.","생각을 모아 더 나은 답을 찾았어요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#17','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C12',3,'mc','auto','「다흰이는 쉬는 시간마다 놀이에 끼었고, 해찬이는 도구를 정리하는 놀이 도우미였다.」고 할 때 바르게 짐작한 것은 어느 것인가요?',ARRAY['K5-1-u5-X12','K5-1-u5-X02']::text[],false,'{"seq":17,"concept":"K5-1-u5-C12","difficulty":3,"kind":"mc","stem":"「다흰이는 쉬는 시간마다 놀이에 끼었고, 해찬이는 도구를 정리하는 놀이 도우미였다.」고 할 때 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"겪은 일이 달라 같은 놀이 상자를 다르게 보았을 수 있다","correct":true},{"t":"놀이 도우미였던 해찬이가 틀렸다","mis":"K5-1-u5-X12"},{"t":"겪은 일과 관점은 관계없다","mis":"K5-1-u5-X12"},{"t":"둘 가운데 한 사람은 거짓을 썼다","mis":"K5-1-u5-X02"}],"explanation":["틀림이 아니에요.","겪은 일이 관점을 만들어요.","처지가 다르면 보는 것도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#18','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C20',3,'mc','auto','세 글을 겹쳐 볼 때 드러나는 사실을 바르게 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X15','K5-1-u5-X10','K5-1-u5-X17']::text[],false,'{"seq":18,"concept":"K5-1-u5-C20","difficulty":3,"kind":"mc","stem":"세 글을 겹쳐 볼 때 드러나는 사실을 바르게 묶은 것은 어느 것인가요?","options":[{"t":"친구들이 놀이 상자를 반기지만, 도구가 줄고 늘 같은 친구만 쓴다","correct":true},{"t":"놀이 상자는 아무 문제 없이 잘 쓰인다","mis":"K5-1-u5-X15"},{"t":"놀이 상자 때문에 쉬는 시간이 싫어졌다","mis":"K5-1-u5-X10"},{"t":"안내 쪽지 덕분에 문제가 모두 풀렸다","mis":"K5-1-u5-X17"}],"explanation":["문제점도 있어요.","쉬는 시간은 즐거워졌어요.","좋은 점과 문제를 함께 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#19','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C37',3,'mc','auto','보담네가 주제 ㉠을 고른 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X37','K5-1-u5-X47']::text[],false,'{"seq":19,"concept":"K5-1-u5-C37","difficulty":3,"kind":"mc","stem":"보담네가 주제 ㉠을 고른 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"답이 하나로 정해져 빨리 끝낼 수 있어서","correct":true},{"t":"여럿이 방법을 모아야 해서","mis":"K5-1-u5-X37"},{"t":"우리 반에서 실제로 해 볼 수 있어서","mis":"K5-1-u5-X47"},{"t":"우리 생활과 관련 있어서","mis":"K5-1-u5-X37"}],"explanation":["까닭이 맞아요.","까닭이 맞아요.","토의 주제는 여러 의견이 나와야 해요."],"asset":{"type":"passage","lines":["㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","㉡ 놀이 상자에 든 줄넘기는 몇 개일까","㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","㉣ 어떤 놀이가 가장 재미있을까"],"title":"보담네 모둠의 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#20','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C38',3,'mc','auto','의견 ㉠ 「요일마다 모둠이 돌아가며 쓴다」의 이유로 가장 타당한 것은 어느 것인가요?',ARRAY['K5-1-u5-X43','K5-1-u5-X38']::text[],false,'{"seq":20,"concept":"K5-1-u5-C38","difficulty":3,"kind":"mc","stem":"의견 ㉠ 「요일마다 모둠이 돌아가며 쓴다」의 이유로 가장 타당한 것은 어느 것인가요?","options":[{"t":"늘 같은 친구만 쓰는 일이 줄고 모두 한 번씩은 쓸 수 있다","correct":true},{"t":"단아가 제일 먼저 말해서","mis":"K5-1-u5-X43"},{"t":"다른 의견은 재미가 없어서","mis":"K5-1-u5-X38"},{"t":"요일을 정하는 게 좋아서","mis":"K5-1-u5-X38"}],"explanation":["누가 먼저 말했는지는 이유가 아니에요.","느낌은 이유가 아니에요.","그렇게 하면 왜 좋은지 말해요."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#21','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C50',3,'mc','auto','받침을 바르게 쓴 문장은 어느 것인가요?',ARRAY['K5-1-u5-X50','K5-1-u5-X52','K5-1-u5-X53']::text[],false,'{"seq":21,"concept":"K5-1-u5-C50","difficulty":3,"kind":"mc","stem":"받침을 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"앞마당 꽃밭에 잎이 무성하다.","correct":true},{"t":"압마당 꼳받에 입이 무성하다.","mis":"K5-1-u5-X50"},{"t":"앞마당 꽃밧에 잎이 무성하다.","mis":"K5-1-u5-X52"},{"t":"압마당 꽃밭에 입이 무성하다.","mis":"K5-1-u5-X53"}],"explanation":["소리 나는 대로 썼어요.","밭의 받침은 ㅌ이에요.","쓸 때는 원래 글자를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#22','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C45',3,'mc','auto','보담네 되돌아보기에서 해찬이의 말이 알맞은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X45']::text[],false,'{"seq":22,"concept":"K5-1-u5-C45","difficulty":3,"kind":"mc","stem":"보담네 되돌아보기에서 해찬이의 말이 알맞은 까닭은 무엇인가요?","options":[{"t":"아쉬운 점을 한 번에 다 고치려 하면 아무것도 바뀌지 않기 때문이다","correct":true},{"t":"아쉬운 점은 없는 것이 좋기 때문이다","mis":"K5-1-u5-X45"},{"t":"잘한 점만 이어 가면 되기 때문이다","mis":"K5-1-u5-X45"},{"t":"다음 토의는 하지 않을 것이기 때문이다","mis":"K5-1-u5-X45"}],"explanation":["아쉬운 점도 찾아요.","아쉬운 점도 고쳐요.","하나씩 고쳐 가요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"잘한 점은 걱정되는 점을 사람이 아니라 의견에 대해 말한 거야."},{"who":"단아","text":"아쉬운 점은 다흰이에게 차례를 늦게 넘긴 거고, 말을 끊은 것도 있었어."},{"who":"해찬","text":"그럼 다음 토의에서는 무엇부터 고칠지 하나만 정하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#23','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C11',4,'essay','teacher','다흰이의 글 ㉮와 해찬이의 글 ㉯에서 제목 · 사진 · 표현을 살펴 두 글쓴이의 관점을 각각 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u5-C11","difficulty":4,"kind":"essay","stem":"다흰이의 글 ㉮와 해찬이의 글 ㉯에서 제목 · 사진 · 표현을 살펴 두 글쓴이의 관점을 각각 쓰세요.","answer_guide":{"answer":"예: 다흰이는 제목 「놀이 상자 덕분에 즐거운 쉬는 시간」, 함께 웃는 친구들 사진, 「북적」 · 「작은 선물」 같은 표현으로 놀이 상자가 쉬는 시간을 즐겁게 한다는 관점을 드러냈다. 해찬이는 제목 「놀이 상자, 이대로 괜찮을까요」, 텅 빈 상자 사진, 「문제점」 · 「써 보지도 못합니다」 같은 표현으로 놀이 상자를 두되 쓰는 방법을 함께 정해야 한다는 관점을 드러냈다.","scoring_points":["다흰이의 관점을 근거와 함께 썼는가","해찬이의 관점을 근거와 함께 썼는가","제목 · 사진 · 표현을 살펴 썼는가"]},"explanation":["제목의 낱말을 보아요.","사진은 무엇을 담았나요?","느낌을 주는 표현을 찾아요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#24','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C26',4,'essay','teacher','보담네 어긋난 토의에서 문제가 된 말을 세 개 골라 쓰고, 각각을 협력하는 말로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u5-C26","difficulty":4,"kind":"essay","stem":"보담네 어긋난 토의에서 문제가 된 말을 세 개 골라 쓰고, 각각을 협력하는 말로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 휘서의 「그건 안 돼요. 그냥 싫어요.」는 「돌아가며 쓰면 도구가 다 돌아왔는지 모를까 봐 걱정돼요.」로 바꾼다. 해찬이의 「휘서는 맨날 공만 독차지하잖아.」는 「휘서가 반대한 이유를 들어 볼까요?」로 바꾼다. 다흰이의 그네 이야기는 「그네도 좋지만 지금은 놀이 상자 이야기부터 할게요.」로 바꾼다.","scoring_points":["문제가 된 말을 세 개 골랐는가","이유를 붙이거나 의견을 다루는 말로 바꾸었는가","주제에 맞게 바꾸었는가"]},"explanation":["이유 없는 반대는?","사람을 탓한 말은?","주제에서 벗어난 말은?"],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_a#25','kor',5,1,'u5','','g5_1_kor_u5_review_a','unit_review','K5-1-u5-C6',4,'essay','teacher','이 단원에서 배운 「다양한 관점의 글 읽기」가 「협력하며 토의하기」로 어떻게 이어지는지 놀이 상자 이야기를 예로 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u5-C6","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「다양한 관점의 글 읽기」가 「협력하며 토의하기」로 어떻게 이어지는지 놀이 상자 이야기를 예로 들어 쓰세요.","answer_guide":{"answer":"예: 다흰이와 해찬이의 글을 읽으며 놀이 상자의 좋은 점과 문제점이라는 서로 다른 관점을 알았다. 이 관점은 보담네 토의의 재료가 되어, 놀이 상자를 오래 쓰는 방법이라는 주제를 정하고 좋은 점은 살리고 문제는 고치는 의견을 합칠 수 있었다. 읽기에서 찾은 관점이 토의의 재료가 되고, 토의는 실천으로 이어진다.","scoring_points":["글 읽기에서 찾은 관점을 썼는가","그 관점이 토의에 쓰인 모습을 썼는가","읽기와 토의가 이어지는 까닭을 썼는가"]},"explanation":["두 글에서 무엇을 알았나요?","토의에 어떻게 쓰였나요?","두 공부를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#1','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C52',1,'mc','auto','「꽃」의 바른 발음은 어느 것인가요?',ARRAY['K5-1-u5-X52']::text[],false,'{"seq":1,"concept":"K5-1-u5-C52","difficulty":1,"kind":"mc","stem":"「꽃」의 바른 발음은 어느 것인가요?","options":[{"t":"[꼳]","correct":true},{"t":"[꽃]","mis":"K5-1-u5-X52"},{"t":"[꼿]","mis":"K5-1-u5-X52"},{"t":"[꼬]","mis":"K5-1-u5-X52"}],"explanation":["쓴 글자대로 소리 나지 않아요.","ㅅ도 [ㄷ]으로 나요.","ㅊ 받침은 [ㄷ]으로 소리 나요."],"asset":{"type":"passage","lines":["받침소리 [ㄱ] — 약[약] · 밖[박] · 부엌[부억] · 떡[떡]","받침소리 [ㄷ] — 옷[옫] · 낮[낟] · 꽃[꼳] · 솥[솓]","받침소리 [ㅂ] — 입[입] · 앞[압] · 무릎[무릅]"],"title":"세 가지 받침소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#2','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C52',1,'mc','auto','받침이 [ㄷ]으로 소리 나는 받침끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X51','K5-1-u5-X53','K5-1-u5-X50']::text[],false,'{"seq":2,"concept":"K5-1-u5-C52","difficulty":1,"kind":"mc","stem":"받침이 [ㄷ]으로 소리 나는 받침끼리 묶은 것은 어느 것인가요?","options":[{"t":"ㅅ · ㅈ · ㅊ · ㅌ","correct":true},{"t":"ㄱ · ㄲ · ㅋ","mis":"K5-1-u5-X51"},{"t":"ㅂ · ㅍ","mis":"K5-1-u5-X53"},{"t":"ㄹ · ㅁ · ㅇ","mis":"K5-1-u5-X50"}],"explanation":["[ㄱ]으로 나요.","[ㅂ]으로 나요.","옷 · 낮 · 꽃 · 솥을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#3','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C12',1,'mc','auto','다흰이와 해찬이의 관점이 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X12','K5-1-u5-X18','K5-1-u5-X01']::text[],false,'{"seq":3,"concept":"K5-1-u5-C12","difficulty":1,"kind":"mc","stem":"다흰이와 해찬이의 관점이 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"겪은 일과 눈여겨본 것이 서로 달라서","correct":true},{"t":"한 사람이 거짓말을 해서","mis":"K5-1-u5-X12"},{"t":"두 글의 길이가 달라서","mis":"K5-1-u5-X18"},{"t":"관점에는 정답이 있어서","mis":"K5-1-u5-X01"}],"explanation":["거짓말이 아니에요.","길이는 관계없어요.","겪은 일 · 아는 것이 관점을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#4','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C9',1,'mc','auto','두 글에 실린 사진에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X09','K5-1-u5-X15','K5-1-u5-X19']::text[],false,'{"seq":4,"concept":"K5-1-u5-C9","difficulty":1,"kind":"mc","stem":"두 글에 실린 사진에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"사진에도 글쓴이가 강조하려는 모습이 담겨 있다","correct":true},{"t":"사진은 꾸밈일 뿐 관점과 관계없다","mis":"K5-1-u5-X09"},{"t":"두 사진은 같은 모습을 담았다","mis":"K5-1-u5-X15"},{"t":"사진이 많을수록 믿을 만한 글이다","mis":"K5-1-u5-X19"}],"explanation":["사진도 관점을 드러내요.","웃는 친구들과 텅 빈 상자는 달라요.","무엇을 담았는지 보아요."],"asset":{"type":"passage","lines":["글 ㉮의 사진 — 줄넘기를 함께 넘으며 웃는 친구들","글 ㉯의 사진 — 텅 빈 놀이 상자와 바닥에 흩어진 공기"],"title":"두 글에 실린 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#5','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C15',1,'mc','auto','글 ㉮ · ㉯ · ㉰에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X15','K5-1-u5-X17']::text[],false,'{"seq":5,"concept":"K5-1-u5-C15","difficulty":1,"kind":"mc","stem":"글 ㉮ · ㉯ · ㉰에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"같은 놀이 상자를 두고 저마다 보여 주는 면이 다르다","correct":true},{"t":"세 글은 모두 같은 면을 보여 준다","mis":"K5-1-u5-X15"},{"t":"한 글만 읽어도 문제를 다 안다","mis":"K5-1-u5-X15"},{"t":"안내 쪽지는 놀이 상자와 관계없다","mis":"K5-1-u5-X17"}],"explanation":["좋은 점 · 문제점 · 규칙은 달라요.","한 글로는 놓쳐요.","세 글이 서로 다른 면을 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#6','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C31',1,'mc','auto','보담네 어긋난 토의에서 휘서의 「그건 안 돼요. 그냥 싫어요.」가 문제인 까닭은 무엇인가요?',ARRAY['K5-1-u5-X31','K5-1-u5-X26','K5-1-u5-X32']::text[],false,'{"seq":6,"concept":"K5-1-u5-C31","difficulty":1,"kind":"mc","stem":"보담네 어긋난 토의에서 휘서의 「그건 안 돼요. 그냥 싫어요.」가 문제인 까닭은 무엇인가요?","options":[{"t":"이유 없이 반대했기 때문이다","correct":true},{"t":"반대를 했기 때문이다","mis":"K5-1-u5-X31"},{"t":"목소리가 작았기 때문이다","mis":"K5-1-u5-X26"},{"t":"사회자가 아니면서 말했기 때문이다","mis":"K5-1-u5-X32"}],"explanation":["반대 자체는 문제가 아니에요.","목소리와 관계없어요.","「그냥」에는 이유가 없어요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#7','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C22',1,'mc','auto','주제 후보 ㉡이 토의 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X37']::text[],false,'{"seq":7,"concept":"K5-1-u5-C22","difficulty":1,"kind":"mc","stem":"주제 후보 ㉡이 토의 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"세어 보면 답이 하나로 정해지기 때문이다","correct":true},{"t":"주제가 너무 길기 때문이다","mis":"K5-1-u5-X22"},{"t":"놀이 상자와 관계없기 때문이다","mis":"K5-1-u5-X22"},{"t":"여럿이 의견을 모아야 하기 때문이다","mis":"K5-1-u5-X37"}],"explanation":["길이는 관계없어요.","놀이 상자 이야기예요.","사실 확인은 토의할 거리가 아니에요."],"asset":{"type":"passage","lines":["㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","㉡ 놀이 상자에 든 줄넘기는 몇 개일까","㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","㉣ 어떤 놀이가 가장 재미있을까"],"title":"보담네 모둠의 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#8','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C42',1,'mc','auto','보담네 모둠이 다시 한 토의에서 정한 의견은 어떻게 만들어졌나요?',ARRAY['K5-1-u5-X42','K5-1-u5-X32']::text[],false,'{"seq":8,"concept":"K5-1-u5-C42","difficulty":1,"kind":"mc","stem":"보담네 모둠이 다시 한 토의에서 정한 의견은 어떻게 만들어졌나요?","options":[{"t":"의견 ㉠과 ㉡의 좋은 점을 합쳐 만들었다","correct":true},{"t":"가장 먼저 나온 의견 하나로 정했다","mis":"K5-1-u5-X42"},{"t":"손을 들어 많이 나온 의견으로 정했다","mis":"K5-1-u5-X42"},{"t":"사회자가 혼자 정했다","mis":"K5-1-u5-X32"}],"explanation":["하나만 고르지 않았어요.","투표하지 않았어요.","단아가 합치자고 했어요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#9','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C53',2,'mc','auto','「숲」과 같은 대표 소리로 받침이 나는 낱말은 어느 것인가요?',ARRAY['K5-1-u5-X52','K5-1-u5-X51']::text[],false,'{"seq":9,"concept":"K5-1-u5-C53","difficulty":2,"kind":"mc","stem":"「숲」과 같은 대표 소리로 받침이 나는 낱말은 어느 것인가요?","options":[{"t":"잎","correct":true},{"t":"빛","mis":"K5-1-u5-X52"},{"t":"동녘","mis":"K5-1-u5-X51"},{"t":"엿","mis":"K5-1-u5-X52"}],"explanation":["[ㄷ]으로 나요.","[ㄱ]으로 나요.","ㅍ 받침끼리 [ㅂ]으로 나요."],"asset":{"type":"passage","lines":["밭 · 숲 · 빛 · 낫 · 짚 · 동녘 · 잎 · 엿"],"title":"받침 낱말 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#10','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C13',2,'mc','auto','다흰이와 해찬이의 글을 함께 읽으면 좋은 점은 무엇인가요?',ARRAY['K5-1-u5-X13','K5-1-u5-X12','K5-1-u5-X18']::text[],false,'{"seq":10,"concept":"K5-1-u5-C13","difficulty":2,"kind":"mc","stem":"다흰이와 해찬이의 글을 함께 읽으면 좋은 점은 무엇인가요?","options":[{"t":"놀이 상자의 좋은 점과 문제점을 모두 알 수 있다","correct":true},{"t":"헷갈리기만 하니 한 글만 읽는 것이 낫다","mis":"K5-1-u5-X13"},{"t":"누가 틀렸는지 가릴 수 있다","mis":"K5-1-u5-X12"},{"t":"두 글의 글자 수를 견줄 수 있다","mis":"K5-1-u5-X18"}],"explanation":["함께 읽어야 깊어져요.","틀림이 아니라 다름이에요.","몰랐던 면까지 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#11','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C10',2,'mc','auto','「문제점」 · 「줄었습니다」만 보고 「해찬이는 놀이 상자를 싫어한다」고 판단한 것이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X08','K5-1-u5-X07','K5-1-u5-X09']::text[],false,'{"seq":11,"concept":"K5-1-u5-C10","difficulty":2,"kind":"mc","stem":"「문제점」 · 「줄었습니다」만 보고 「해찬이는 놀이 상자를 싫어한다」고 판단한 것이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"마지막 문장에서 놀이 상자를 두되 쓰는 방법을 정하자고 했기 때문이다","correct":true},{"t":"「문제점」은 좋은 뜻의 낱말이기 때문이다","mis":"K5-1-u5-X08"},{"t":"글쓴이의 이름이 나와 있기 때문이다","mis":"K5-1-u5-X07"},{"t":"사진에 놀이 상자가 없기 때문이다","mis":"K5-1-u5-X09"}],"explanation":["좋은 뜻은 아니에요.","이름은 관점과 관계없어요.","끝까지 읽고 판단해요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#12','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C18',2,'mc','auto','놀이 상자에 대한 세 글을 평가할 때 쓸 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u5-X18','K5-1-u5-X19']::text[],false,'{"seq":12,"concept":"K5-1-u5-C18","difficulty":2,"kind":"mc","stem":"놀이 상자에 대한 세 글을 평가할 때 쓸 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글씨가 크고 예쁜가","correct":true},{"t":"제목이 내용을 잘 나타내는가","mis":"K5-1-u5-X18"},{"t":"내용을 신뢰할 수 있는가","mis":"K5-1-u5-X19"},{"t":"내 생각과 비슷한 점이 있는가","mis":"K5-1-u5-X18"}],"explanation":["기준이에요.","기준이에요.","글씨는 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#13','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C26',2,'mc','auto','해찬이의 말을 협력하는 말로 바르게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u5-X26','K5-1-u5-X29']::text[],false,'{"seq":13,"concept":"K5-1-u5-C26","difficulty":2,"kind":"mc","stem":"해찬이의 말을 협력하는 말로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"「휘서가 반대한 이유가 궁금해요. 걱정되는 점을 말해 줄래요?」","correct":true},{"t":"「휘서는 늘 그런 식이야.」","mis":"K5-1-u5-X26"},{"t":"「휘서 말은 듣지 말자.」","mis":"K5-1-u5-X26"},{"t":"「그냥 넘어가자.」","mis":"K5-1-u5-X29"}],"explanation":["또 사람을 탓해요.","존중이 아니에요.","사람 대신 의견의 이유를 물어요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#14','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C27',2,'mc','auto','해찬이가 의견과 함께 말한 이유는 무엇인가요?',ARRAY['K5-1-u5-X38','K5-1-u5-X27']::text[],false,'{"seq":14,"concept":"K5-1-u5-C27","difficulty":2,"kind":"mc","stem":"해찬이가 의견과 함께 말한 이유는 무엇인가요?","options":[{"t":"이미 있는 역할이라 새로 만들지 않아도 된다","correct":true},{"t":"내가 놀이 도우미라서","mis":"K5-1-u5-X38"},{"t":"다른 의견은 재미없어서","mis":"K5-1-u5-X38"},{"t":"이유는 말하지 않았다","mis":"K5-1-u5-X27"}],"explanation":["그런 말은 없어요.","느낌은 이유가 아니에요.","「이미 있는 역할」을 보아요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#15','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C43',2,'mc','auto','의견 ㉡을 네 기준으로 살핀 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X43','K5-1-u5-X23']::text[],false,'{"seq":15,"concept":"K5-1-u5-C43","difficulty":2,"kind":"mc","stem":"의견 ㉡을 네 기준으로 살핀 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"이미 있는 역할을 쓰니 꾸준히 이어 가기 쉽다","correct":true},{"t":"해찬이가 냈으니 좋은 의견이다","mis":"K5-1-u5-X43"},{"t":"새 문제가 생기니 고를 수 없다","mis":"K5-1-u5-X23"},{"t":"누구도 실천할 수 없다","mis":"K5-1-u5-X43"}],"explanation":["누가 냈는지는 기준이 아니에요.","창피를 주지 않아요.","꾸준히 할 수 있는지 보아요."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#16','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C6',2,'mc','auto','다흰이 · 해찬이의 글 읽기가 보담네 토의로 이어진 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X06']::text[],false,'{"seq":16,"concept":"K5-1-u5-C6","difficulty":2,"kind":"mc","stem":"다흰이 · 해찬이의 글 읽기가 보담네 토의로 이어진 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"글에서 찾은 좋은 점과 문제점이 토의 의견의 재료가 되었다","correct":true},{"t":"글 읽기와 토의는 서로 관계없다","mis":"K5-1-u5-X06"},{"t":"글을 읽었으니 토의할 필요가 없어졌다","mis":"K5-1-u5-X06"},{"t":"토의에서는 글의 제목만 외웠다","mis":"K5-1-u5-X06"}],"explanation":["두 공부는 이어져요.","읽고 나서 토의해요.","읽기에서 찾은 관점이 재료가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#17','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C14',3,'mc','auto','두 글을 읽은 단아의 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X14','K5-1-u5-X13','K5-1-u5-X10']::text[],false,'{"seq":17,"concept":"K5-1-u5-C14","difficulty":3,"kind":"mc","stem":"두 글을 읽은 단아의 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「놀이 상자는 두고, 쓰는 방법을 정하면 두 글의 걱정이 함께 풀리겠어.」","correct":true},{"t":"「다흰이 글이 맞으니 해찬이 글은 버릴래.」","mis":"K5-1-u5-X14"},{"t":"「둘 다 다르니 아무것도 믿지 않을래.」","mis":"K5-1-u5-X13"},{"t":"「해찬이 글이 맞으니 상자를 치우자.」","mis":"K5-1-u5-X10"}],"explanation":["한쪽만 고르지 않아요.","다른 관점은 생각을 넓혀요.","두 관점을 합쳐 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#18','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C22',3,'mc','auto','세 글을 읽고 토의로 다룰 만한 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22']::text[],false,'{"seq":18,"concept":"K5-1-u5-C22","difficulty":3,"kind":"mc","stem":"세 글을 읽고 토의로 다룰 만한 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 도구를 제때 돌려놓게 할 수 있을까?","correct":true},{"t":"줄넘기는 처음에 몇 개였을까?","mis":"K5-1-u5-X22"},{"t":"안내 쪽지는 누가 붙였을까?","mis":"K5-1-u5-X22"},{"t":"놀이 상자는 무슨 색일까?","mis":"K5-1-u5-X22"}],"explanation":["글에 답이 있어요.","사실 확인이에요.","여럿이 방법을 모아야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#19','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C47',3,'mc','auto','주제 후보 ㉢을 우리 반이 해 볼 수 있는 크기로 좁힌 것은 어느 것인가요?',ARRAY['K5-1-u5-X47','K5-1-u5-X37','K5-1-u5-X22']::text[],false,'{"seq":19,"concept":"K5-1-u5-C47","difficulty":3,"kind":"mc","stem":"주제 후보 ㉢을 우리 반이 해 볼 수 있는 크기로 좁힌 것은 어느 것인가요?","options":[{"t":"우리 반 쉬는 시간 놀이를 모두가 함께 즐기는 방법","correct":true},{"t":"온 나라 어린이의 놀이를 즐겁게 만드는 방법","mis":"K5-1-u5-X47"},{"t":"놀이란 무엇인가","mis":"K5-1-u5-X37"},{"t":"어제 가장 많이 한 놀이는 무엇이었나","mis":"K5-1-u5-X22"}],"explanation":["오히려 넓어요.","뜻을 묻는 질문이에요.","우리 반 · 쉬는 시간으로 좁혔어요."],"asset":{"type":"passage","lines":["㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","㉡ 놀이 상자에 든 줄넘기는 몇 개일까","㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","㉣ 어떤 놀이가 가장 재미있을까"],"title":"보담네 모둠의 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#20','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C39',3,'mc','auto','해찬이가 「줄넘기가 열 개에서 네 개로 줄었다」를 토의 근거로 쓸 때 함께 밝히면 좋은 것은 무엇인가요?',ARRAY['K5-1-u5-X39','K5-1-u5-X38']::text[],false,'{"seq":20,"concept":"K5-1-u5-C39","difficulty":3,"kind":"mc","stem":"해찬이가 「줄넘기가 열 개에서 네 개로 줄었다」를 토의 근거로 쓸 때 함께 밝히면 좋은 것은 무엇인가요?","options":[{"t":"언제 누가 세어 본 것인지 출처","correct":true},{"t":"줄넘기의 색깔","mis":"K5-1-u5-X39"},{"t":"해찬이가 좋아하는 놀이","mis":"K5-1-u5-X38"},{"t":"근거는 밝히지 않아도 된다","mis":"K5-1-u5-X39"}],"explanation":["색깔은 근거와 관계없어요.","좋아하는 것은 근거가 아니에요.","어디서 온 근거인지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#21','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C51',3,'mc','auto','받침이 대표 소리 [ㄱ]으로 나는 낱말끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X52','K5-1-u5-X53']::text[],false,'{"seq":21,"concept":"K5-1-u5-C51","difficulty":3,"kind":"mc","stem":"받침이 대표 소리 [ㄱ]으로 나는 낱말끼리 묶은 것은 어느 것인가요?","options":[{"t":"밖 · 부엌 · 동녘","correct":true},{"t":"밭 · 숲 · 빛","mis":"K5-1-u5-X52"},{"t":"잎 · 짚 · 무릎","mis":"K5-1-u5-X53"},{"t":"낫 · 엿 · 옷","mis":"K5-1-u5-X52"}],"explanation":["섞여 있어요.","[ㅂ]으로 나요.","ㄲ · ㅋ 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#22','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C49',3,'mc','auto','보담네 어긋난 토의가 끝난 뒤 「보담이가 사회를 못 봐서 그래.」라는 말에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X49','K5-1-u5-X26','K5-1-u5-X05']::text[],false,'{"seq":22,"concept":"K5-1-u5-C49","difficulty":3,"kind":"mc","stem":"보담네 어긋난 토의가 끝난 뒤 「보담이가 사회를 못 봐서 그래.」라는 말에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"참여한 모두에게 맡을 몫이 있었으므로 한 사람 탓으로 볼 수 없다","correct":true},{"t":"사회자의 탓이 맞다","mis":"K5-1-u5-X49"},{"t":"휘서 한 사람의 탓이다","mis":"K5-1-u5-X26"},{"t":"토의는 원래 어긋나니 할 필요가 없다","mis":"K5-1-u5-X05"}],"explanation":["한 사람 탓이 아니에요.","사람 탓을 또 하고 있어요.","모두가 함께 만드는 토의예요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#23','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C19',4,'essay','teacher','해찬이의 글 ㉯를 신뢰할 수 있는지 판단하고, 그 근거를 두 가지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u5-C19","difficulty":4,"kind":"essay","stem":"해찬이의 글 ㉯를 신뢰할 수 있는지 판단하고, 그 근거를 두 가지 쓰세요.","answer_guide":{"answer":"예: 신뢰할 수 있다. 첫째, 줄넘기가 열 개에서 네 개로 줄었다는 확인할 수 있는 사실을 들었다. 둘째, 즐거워졌다는 친구가 많다는 좋은 점도 함께 말해 한쪽 면만 부풀리지 않았다. 다만 누가 언제 세어 보았는지 출처를 밝히면 더 믿을 만하다.","scoring_points":["신뢰할 수 있는지 판단했는가","근거를 두 가지 썼는가","확인할 수 있는 사실이나 한쪽만 부풀리지 않았는지를 따졌는가"]},"explanation":["확인할 수 있는 사실이 있나요?","한쪽만 말했나요?","출처도 살펴요."],"asset":{"type":"passage","lines":["놀이 상자가 생긴 뒤 쉬는 시간이 즐거워졌다는 친구가 많습니다.","그러나 지금 방식에 문제점은 없는지 함께 살펴보아야 합니다.","먼저, 제때 돌려놓지 않아 줄넘기가 열 개에서 네 개로 줄었습니다.","또 늘 같은 친구들이 먼저 가져가 다른 친구는 써 보지도 못합니다.","따라서 놀이 상자를 두되 쓰는 방법을 함께 정해야 합니다."],"title":"글 ㉯ 「놀이 상자, 이대로 괜찮을까요」 — 해찬","hi":["문제점","줄었습니다","써 보지도 못합니다","함께 정해야"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#24','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C42',4,'essay','teacher','보담네 의견 ㉠과 ㉡의 장점과 단점을 쓰고, 두 의견을 합친 모둠 의견이 네 기준에 맞는지 살펴 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u5-C42","difficulty":4,"kind":"essay","stem":"보담네 의견 ㉠과 ㉡의 장점과 단점을 쓰고, 두 의견을 합친 모둠 의견이 네 기준에 맞는지 살펴 쓰세요.","answer_guide":{"answer":"예: ㉠은 모두 한 번씩 쓸 수 있지만 도구가 다 돌아왔는지 알기 어렵다. ㉡은 이미 있는 역할이라 새로 만들지 않아도 되지만 도우미의 일이 늘어난다. 합친 의견 — 요일마다 모둠이 돌아가며 쓰고, 놀이 도우미가 종이 울리면 개수를 센다. 누구나 할 수 있고, 이미 있는 역할이라 꾸준히 이어 갈 수 있으며, 도구가 줄어드는 문제를 막는 데 효과적이고, 창피를 주지 않아 새 문제도 없다.","scoring_points":["두 의견의 장점과 단점을 썼는가","합친 모둠 의견을 썼는가","네 기준으로 살펴 썼는가"]},"explanation":["㉠의 좋은 점과 걱정은?","㉡은?","실천 · 꾸준 · 효과 · 새 문제."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_b#25','kor',5,1,'u5','','g5_1_kor_u5_review_b','unit_review','K5-1-u5-C30',4,'essay','teacher','보담네 어긋난 토의와 다시 한 토의를 견주어, 협력하며 토의하는 세 방법이 다시 한 토의의 어디에서 드러났는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u5-C30","difficulty":4,"kind":"essay","stem":"보담네 어긋난 토의와 다시 한 토의를 견주어, 협력하며 토의하는 세 방법이 다시 한 토의의 어디에서 드러났는지 쓰세요.","answer_guide":{"answer":"예: 의견을 나누고 검토하기 — 해찬이가 의견에 「이미 있는 역할」이라는 이유를 붙였다. 존중하는 태도 — 휘서가 「그냥 싫어요」 대신 걱정되는 점을 의견에 대해 말했다. 협력하며 진행하기 — 보담이가 논의할 부분을 짚고, 단아가 두 의견을 합쳐 결론에 이르게 했다.","scoring_points":["검토가 드러난 곳을 썼는가","존중이 드러난 곳을 썼는가","협력하는 진행이 드러난 곳을 썼는가"]},"explanation":["이유가 붙은 말은?","걱정을 어떻게 말했나요?","결론으로 이끈 말은?"],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#1','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C53',1,'mc','auto','「무릎」의 바른 발음은 어느 것인가요?',ARRAY['K5-1-u5-X53']::text[],false,'{"seq":1,"concept":"K5-1-u5-C53","difficulty":1,"kind":"mc","stem":"「무릎」의 바른 발음은 어느 것인가요?","options":[{"t":"[무릅]","correct":true},{"t":"[무릎]","mis":"K5-1-u5-X53"},{"t":"[무른]","mis":"K5-1-u5-X53"},{"t":"[무르]","mis":"K5-1-u5-X53"}],"explanation":["쓴 글자대로 소리 나지 않아요.","ㅍ 받침은 [ㄴ]이 아니에요.","ㅍ 받침은 [ㅂ]으로 소리 나요."],"asset":{"type":"passage","lines":["받침소리 [ㄱ] — 약[약] · 밖[박] · 부엌[부억] · 떡[떡]","받침소리 [ㄷ] — 옷[옫] · 낮[낟] · 꽃[꼳] · 솥[솓]","받침소리 [ㅂ] — 입[입] · 앞[압] · 무릎[무릅]"],"title":"세 가지 받침소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#2','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C53',1,'mc','auto','받침이 [ㅂ]으로 소리 나는 받침끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X51','K5-1-u5-X52','K5-1-u5-X50']::text[],false,'{"seq":2,"concept":"K5-1-u5-C53","difficulty":1,"kind":"mc","stem":"받침이 [ㅂ]으로 소리 나는 받침끼리 묶은 것은 어느 것인가요?","options":[{"t":"ㅂ · ㅍ","correct":true},{"t":"ㄱ · ㅋ","mis":"K5-1-u5-X51"},{"t":"ㅌ · ㅊ","mis":"K5-1-u5-X52"},{"t":"ㄴ · ㄹ","mis":"K5-1-u5-X50"}],"explanation":["[ㄱ]으로 나요.","[ㄷ]으로 나요.","입 · 앞 · 무릎을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#3','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C14',1,'ox','auto','다흰이의 글과 해찬이의 글을 읽었다면 둘 가운데 한 사람의 편을 꼭 들어야 해요.',ARRAY['K5-1-u5-X14']::text[],false,'{"seq":3,"concept":"K5-1-u5-C14","difficulty":1,"kind":"ox","stem":"다흰이의 글과 해찬이의 글을 읽었다면 둘 가운데 한 사람의 편을 꼭 들어야 해요.","answer":"X","reason_options":[{"t":"두 관점을 합쳐 생각하거나 나만의 관점을 세울 수 있기 때문에","correct":true},{"t":"편을 들지 않으면 글을 읽은 것이 아니기 때문에","mis":"K5-1-u5-X14"}],"mis":"K5-1-u5-X14","explanation":["편 가르기가 아니에요.","합쳐 생각할 수 있어요.","나만의 관점도 세울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#4','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C8',1,'mc','auto','다흰이의 글에서 놀이 상자를 좋게 보는 관점이 드러난 표현은 어느 것인가요?',ARRAY['K5-1-u5-X08']::text[],false,'{"seq":4,"concept":"K5-1-u5-C8","difficulty":1,"kind":"mc","stem":"다흰이의 글에서 놀이 상자를 좋게 보는 관점이 드러난 표현은 어느 것인가요?","options":[{"t":"「작은 선물」","correct":true},{"t":"「쉬는 시간마다」","mis":"K5-1-u5-X08"},{"t":"「교실 뒤」","mis":"K5-1-u5-X08"},{"t":"「줄넘기와 공기」","mis":"K5-1-u5-X08"}],"explanation":["때를 나타내는 말이에요.","곳을 나타내는 말이에요.","선물이라는 낱말에 생각이 담겼어요."],"asset":{"type":"passage","lines":["쉬는 시간마다 교실 뒤 놀이 상자 앞이 북적입니다.","먼저, 줄넘기와 공기, 고무줄로 함께 노는 친구가 늘었습니다.","또 혼자 앉아 있던 친구도 자연스럽게 놀이에 끼게 되었습니다.","놀이 상자는 쉬는 시간을 반갑게 기다리게 하는 작은 선물입니다."],"title":"글 ㉮ 「놀이 상자 덕분에 즐거운 쉬는 시간」 — 다흰","hi":["북적","늘었습니다","자연스럽게","선물"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#5','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C16',1,'mc','auto','빌린 놀이 도구를 제때 상자에 도로 돌려주는 일을 뜻하는 낱말은 어느 것인가요?',ARRAY['K5-1-u5-X16']::text[],false,'{"seq":5,"concept":"K5-1-u5-C16","difficulty":1,"kind":"mc","stem":"빌린 놀이 도구를 제때 상자에 도로 돌려주는 일을 뜻하는 낱말은 어느 것인가요?","options":[{"t":"반납","correct":true},{"t":"대여","mis":"K5-1-u5-X16"},{"t":"훼손","mis":"K5-1-u5-X16"},{"t":"관리","mis":"K5-1-u5-X16"}],"explanation":["빌려줌이에요.","못 쓰게 함이에요.","도로 돌려줌이 반납이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#6','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C26',1,'mc','auto','해찬이의 「휘서는 맨날 공만 독차지하잖아.」가 문제인 까닭은 무엇인가요?',ARRAY['K5-1-u5-X26','K5-1-u5-X24','K5-1-u5-X25']::text[],false,'{"seq":6,"concept":"K5-1-u5-C26","difficulty":1,"kind":"mc","stem":"해찬이의 「휘서는 맨날 공만 독차지하잖아.」가 문제인 까닭은 무엇인가요?","options":[{"t":"의견이 아니라 사람을 탓하는 말이기 때문이다","correct":true},{"t":"말이 너무 짧기 때문이다","mis":"K5-1-u5-X26"},{"t":"주제를 먼저 말했기 때문이다","mis":"K5-1-u5-X24"},{"t":"이유를 물었기 때문이다","mis":"K5-1-u5-X25"}],"explanation":["길이와 관계없어요.","주제 이야기가 아니에요.","휘서라는 사람을 겨누었어요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#7','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C47',1,'mc','auto','주제 후보 ㉢이 토의 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X47']::text[],false,'{"seq":7,"concept":"K5-1-u5-C47","difficulty":1,"kind":"mc","stem":"주제 후보 ㉢이 토의 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"너무 넓어서 우리가 실천할 수 없기 때문이다","correct":true},{"t":"답이 하나로 정해지기 때문이다","mis":"K5-1-u5-X22"},{"t":"놀이를 다루기 때문이다","mis":"K5-1-u5-X47"},{"t":"우리 반 문제이기 때문이다","mis":"K5-1-u5-X47"}],"explanation":["답이 하나는 아니에요.","놀이도 주제가 될 수 있어요.","「세상의 모든」은 너무 커요."],"asset":{"type":"passage","lines":["㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","㉡ 놀이 상자에 든 줄넘기는 몇 개일까","㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","㉣ 어떤 놀이가 가장 재미있을까"],"title":"보담네 모둠의 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#8','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C41',1,'mc','auto','휘서가 의견 ㉠ 「요일마다 모둠이 돌아가며 쓴다」의 단점으로 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X41']::text[],false,'{"seq":8,"concept":"K5-1-u5-C41","difficulty":1,"kind":"mc","stem":"휘서가 의견 ㉠ 「요일마다 모둠이 돌아가며 쓴다」의 단점으로 말한 것은 어느 것인가요?","options":[{"t":"도구가 다 돌아왔는지 모를 수 있다","correct":true},{"t":"모두 한 번씩은 쓸 수 있다","mis":"K5-1-u5-X41"},{"t":"놀이 상자가 너무 커진다","mis":"K5-1-u5-X41"},{"t":"단점은 말하지 않았다","mis":"K5-1-u5-X41"}],"explanation":["그건 장점이에요.","크기 이야기는 없어요.","휘서의 첫 말을 보아요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#9','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C51',2,'mc','auto','「동녘」의 바른 발음은 어느 것인가요?',ARRAY['K5-1-u5-X51','K5-1-u5-X52','K5-1-u5-X53']::text[],false,'{"seq":9,"concept":"K5-1-u5-C51","difficulty":2,"kind":"mc","stem":"「동녘」의 바른 발음은 어느 것인가요?","options":[{"t":"[동녁]","correct":true},{"t":"[동녘]","mis":"K5-1-u5-X51"},{"t":"[동넏]","mis":"K5-1-u5-X52"},{"t":"[동녑]","mis":"K5-1-u5-X53"}],"explanation":["쓴 글자대로 나지 않아요.","ㅋ은 [ㄷ]이 아니에요.","ㅋ 받침은 [ㄱ]으로 나요."],"asset":{"type":"passage","lines":["밭 · 숲 · 빛 · 낫 · 짚 · 동녘 · 잎 · 엿"],"title":"받침 낱말 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#10','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C4',2,'mc','auto','다흰이의 글만 읽고 해결 방법을 찾으면 어떤 일이 생기기 쉬운가요?',ARRAY['K5-1-u5-X15','K5-1-u5-X04']::text[],false,'{"seq":10,"concept":"K5-1-u5-C4","difficulty":2,"kind":"mc","stem":"다흰이의 글만 읽고 해결 방법을 찾으면 어떤 일이 생기기 쉬운가요?","options":[{"t":"도구가 줄어드는 문제를 놓칠 수 있다","correct":true},{"t":"모든 문제를 다 알 수 있다","mis":"K5-1-u5-X15"},{"t":"토의에서 반드시 이긴다","mis":"K5-1-u5-X04"},{"t":"놀이 상자가 저절로 늘어난다","mis":"K5-1-u5-X04"}],"explanation":["한 글은 한 면만 보여요.","이기려고 읽지 않아요.","혼자 보면 놓치는 부분이 생겨요."],"asset":{"type":"passage","lines":["쉬는 시간마다 교실 뒤 놀이 상자 앞이 북적입니다.","먼저, 줄넘기와 공기, 고무줄로 함께 노는 친구가 늘었습니다.","또 혼자 앉아 있던 친구도 자연스럽게 놀이에 끼게 되었습니다.","놀이 상자는 쉬는 시간을 반갑게 기다리게 하는 작은 선물입니다."],"title":"글 ㉮ 「놀이 상자 덕분에 즐거운 쉬는 시간」 — 다흰","hi":["북적","늘었습니다","자연스럽게","선물"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#11','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C8',2,'mc','auto','다흰이가 「북적입니다」라는 표현을 쓴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X08','K5-1-u5-X10','K5-1-u5-X18']::text[],false,'{"seq":11,"concept":"K5-1-u5-C8","difficulty":2,"kind":"mc","stem":"다흰이가 「북적입니다」라는 표현을 쓴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"놀이 상자 덕분에 함께 노는 친구가 많아졌음을 드러내려고","correct":true},{"t":"교실이 시끄럽다고 꾸짖으려고","mis":"K5-1-u5-X08"},{"t":"놀이 상자를 치우자고 하려고","mis":"K5-1-u5-X10"},{"t":"글자 수를 늘리려고","mis":"K5-1-u5-X18"}],"explanation":["꾸짖는 글이 아니에요.","치우자는 말은 없어요.","반가운 모습을 그린 낱말이에요."],"asset":{"type":"passage","lines":["쉬는 시간마다 교실 뒤 놀이 상자 앞이 북적입니다.","먼저, 줄넘기와 공기, 고무줄로 함께 노는 친구가 늘었습니다.","또 혼자 앉아 있던 친구도 자연스럽게 놀이에 끼게 되었습니다.","놀이 상자는 쉬는 시간을 반갑게 기다리게 하는 작은 선물입니다."],"title":"글 ㉮ 「놀이 상자 덕분에 즐거운 쉬는 시간」 — 다흰","hi":["북적","늘었습니다","자연스럽게","선물"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#12','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C21',2,'mc','auto','놀이 상자에 대한 글을 더 찾아 읽으려는 휘서에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X21','K5-1-u5-X15','K5-1-u5-X19']::text[],false,'{"seq":12,"concept":"K5-1-u5-C21","difficulty":2,"kind":"mc","stem":"놀이 상자에 대한 글을 더 찾아 읽으려는 휘서에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「네 생각과 다른 관점의 글도 함께 찾아봐.」","correct":true},{"t":"「네 생각과 같은 글만 모으면 돼.」","mis":"K5-1-u5-X21"},{"t":"「한 편이면 충분해.」","mis":"K5-1-u5-X15"},{"t":"「가장 긴 글만 찾아.」","mis":"K5-1-u5-X19"}],"explanation":["같은 편 글만 모으면 문제가 남아요.","한 편은 한 면뿐이에요.","다른 관점 글도 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#13','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C29',2,'mc','auto','다흰이의 그네 이야기가 나왔을 때 협력하며 진행하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X26','K5-1-u5-X29']::text[],false,'{"seq":13,"concept":"K5-1-u5-C29","difficulty":2,"kind":"mc","stem":"다흰이의 그네 이야기가 나왔을 때 협력하며 진행하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「그네도 좋지만, 지금은 놀이 상자를 오래 쓰는 방법부터 이야기해 볼까요?」","correct":true},{"t":"「그런 말은 하지 마.」","mis":"K5-1-u5-X26"},{"t":"「그네 이야기를 더 해 봐요.」","mis":"K5-1-u5-X29"},{"t":"(아무 말 없이 넘어간다)","mis":"K5-1-u5-X29"}],"explanation":["핀잔이에요.","주제에서 더 멀어져요.","부드럽게 주제로 되돌려요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#14','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C28',2,'mc','auto','두 토의를 견주어 볼 때 다시 한 토의에서 달라진 태도는 어느 것인가요?',ARRAY['K5-1-u5-X40','K5-1-u5-X31','K5-1-u5-X32']::text[],false,'{"seq":14,"concept":"K5-1-u5-C28","difficulty":2,"kind":"mc","stem":"두 토의를 견주어 볼 때 다시 한 토의에서 달라진 태도는 어느 것인가요?","options":[{"t":"사람이 아니라 의견을 다루며 끝까지 들었다","correct":true},{"t":"목소리가 큰 사람이 정했다","mis":"K5-1-u5-X40"},{"t":"반대는 아무도 하지 않았다","mis":"K5-1-u5-X31"},{"t":"사회자 혼자만 말했다","mis":"K5-1-u5-X32"}],"explanation":["목소리로 정하지 않았어요.","걱정을 말한 친구가 있어요.","모두가 말하고 끝까지 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#15','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C41',2,'mc','auto','의견 ㉡ 「놀이 도우미가 개수를 센다」의 단점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X41','K5-1-u5-X23']::text[],false,'{"seq":15,"concept":"K5-1-u5-C41","difficulty":2,"kind":"mc","stem":"의견 ㉡ 「놀이 도우미가 개수를 센다」의 단점으로 알맞은 것은 어느 것인가요?","options":[{"t":"놀이 도우미가 맡는 일이 늘어난다","correct":true},{"t":"모두가 놀이 상자를 쓸 수 없게 된다","mis":"K5-1-u5-X41"},{"t":"창피를 당하는 친구가 생긴다","mis":"K5-1-u5-X23"},{"t":"단점은 하나도 없다","mis":"K5-1-u5-X41"}],"explanation":["그건 ㉣의 단점이에요.","그건 ㉢의 단점이에요.","어느 의견에나 단점이 있어요."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#16','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C30',2,'mc','auto','검토 · 존중 · 협력하는 진행 가운데 하나만 지키면 어떻게 되나요?',ARRAY['K5-1-u5-X30','K5-1-u5-X32']::text[],false,'{"seq":16,"concept":"K5-1-u5-C30","difficulty":2,"kind":"mc","stem":"검토 · 존중 · 협력하는 진행 가운데 하나만 지키면 어떻게 되나요?","options":[{"t":"토의가 결론까지 가기 어렵다","correct":true},{"t":"하나만 지켜도 토의는 잘된다","mis":"K5-1-u5-X30"},{"t":"셋을 외우기만 하면 된다","mis":"K5-1-u5-X30"},{"t":"사회자가 나머지를 모두 맡는다","mis":"K5-1-u5-X32"}],"explanation":["하나로는 부족해요.","외우기가 목적이 아니에요.","셋이 함께여야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#17','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C2',3,'mc','auto','세 글을 두고 「같은 일인데 왜 생각이 다를까?」라는 물음에 답한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X02','K5-1-u5-X01','K5-1-u5-X15']::text[],false,'{"seq":17,"concept":"K5-1-u5-C2","difficulty":3,"kind":"mc","stem":"세 글을 두고 「같은 일인데 왜 생각이 다를까?」라는 물음에 답한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇에 무게를 두느냐가 저마다 달라서이다","correct":true},{"t":"누군가 틀린 말을 해서이다","mis":"K5-1-u5-X02"},{"t":"관점에는 정답이 하나 있어서이다","mis":"K5-1-u5-X01"},{"t":"셋이 서로 다른 놀이 상자를 보아서이다","mis":"K5-1-u5-X15"}],"explanation":["틀린 사람은 없어요.","관점은 정답이 아니에요.","같은 상자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#18','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C15',3,'mc','auto','안내 쪽지 ㉰가 다른 두 글과 다르게 보여 주는 면은 무엇인가요?',ARRAY['K5-1-u5-X15','K5-1-u5-X17']::text[],false,'{"seq":18,"concept":"K5-1-u5-C15","difficulty":3,"kind":"mc","stem":"안내 쪽지 ㉰가 다른 두 글과 다르게 보여 주는 면은 무엇인가요?","options":[{"t":"놀이 상자를 쓸 때 지킬 규칙","correct":true},{"t":"놀이 상자의 좋은 점","mis":"K5-1-u5-X15"},{"t":"놀이 상자의 문제점","mis":"K5-1-u5-X15"},{"t":"놀이 상자를 만든 사람","mis":"K5-1-u5-X17"}],"explanation":["글 ㉮의 몫이에요.","글 ㉯의 몫이에요.","쪽지는 지킬 일을 알려요."],"asset":{"type":"passage","lines":["쓴 놀이 도구는 종이 울리면 바로 상자에 넣어 주세요.","고장 난 도구는 선생님께 알려 주세요.","모두의 놀이 상자입니다. 아껴 써 주세요."],"title":"글 ㉰ 놀이 상자 옆 안내 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#19','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C46',3,'mc','auto','놀이 상자 문제를 다른 교과와 이어 본 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X37','K5-1-u5-X23']::text[],false,'{"seq":19,"concept":"K5-1-u5-C46","difficulty":3,"kind":"mc","stem":"놀이 상자 문제를 다른 교과와 이어 본 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"실과 — 놀이 도구를 오래 쓰도록 정리하고 고치는 방법","correct":true},{"t":"국어 — 놀이 상자는 몇 개일까","mis":"K5-1-u5-X22"},{"t":"과학 — 가장 재미있는 놀이 고르기","mis":"K5-1-u5-X37"},{"t":"도덕 — 돌려놓지 않은 친구 이름 알리기","mis":"K5-1-u5-X23"}],"explanation":["답이 하나예요.","취향을 묻고 있어요.","새 문제가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#20','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C35',3,'mc','auto','기사 「작은 나눔이 만든 변화」와 보담네 놀이 상자 문제를 이어 본 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X35','K5-1-u5-X32']::text[],false,'{"seq":20,"concept":"K5-1-u5-C35","difficulty":3,"kind":"mc","stem":"기사 「작은 나눔이 만든 변화」와 보담네 놀이 상자 문제를 이어 본 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"여럿이 돌아가며 살피면 함께 쓰는 물건도 오래 지켜진다","correct":true},{"t":"돈을 많이 들여야 물건이 지켜진다","mis":"K5-1-u5-X35"},{"t":"신문에 나야 문제가 풀린다","mis":"K5-1-u5-X35"},{"t":"한 사람이 혼자 다 맡아야 오래간다","mis":"K5-1-u5-X32"}],"explanation":["기사에 돈 이야기는 없어요.","신문 이야기도 없어요.","마을 사람들이 함께 돌보았어요."],"asset":{"type":"passage","lines":["한 마을 어귀의 나무 상자에 「가져가도, 두고 가도 좋은 책」이라고 적혀 있다.","두 해 전, 이 마을의 한 초등학생이 다 읽은 책을 정류장 옆에 두면서 시작되었다.","버스를 기다리는 시간이 지루하다는 말을 자주 들었기 때문이다.","처음에는 책이 줄기만 했지만, 몇 달 뒤 누군가 두고 간 낯선 책이 늘기 시작했다.","지금은 마을 사람들이 돌아가며 상자를 살피고, 상자는 세 곳으로 늘었다.","처음 상자를 놓은 학생은 「그냥 제 책이 놀고 있어서요.」라고 말했다."],"title":"기사 — 작은 나눔이 만든 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#21','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C53',3,'mc','auto','받침이 대표 소리 [ㅂ]으로 나는 낱말끼리 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X51','K5-1-u5-X52']::text[],false,'{"seq":21,"concept":"K5-1-u5-C53","difficulty":3,"kind":"mc","stem":"받침이 대표 소리 [ㅂ]으로 나는 낱말끼리 묶은 것은 어느 것인가요?","options":[{"t":"숲 · 잎 · 짚","correct":true},{"t":"밖 · 부엌 · 떡","mis":"K5-1-u5-X51"},{"t":"빛 · 솥 · 낮","mis":"K5-1-u5-X52"},{"t":"낫 · 엿 · 꽃","mis":"K5-1-u5-X52"}],"explanation":["[ㄱ]으로 나요.","[ㄷ]으로 나요.","ㅍ 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#22','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C44',3,'mc','auto','다른 모둠 발표를 들은 보담네가 「도구에 이름표를 붙이자」는 생각을 보탰다면 이것이 보여 주는 것은 무엇인가요?',ARRAY['K5-1-u5-X03','K5-1-u5-X44']::text[],false,'{"seq":22,"concept":"K5-1-u5-C44","difficulty":3,"kind":"mc","stem":"다른 모둠 발표를 들은 보담네가 「도구에 이름표를 붙이자」는 생각을 보탰다면 이것이 보여 주는 것은 무엇인가요?","options":[{"t":"다른 모둠의 의견을 들을 때에도 토의가 이어진다","correct":true},{"t":"다른 모둠 의견을 그대로 베꼈다","mis":"K5-1-u5-X03"},{"t":"우리 의견이 졌다","mis":"K5-1-u5-X44"},{"t":"발표는 들을 필요가 없다","mis":"K5-1-u5-X44"}],"explanation":["견주어 보탠 거예요.","이기고 지는 일이 아니에요.","보탤 점을 찾으며 들었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#23','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C20',4,'essay','teacher','세 글 ㉮ · ㉯ · ㉰를 겹쳐 보고 「어떻게 하면 ~할 수 있을까?」 꼴로 문제 상황을 정한 뒤, 그렇게 정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u5-C20","difficulty":4,"kind":"essay","stem":"세 글 ㉮ · ㉯ · ㉰를 겹쳐 보고 「어떻게 하면 ~할 수 있을까?」 꼴로 문제 상황을 정한 뒤, 그렇게 정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 문제 상황 — 어떻게 하면 놀이 상자를 모두가 고르게, 오래 쓸 수 있을까? 글 ㉮는 놀이 상자가 쉬는 시간을 즐겁게 한다는 좋은 점을, 글 ㉯는 도구가 줄고 같은 친구만 쓴다는 문제를, 글 ㉰는 제때 넣자는 규칙을 보여 준다. 셋을 겹치면 좋은 점은 살리고 문제는 고쳐야 한다는 것이 드러난다.","scoring_points":["문제 상황을 「어떻게 하면」 꼴로 썼는가","세 글이 보여 주는 면을 각각 썼는가","겹쳐 본 까닭을 썼는가"]},"explanation":["글 ㉮는 무엇을 보여 주나요?","글 ㉯와 ㉰는?","셋을 겹쳐 보아요."],"asset":{"type":"passage","lines":["쓴 놀이 도구는 종이 울리면 바로 상자에 넣어 주세요.","고장 난 도구는 선생님께 알려 주세요.","모두의 놀이 상자입니다. 아껴 써 주세요."],"title":"글 ㉰ 놀이 상자 옆 안내 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#24','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C45',4,'essay','teacher','보담네 되돌아보기를 보고, 다음 토의에서 고칠 한 가지를 골라 그 까닭과 다음 토의에서 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u5-C45","difficulty":4,"kind":"essay","stem":"보담네 되돌아보기를 보고, 다음 토의에서 고칠 한 가지를 골라 그 까닭과 다음 토의에서 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 고칠 한 가지 — 말수가 적은 친구에게 차례를 늦게 넘긴 것. 다흰이가 늦게 말하게 되어 의견이 다 모이지 못했기 때문이다. 다음 토의를 시작하기 전에 이 점을 다시 꺼내 보고, 한 바퀴 돌아가며 모두 한 번씩 말한 뒤 자유롭게 이야기한다.","scoring_points":["고칠 점을 한 가지만 골랐는가","고르는 까닭을 썼는가","다음 토의에서 할 일을 구체적으로 썼는가"]},"explanation":["아쉬운 점 가운데 하나만.","왜 그것부터일까요?","다음 토의 전에 다시 꺼내요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"잘한 점은 걱정되는 점을 사람이 아니라 의견에 대해 말한 거야."},{"who":"단아","text":"아쉬운 점은 다흰이에게 차례를 늦게 넘긴 거고, 말을 끊은 것도 있었어."},{"who":"해찬","text":"그럼 다음 토의에서는 무엇부터 고칠지 하나만 정하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_c#25','kor',5,1,'u5','','g5_1_kor_u5_review_c','unit_review','K5-1-u5-C49',4,'essay','teacher','글 「좋은 토의는 누가 만드는가」의 관점을 쓰고, 보담네 다시 한 토의에서 사회자가 아닌 친구가 맡은 몫을 예로 들어 그 관점을 뒷받침하세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u5-C49","difficulty":4,"kind":"essay","stem":"글 「좋은 토의는 누가 만드는가」의 관점을 쓰고, 보담네 다시 한 토의에서 사회자가 아닌 친구가 맡은 몫을 예로 들어 그 관점을 뒷받침하세요.","answer_guide":{"answer":"예: 이 글은 좋은 토의의 몫이 참여한 모두에게 있다는 관점을 드러낸다. 보담네 다시 한 토의에서 사회자가 아닌 휘서는 걱정되는 점을 말해 의견을 다듬었고, 해찬이는 그 걱정을 이어받아 의견을 냈으며, 단아는 두 의견을 합쳤다. 다흰이는 해 보고 다시 이야기하자며 실천으로 이었다. 모두가 몫을 맡았기에 좋은 토의가 되었다.","scoring_points":["글쓴이의 관점을 썼는가","사회자가 아닌 친구의 몫을 예로 들었는가","예가 관점을 뒷받침하게 썼는가"]},"explanation":["제목과 마지막 문장을 보아요.","누가 어떤 몫을 했나요?","관점과 이어요."],"asset":{"type":"passage","lines":["토의를 잘 이끄는 일은 흔히 사회자의 몫이라고 여겨집니다.","그러나 좋은 토의는 한 사람의 솜씨로 만들어지지 않습니다.","이유 붙이기, 끊지 않고 듣기, 주제로 되돌리기, 차례 넘기기가 함께 일어나야 합니다.","이 가운데 사회자만 할 수 있는 일은 없습니다. 여럿이 나누어 할 때 더 잘됩니다.","그러므로 토의가 어긋났을 때 사회자 한 사람을 탓하는 것은 알맞지 않습니다.","좋은 토의는 모두가 함께 만드는 것입니다."],"title":"좋은 토의는 누가 만드는가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#1','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C52',1,'mc','auto','「낮」의 바른 발음은 어느 것인가요?',ARRAY['K5-1-u5-X52']::text[],false,'{"seq":1,"concept":"K5-1-u5-C52","difficulty":1,"kind":"mc","stem":"「낮」의 바른 발음은 어느 것인가요?","options":[{"t":"[낟]","correct":true},{"t":"[낮]","mis":"K5-1-u5-X52"},{"t":"[난]","mis":"K5-1-u5-X52"},{"t":"[낫]","mis":"K5-1-u5-X52"}],"explanation":["쓴 글자대로 소리 나지 않아요.","ㅈ 받침은 [ㄴ]이 아니에요.","ㅈ 받침은 [ㄷ]으로 소리 나요."],"asset":{"type":"passage","lines":["받침소리 [ㄱ] — 약[약] · 밖[박] · 부엌[부억] · 떡[떡]","받침소리 [ㄷ] — 옷[옫] · 낮[낟] · 꽃[꼳] · 솥[솓]","받침소리 [ㅂ] — 입[입] · 앞[압] · 무릎[무릅]"],"title":"세 가지 받침소리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#2','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C50',1,'ox','auto','받침은 소리 나는 대로 바꾸어 써야 해요. 그래서 「꽃」은 「꼳」으로 써요.',ARRAY['K5-1-u5-X50']::text[],false,'{"seq":2,"concept":"K5-1-u5-C50","difficulty":1,"kind":"ox","stem":"받침은 소리 나는 대로 바꾸어 써야 해요. 그래서 「꽃」은 「꼳」으로 써요.","answer":"X","reason_options":[{"t":"소리가 같아도 쓸 때는 원래 글자를 쓰기 때문에","correct":true},{"t":"글자는 언제나 소리 나는 대로 쓰기 때문에","mis":"K5-1-u5-X50"}],"mis":"K5-1-u5-X50","explanation":["소리와 글자는 달라요.","읽을 때만 [꼳]이에요.","쓸 때는 원래 글자 「꽃」을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#3','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C1',1,'mc','auto','「관점」이라는 낱말이 알맞게 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u5-X01']::text[],false,'{"seq":3,"concept":"K5-1-u5-C1","difficulty":1,"kind":"mc","stem":"「관점」이라는 낱말이 알맞게 쓰인 문장은 어느 것인가요?","options":[{"t":"「같은 놀이 상자를 두고도 친구마다 관점이 다르다.」","correct":true},{"t":"「놀이 상자의 관점은 네모 모양이다.」","mis":"K5-1-u5-X01"},{"t":"「관점을 재어 보니 한 뼘이었다.」","mis":"K5-1-u5-X01"},{"t":"「이 글의 관점은 오늘 날짜이다.」","mis":"K5-1-u5-X01"}],"explanation":["모양은 관점이 아니에요.","재는 기준이 아니에요.","바라보는 태도 · 방향이 관점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#4','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C11',1,'mc','auto','글쓴이의 관점을 파악할 때 살펴볼 곳이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u5-X11','K5-1-u5-X09','K5-1-u5-X08']::text[],false,'{"seq":4,"concept":"K5-1-u5-C11","difficulty":1,"kind":"mc","stem":"글쓴이의 관점을 파악할 때 살펴볼 곳이 아닌 것은 어느 것인가요?","options":[{"t":"글의 글자 수","correct":true},{"t":"제목","mis":"K5-1-u5-X11"},{"t":"사진이나 그림","mis":"K5-1-u5-X09"},{"t":"표현","mis":"K5-1-u5-X08"}],"explanation":["살펴볼 곳이에요.","살펴볼 곳이에요.","글자 수는 관점과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#5','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C16',1,'mc','auto','도구를 헐거나 깨뜨려 못 쓰게 하는 일을 뜻하는 낱말은 어느 것인가요?',ARRAY['K5-1-u5-X16']::text[],false,'{"seq":5,"concept":"K5-1-u5-C16","difficulty":1,"kind":"mc","stem":"도구를 헐거나 깨뜨려 못 쓰게 하는 일을 뜻하는 낱말은 어느 것인가요?","options":[{"t":"훼손","correct":true},{"t":"반납","mis":"K5-1-u5-X16"},{"t":"대여","mis":"K5-1-u5-X16"},{"t":"관리","mis":"K5-1-u5-X16"}],"explanation":["돌려줌이에요.","빌려줌이에요.","못 쓰게 함이 훼손이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#6','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C25',1,'mc','auto','다흰이의 「운동장에 그네가 하나 더 있으면 좋겠어요.」에 드러난 문제점은 무엇인가요?',ARRAY['K5-1-u5-X31','K5-1-u5-X28','K5-1-u5-X26']::text[],false,'{"seq":6,"concept":"K5-1-u5-C25","difficulty":1,"kind":"mc","stem":"다흰이의 「운동장에 그네가 하나 더 있으면 좋겠어요.」에 드러난 문제점은 무엇인가요?","options":[{"t":"주제와 관련 없는 의견을 냈다","correct":true},{"t":"이유 없이 반대했다","mis":"K5-1-u5-X31"},{"t":"말을 끊었다","mis":"K5-1-u5-X28"},{"t":"사람을 탓했다","mis":"K5-1-u5-X26"}],"explanation":["반대가 아니에요.","끊지 않았어요.","놀이 상자 이야기가 아니에요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"오늘은 놀이 상자를 오래 잘 쓰는 방법을 토의해요. 의견을 말해 주세요."},{"who":"단아","text":"요일마다 모둠이 돌아가며 쓰면 좋겠어요. 모두 한 번씩은 쓸 수 있으니까요."},{"who":"휘서","text":"그건 안 돼요. 그냥 싫어요."},{"who":"해찬","text":"휘서는 맨날 공만 독차지하잖아. 그러니까 그런 말을 하지."},{"who":"다흰","text":"저는 운동장에 그네가 하나 더 있으면 좋겠어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#7','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C37',1,'mc','auto','주제 후보 ㉣이 토의 주제로 알맞지 않은 까닭은 무엇인가요?',ARRAY['K5-1-u5-X37','K5-1-u5-X46']::text[],false,'{"seq":7,"concept":"K5-1-u5-C37","difficulty":1,"kind":"mc","stem":"주제 후보 ㉣이 토의 주제로 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"저마다 좋아하는 것을 묻는 질문이라 함께 방법을 모을 거리가 없기 때문이다","correct":true},{"t":"답이 너무 많아 좋은 토의가 되기 때문이다","mis":"K5-1-u5-X37"},{"t":"우리 반과 관계없기 때문이다","mis":"K5-1-u5-X46"},{"t":"놀이는 토의할 수 없기 때문이다","mis":"K5-1-u5-X37"}],"explanation":["취향은 견줄 거리가 아니에요.","관계없지는 않아요.","취향만 묻는 질문이에요."],"asset":{"type":"passage","lines":["㉠ 우리 반 놀이 상자를 모두가 고르게 쓰는 방법","㉡ 놀이 상자에 든 줄넘기는 몇 개일까","㉢ 세상의 모든 놀이를 즐겁게 만드는 방법","㉣ 어떤 놀이가 가장 재미있을까"],"title":"보담네 모둠의 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#8','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C45',1,'mc','auto','보담네 모둠이 되돌아보기에서 정한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X45','K5-1-u5-X26']::text[],false,'{"seq":8,"concept":"K5-1-u5-C45","difficulty":1,"kind":"mc","stem":"보담네 모둠이 되돌아보기에서 정한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"다음 토의에서 고칠 점을 하나만 정하자고 했다","correct":true},{"t":"아쉬운 점을 한꺼번에 다 고치자고 했다","mis":"K5-1-u5-X45"},{"t":"되돌아볼 것은 없다고 했다","mis":"K5-1-u5-X45"},{"t":"말을 끊은 친구를 탓하자고 했다","mis":"K5-1-u5-X26"}],"explanation":["한 번에 다 고치면 안 바뀌어요.","잘한 점 · 아쉬운 점을 찾았어요.","해찬이의 말을 보아요."],"asset":{"type":"speech","turns":[{"who":"보담","text":"잘한 점은 걱정되는 점을 사람이 아니라 의견에 대해 말한 거야."},{"who":"단아","text":"아쉬운 점은 다흰이에게 차례를 늦게 넘긴 거고, 말을 끊은 것도 있었어."},{"who":"해찬","text":"그럼 다음 토의에서는 무엇부터 고칠지 하나만 정하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#9','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C50',2,'mc','auto','「낫」 · 「낮」 · 「낟」처럼 글자는 다른데 소리가 같아지는 까닭은 무엇인가요?',ARRAY['K5-1-u5-X50','K5-1-u5-X53']::text[],false,'{"seq":9,"concept":"K5-1-u5-C50","difficulty":2,"kind":"mc","stem":"「낫」 · 「낮」 · 「낟」처럼 글자는 다른데 소리가 같아지는 까닭은 무엇인가요?","options":[{"t":"받침이 모두 대표 소리 [ㄷ]으로 나기 때문이다","correct":true},{"t":"세 낱말의 뜻이 같기 때문이다","mis":"K5-1-u5-X50"},{"t":"받침을 쓰지 않기 때문이다","mis":"K5-1-u5-X50"},{"t":"받침이 [ㅂ]으로 나기 때문이다","mis":"K5-1-u5-X53"}],"explanation":["뜻은 서로 달라요.","받침은 있어요.","ㅅ · ㅈ · ㄷ은 모두 [ㄷ]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#10','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C3',2,'mc','auto','두 글을 읽은 단아가 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X03']::text[],false,'{"seq":10,"concept":"K5-1-u5-C3","difficulty":2,"kind":"mc","stem":"두 글을 읽은 단아가 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"두 글의 내용이 우리 반 상황에 맞는지 견주어 판단한다","correct":true},{"t":"먼저 읽은 글을 그대로 따른다","mis":"K5-1-u5-X03"},{"t":"나중에 읽은 글만 믿는다","mis":"K5-1-u5-X03"},{"t":"두 글을 모두 무시한다","mis":"K5-1-u5-X03"}],"explanation":["그대로 따르면 안 돼요.","읽은 차례는 기준이 아니에요.","견주어 보고 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#11','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C9',2,'mc','auto','해찬이가 텅 빈 놀이 상자 사진을 실은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X09','K5-1-u5-X19','K5-1-u5-X37']::text[],false,'{"seq":11,"concept":"K5-1-u5-C9","difficulty":2,"kind":"mc","stem":"해찬이가 텅 빈 놀이 상자 사진을 실은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"도구가 제대로 돌아오지 않는 문제를 보여 주려고","correct":true},{"t":"놀이 상자를 자랑하려고","mis":"K5-1-u5-X09"},{"t":"사진이 예뻐서","mis":"K5-1-u5-X19"},{"t":"공기놀이가 가장 재미있다는 것을 알리려고","mis":"K5-1-u5-X37"}],"explanation":["자랑하는 사진이 아니에요.","예쁜지는 기준이 아니에요.","글의 관점을 뒷받침해요."],"asset":{"type":"passage","lines":["글 ㉮의 사진 — 줄넘기를 함께 넘으며 웃는 친구들","글 ㉯의 사진 — 텅 빈 놀이 상자와 바닥에 흩어진 공기"],"title":"두 글에 실린 사진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#12','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C20',2,'mc','auto','세 글을 겹쳐 보고 정한 문제 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X22','K5-1-u5-X20']::text[],false,'{"seq":12,"concept":"K5-1-u5-C20","difficulty":2,"kind":"mc","stem":"세 글을 겹쳐 보고 정한 문제 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 놀이 상자를 모두가 오래 잘 쓸 수 있을까?","correct":true},{"t":"놀이 상자는 언제 생겼을까?","mis":"K5-1-u5-X22"},{"t":"놀이 상자 덕분에 쉬는 시간이 즐겁다","mis":"K5-1-u5-X20"},{"t":"놀이 상자 속 공기는 몇 개일까?","mis":"K5-1-u5-X22"}],"explanation":["사실 확인이에요.","글 ㉮ 하나의 내용이에요.","세 글을 겹쳐 「어떻게 하면」으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#13','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C31',2,'mc','auto','휘서가 단아의 의견에 반대하고 싶을 때 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u5-X31','K5-1-u5-X26']::text[],false,'{"seq":13,"concept":"K5-1-u5-C31","difficulty":2,"kind":"mc","stem":"휘서가 단아의 의견에 반대하고 싶을 때 알맞은 말은 어느 것인가요?","options":[{"t":"「돌아가며 쓰면 도구가 다 돌아왔는지 모를까 봐 걱정돼요.」","correct":true},{"t":"「그건 안 돼요. 그냥 싫어요.」","mis":"K5-1-u5-X31"},{"t":"「반대하면 다투니까 그냥 따를게요.」","mis":"K5-1-u5-X31"},{"t":"「단아는 늘 그런 말만 해요.」","mis":"K5-1-u5-X26"}],"explanation":["이유가 없어요.","반대도 할 수 있어요.","걱정되는 점을 이유로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#14','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C42',2,'mc','auto','단아의 「요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요.」가 보여 주는 것은 무엇인가요?',ARRAY['K5-1-u5-X42','K5-1-u5-X31','K5-1-u5-X32']::text[],false,'{"seq":14,"concept":"K5-1-u5-C42","difficulty":2,"kind":"mc","stem":"단아의 「요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요.」가 보여 주는 것은 무엇인가요?","options":[{"t":"토의는 하나를 고르는 투표가 아니라 좋은 점을 합칠 수 있다는 것","correct":true},{"t":"가장 먼저 나온 의견이 이긴다는 것","mis":"K5-1-u5-X42"},{"t":"반대 의견은 버린다는 것","mis":"K5-1-u5-X31"},{"t":"사회자만 결론을 낸다는 것","mis":"K5-1-u5-X32"}],"explanation":["이기고 지는 일이 아니에요.","걱정도 반영했어요.","단아는 사회자가 아니에요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#15','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C44',2,'mc','auto','옆 모둠이 「도구마다 번호 스티커를 붙인다」는 의견을 발표했을 때 보담네가 할 일은 무엇인가요?',ARRAY['K5-1-u5-X44','K5-1-u5-X03']::text[],false,'{"seq":15,"concept":"K5-1-u5-C44","difficulty":2,"kind":"mc","stem":"옆 모둠이 「도구마다 번호 스티커를 붙인다」는 의견을 발표했을 때 보담네가 할 일은 무엇인가요?","options":[{"t":"우리 의견에 보탤 점이 없는지 살핀다","correct":true},{"t":"우리 의견이 더 낫다는 까닭만 찾는다","mis":"K5-1-u5-X44"},{"t":"이미 정했으니 듣지 않는다","mis":"K5-1-u5-X44"},{"t":"곧바로 우리 의견을 버린다","mis":"K5-1-u5-X03"}],"explanation":["이기려고 듣지 않아요.","들어야 보탤 수 있어요.","견주어 보고 보태요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#16','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C32',2,'mc','auto','보담네 다시 한 토의에서 사회자가 아닌데도 토의를 앞으로 이끈 사람은 누구인가요?',ARRAY['K5-1-u5-X32','K5-1-u5-X31','K5-1-u5-X25']::text[],false,'{"seq":16,"concept":"K5-1-u5-C32","difficulty":2,"kind":"mc","stem":"보담네 다시 한 토의에서 사회자가 아닌데도 토의를 앞으로 이끈 사람은 누구인가요?","options":[{"t":"두 의견을 합치자고 말한 단아","correct":true},{"t":"아무도 없다 — 사회자만 이끌 수 있다","mis":"K5-1-u5-X32"},{"t":"걱정을 하나도 말하지 않은 친구","mis":"K5-1-u5-X31"},{"t":"주제와 관련 없는 말을 한 친구","mis":"K5-1-u5-X25"}],"explanation":["사회자만의 일이 아니에요.","걱정을 말해도 협력이에요.","합치자는 말이 결론으로 이끌었어요."],"asset":{"type":"speech","turns":[{"who":"휘서","text":"요일마다 돌아가며 쓰는 건 좋은데, 도구가 다 돌아왔는지 모를까 봐 걱정돼요."},{"who":"보담","text":"좋은 지적이에요. 돌려놓는 문제를 함께 생각해 봅시다."},{"who":"해찬","text":"놀이 도우미가 종이 울리면 개수를 세면 어때요? 이미 있는 역할이라 새로 만들지 않아도 돼요."},{"who":"단아","text":"그럼 요일마다 돌아가며 쓰되, 놀이 도우미가 개수를 세는 걸로 합쳐요."},{"who":"다흰","text":"좋아요. 다음 주에 한번 해 보고 다시 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#17','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C13',3,'mc','auto','다흰이의 글만 읽은 친구와 두 글을 모두 읽은 친구를 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u5-X13','K5-1-u5-X15','K5-1-u5-X04']::text[],false,'{"seq":17,"concept":"K5-1-u5-C13","difficulty":3,"kind":"mc","stem":"다흰이의 글만 읽은 친구와 두 글을 모두 읽은 친구를 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 글을 모두 읽은 친구가 문제까지 알아 더 나은 방법을 찾기 쉽다","correct":true},{"t":"한 글만 읽은 친구가 덜 헷갈려 더 잘 안다","mis":"K5-1-u5-X13"},{"t":"두 친구가 아는 것은 똑같다","mis":"K5-1-u5-X15"},{"t":"많이 읽은 친구가 토의에서 이긴다","mis":"K5-1-u5-X04"}],"explanation":["덜 헷갈리는 게 아니라 덜 알아요.","아는 면이 달라요.","이기려고 읽지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#18','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C21',3,'mc','auto','다흰이의 글이 마음에 든 휘서가 놀이 상자를 칭찬하는 글만 더 모았다면 생길 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X21','K5-1-u5-X19','K5-1-u5-X05']::text[],false,'{"seq":18,"concept":"K5-1-u5-C21","difficulty":3,"kind":"mc","stem":"다흰이의 글이 마음에 든 휘서가 놀이 상자를 칭찬하는 글만 더 모았다면 생길 일로 알맞은 것은 어느 것인가요?","options":[{"t":"도구가 줄어드는 문제가 보이지 않아 그대로 남는다","correct":true},{"t":"문제가 저절로 풀린다","mis":"K5-1-u5-X21"},{"t":"더 믿을 만한 결론이 나온다","mis":"K5-1-u5-X19"},{"t":"토의할 필요가 없어진다","mis":"K5-1-u5-X05"}],"explanation":["모르는 문제는 풀리지 않아요.","같은 편이라 믿을 만한 건 아니에요.","다른 관점 글이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#19','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C33',3,'mc','auto','다흰이와 해찬이의 글이 보담네 토의 주제를 정하는 데 한 몫으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u5-X33']::text[],false,'{"seq":19,"concept":"K5-1-u5-C33","difficulty":3,"kind":"mc","stem":"다흰이와 해찬이의 글이 보담네 토의 주제를 정하는 데 한 몫으로 알맞은 것은 어느 것인가요?","options":[{"t":"글을 살펴보다가 함께 이야기할 거리가 드러나게 했다","correct":true},{"t":"토의 주제를 대신 정해 주었다","mis":"K5-1-u5-X33"},{"t":"토의할 필요를 없앴다","mis":"K5-1-u5-X33"},{"t":"글자 수로 주제를 정하게 했다","mis":"K5-1-u5-X33"}],"explanation":["주제는 모둠이 정했어요.","읽고 나서 토의했어요.","자료가 이야깃거리를 드러내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#20','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C34',3,'mc','auto','공익 광고 「혼자서는 그늘이 되지 못합니다」를 놀이 상자 토의에 쓸 때 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u5-X34','K5-1-u5-X32','K5-1-u5-X33']::text[],false,'{"seq":20,"concept":"K5-1-u5-C34","difficulty":3,"kind":"mc","stem":"공익 광고 「혼자서는 그늘이 되지 못합니다」를 놀이 상자 토의에 쓸 때 알맞은 말은 어느 것인가요?","options":[{"t":"「한 사람만 애쓰기보다 모두가 조금씩 지키면 놀이 상자가 오래가요.」","correct":true},{"t":"「나무를 심어 운동장에 그늘을 만들어요.」","mis":"K5-1-u5-X34"},{"t":"「놀이 도우미 혼자 다 하면 돼요.」","mis":"K5-1-u5-X32"},{"t":"「광고는 토의와 관계없어요.」","mis":"K5-1-u5-X33"}],"explanation":["글자 그대로의 나무가 아니에요.","혼자서는 그늘이 못 돼요.","함께 모이는 힘을 옮겨 써요."],"asset":{"type":"passage","lines":["화면 — 빈 손바닥 여럿이 모여 한 그루 나무 모양을 이룬다.","적힌 글 — 혼자서는 그늘이 되지 못합니다."],"title":"공익 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#21','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C52',3,'mc','auto','「빛」 · 「솥」 · 「엿」을 소리 내어 읽은 것으로 바른 것은 어느 것인가요?',ARRAY['K5-1-u5-X50','K5-1-u5-X53','K5-1-u5-X51']::text[],false,'{"seq":21,"concept":"K5-1-u5-C52","difficulty":3,"kind":"mc","stem":"「빛」 · 「솥」 · 「엿」을 소리 내어 읽은 것으로 바른 것은 어느 것인가요?","options":[{"t":"[빋] · [솓] · [엳]","correct":true},{"t":"[빛] · [솥] · [엿]","mis":"K5-1-u5-X50"},{"t":"[빕] · [솝] · [엽]","mis":"K5-1-u5-X53"},{"t":"[빅] · [속] · [역]","mis":"K5-1-u5-X51"}],"explanation":["쓴 글자대로 나지 않아요.","[ㅂ]이 아니에요.","ㅊ · ㅌ · ㅅ은 모두 [ㄷ]이에요."],"asset":{"type":"passage","lines":["밭 · 숲 · 빛 · 낫 · 짚 · 동녘 · 잎 · 엿"],"title":"받침 낱말 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#22','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C48',3,'mc','auto','보담네가 다음 토의를 위해 준비할 것으로 알맞게 묶은 것은 어느 것인가요?',ARRAY['K5-1-u5-X48','K5-1-u5-X27','K5-1-u5-X39']::text[],false,'{"seq":22,"concept":"K5-1-u5-C48","difficulty":3,"kind":"mc","stem":"보담네가 다음 토의를 위해 준비할 것으로 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"의견과 이유 · 자료와 출처 · 협력 계획 · 차례와 시간","correct":true},{"t":"반박거리 · 미리 정한 결론","mis":"K5-1-u5-X48"},{"t":"의견만 · 이유는 그때 생각하기","mis":"K5-1-u5-X27"},{"t":"자료만 · 출처는 빼기","mis":"K5-1-u5-X39"}],"explanation":["이길 거리는 준비물이 아니에요.","이유도 미리 준비해요.","출처도 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#23','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C23',4,'essay','teacher','보담네 모둠의 의견 ㉢과 ㉣이 알맞은 해결 방법이 아닌 까닭을 각각 쓰고, 누구나 꾸준히 할 수 있는 다른 해결 방법을 하나 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u5-C23","difficulty":4,"kind":"essay","stem":"보담네 모둠의 의견 ㉢과 ㉣이 알맞은 해결 방법이 아닌 까닭을 각각 쓰고, 누구나 꾸준히 할 수 있는 다른 해결 방법을 하나 쓰세요.","answer_guide":{"answer":"예: ㉢은 이름을 칠판에 적어 친구에게 창피를 주므로 새 문제를 만든다. ㉣은 문제를 고치는 대신 모두가 놀이 상자를 쓰지 못하게 한다. 다른 방법 — 종이 울리면 모둠마다 쓴 도구를 함께 확인하고 넣는다. 누구나 할 수 있고 이미 하는 정리 시간에 붙여 꾸준히 이어 갈 수 있다.","scoring_points":["㉢이 알맞지 않은 까닭을 썼는가","㉣이 알맞지 않은 까닭을 썼는가","누구나 꾸준히 할 수 있는 방법을 썼는가"]},"explanation":["창피를 주면?","없애면 해결일까요?","누구나 · 꾸준히 · 새 문제 없이."],"asset":{"type":"passage","lines":["의견 ㉠ — 요일마다 모둠이 돌아가며 쓴다","의견 ㉡ — 놀이 도우미가 종이 울리면 개수를 센다","의견 ㉢ — 돌려놓지 않은 사람의 이름을 칠판에 적는다","의견 ㉣ — 놀이 상자를 치운다"],"title":"보담네 모둠에서 나온 의견"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#24','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C50',4,'essay','teacher','받침의 대표 소리 [ㄱ] · [ㄷ] · [ㅂ]으로 나는 받침을 각각 쓰고, 「동녘」 · 「낫」 · 「짚」의 발음과 함께 소리가 같아도 원래 글자로 써야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u5-C50","difficulty":4,"kind":"essay","stem":"받침의 대표 소리 [ㄱ] · [ㄷ] · [ㅂ]으로 나는 받침을 각각 쓰고, 「동녘」 · 「낫」 · 「짚」의 발음과 함께 소리가 같아도 원래 글자로 써야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: [ㄱ] — ㄱ · ㄲ · ㅋ, [ㄷ] — ㅅ · ㅆ · ㅈ · ㅊ · ㅌ · ㄷ, [ㅂ] — ㅂ · ㅍ. 동녘은 [동녁], 낫은 [낟], 짚은 [집]으로 읽는다. 「낫」 · 「낮」 · 「낟」처럼 소리가 같은 낱말이 많아 소리 나는 대로 쓰면 뜻을 가를 수 없으므로 원래 글자로 쓴다.","scoring_points":["세 대표 소리의 받침을 썼는가","세 낱말의 발음을 바르게 썼는가","원래 글자로 쓰는 까닭을 썼는가"]},"explanation":["받침을 셋으로 묶어요.","각 낱말의 받침은?","소리대로 쓰면 무엇이 헷갈릴까요?"],"asset":{"type":"passage","lines":["밭 · 숲 · 빛 · 낫 · 짚 · 동녘 · 잎 · 엿"],"title":"받침 낱말 모음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u5_review_d#25','kor',5,1,'u5','','g5_1_kor_u5_review_d','unit_review','K5-1-u5-C12',4,'essay','teacher','「관점은 맞고 틀림이 아니라 서로 다름이다」라는 생각이 토의에서 왜 중요한지, 다흰이와 해찬이가 한 모둠에서 토의한다고 생각하고 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u5-C12","difficulty":4,"kind":"essay","stem":"「관점은 맞고 틀림이 아니라 서로 다름이다」라는 생각이 토의에서 왜 중요한지, 다흰이와 해찬이가 한 모둠에서 토의한다고 생각하고 쓰세요.","answer_guide":{"answer":"예: 다흰이는 놀이 상자의 좋은 점을, 해찬이는 문제점을 중요하게 본다. 서로 틀렸다고 여기면 상대의 말을 듣지 않고 말다툼이 된다. 하지만 다름으로 받아들이면 다흰이의 생각에서 좋은 점을 살리고 해찬이의 생각에서 고칠 점을 찾아, 둘을 합친 더 나은 방법을 만들 수 있다.","scoring_points":["두 사람이 중요하게 보는 것을 썼는가","틀림으로 여길 때 생기는 일을 썼는가","다름으로 받아들일 때 토의가 나아지는 점을 썼는가"]},"explanation":["둘은 무엇을 보나요?","틀렸다고 여기면?","다르다고 여기면?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
